def utc_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def read_json(path: Path) -> Any:
    return json.loads(read_text_with_retries(path))


def read_jsonl(path: Path) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    try:
        lines = iter_text_lines_with_retries(path)
        for line in lines:
            if line.strip():
                rows.append(json.loads(line))
        return rows
    except TimeoutError:
        rows = []
    for line in iter_text_lines_with_retries(path, max_timeout_retries=240):
        if line.strip():
            rows.append(json.loads(line))
    return rows


def jsonl_row_count(path: Path) -> int:
    try:
        return count_nonblank_binary_lines_with_retries(path)
    except TimeoutError:
        return sum(
            1
            for line in iter_text_lines_with_retries(
                path,
                max_timeout_retries=240,
            )
            if line.strip()
        )


def jsonl_row_count_and_truthy_fields(
    path: Path,
    fields: Iterable[str],
) -> dict[str, Any]:
    counts = Counter()
    truthy_fields: Counter[str] = Counter()
    try:
        lines = iter_text_lines_with_retries(path)
        for line in lines:
            if not line.strip():
                continue
            row = json.loads(line)
            counts["rows"] += 1
            for field in fields:
                if row.get(field):
                    truthy_fields[field] += 1
    except TimeoutError:
        lines = iter_text_lines_with_retries(path, max_timeout_retries=240)
        for line in lines:
            if not line.strip():
                continue
            row = json.loads(line)
            counts["rows"] += 1
            for field in fields:
                if row.get(field):
                    truthy_fields[field] += 1
    return {
        "row_count": int(counts["rows"]),
        "truthy_fields": json_safe_counter(truthy_fields),
    }


def summary_row_count_and_boundary_fields(
    summary: Mapping[str, Any],
    *,
    row_count_field: str,
    fields: Iterable[str],
    authority: str,
) -> dict[str, Any]:
    row_count = int(summary.get(row_count_field) or 0)
    truthy_fields: Counter[str] = Counter()
    for field in fields:
        if summary.get(field):
            truthy_fields[field] = row_count
    return {
        "row_count": row_count,
        "truthy_fields": json_safe_counter(truthy_fields),
        "row_count_authority": authority,
    }


def denominator_bridge_stream_stats(path: Path) -> dict[str, Any]:
    counts = Counter()
    selected_windows: set[str] = set()
    label_match_windows: set[str] = set()
    matched_member_axes: set[str] = set()
    truthy_fields: Counter[str] = Counter()
    boundary_fields = (
        "training_use_allowed",
        "final_package_selection_allowed",
        "broker_mutation",
        "paid_api_call",
        "remote_push",
    )

    def consume(row: Mapping[str, Any]) -> None:
        counts["rows"] += 1
        selected = row.get("selected_package_replay_row") is True
        if selected:
            counts["selected_package_replay_rows"] += 1
            window = row.get("stable_decision_window_id")
            if window:
                selected_windows.add(str(window))
            if row.get("stable_decision_window_label_match") is True and window:
                label_match_windows.add(str(window))
        if row.get("selected_package_denominator_use_allowed") is True:
            counts["selected_package_denominator_use_allowed_rows"] += 1
        for source_axis_row_index in row.get("matched_source_axis_row_indexes") or []:
            matched_member_axes.add(str(source_axis_row_index))
        for field in boundary_fields:
            if row.get(field):
                truthy_fields[field] += 1

    try:
        lines = iter_text_lines_with_retries(path)
        for line in lines:
            if line.strip():
                consume(json.loads(line))
    except TimeoutError:
        for line in iter_text_lines_with_retries(path, max_timeout_retries=240):
            if line.strip():
                consume(json.loads(line))
    return {
        "row_count": int(counts["rows"]),
        "selected_package_replay_rows": int(
            counts["selected_package_replay_rows"]
        ),
        "selected_package_denominator_use_allowed_rows": int(
            counts["selected_package_denominator_use_allowed_rows"]
        ),
        "selected_windows": selected_windows,
        "label_match_windows": label_match_windows,
        "matched_member_axes": matched_member_axes,
        "truthy_fields": json_safe_counter(truthy_fields),
    }


def json_artifact_readable(path: Path) -> bool:
    if not path.exists() or path.stat().st_size <= 0:
        return False
    try:
        json.loads(read_text_with_retries(path))
    except (json.JSONDecodeError, OSError, TimeoutError):
        return False
    return True


def read_json_if_readable(path: Path) -> dict[str, Any]:
    if not path.exists() or path.stat().st_size <= 0:
        return {}
    try:
        payload = json.loads(read_text_with_retries(path))
    except (json.JSONDecodeError, OSError, TimeoutError):
        return {}
    return payload if isinstance(payload, dict) else {}


def numeric_or_none(value: Any) -> float | None:
    if isinstance(value, bool):
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def read_jsonl_if_readable(path: Path) -> list[dict[str, Any]]:
    if not path.exists() or path.stat().st_size <= 0:
        return []
    try:
        return read_jsonl(path)
    except (json.JSONDecodeError, OSError, TimeoutError):
        return []


class JsonlRowStream:
    """Re-iterable JSONL stream for very large verifier inputs.

    The verifier only needs a single pass over some multi-GB ledgers. Keeping
    those rows in memory makes the route verifier vulnerable to host memory
    pressure, so this object provides list-like iteration and a trusted row
    count without materializing the payload.
    """

    def __init__(self, path: Path, *, row_count: int | None = None) -> None:
        self.path = path
        self._row_count = row_count

    def __iter__(self):
        if not self.path.exists() or self.path.stat().st_size <= 0:
            return
        for line in iter_text_lines_with_retries(self.path):
            if line.strip():
                yield json.loads(line)

    def __len__(self) -> int:
        if self._row_count is None:
            raise TypeError(
                "JsonlRowStream length is unknown; pass row_count when constructing "
                "the stream or call jsonl_row_count(path) explicitly"
            )
        return int(self._row_count or 0)


def stream_jsonl_rows_if_readable(
    path: Path,
    *,
    row_count: int | None = None,
) -> JsonlRowStream | list[dict[str, Any]]:
    if not path.exists() or path.stat().st_size <= 0:
        return []
    return JsonlRowStream(path, row_count=row_count)


REPLAY_BRIDGE_COMPLETED_STATUSES = {
    "completed",
    "completed_candidate_replay_no_terminal_execution",
}


def replay_bridge_candidate_replay_completed(summary: Mapping[str, Any]) -> bool:
    return str(summary.get("status") or "").strip() in REPLAY_BRIDGE_COMPLETED_STATUSES


def read_text_with_retries(path: Path) -> str:
    materialize_file_provider_artifact(path)
    for attempt in range(3):
        try:
            return path.read_text(encoding="utf-8")
        except TimeoutError as exc:
            materialized = materialize_file_provider_artifact(path, force=True)
            if attempt >= 2:
                raise TimeoutError(
                    f"timed out reading route artifact {path}; "
                    f"materialization_attempted={materialized}"
                ) from exc
            time.sleep(0.25)
    return ""


_FILE_PROVIDER_MATERIALIZED_PATHS: set[str] = set()
FILE_PROVIDER_MATERIALIZE_TIMEOUT_RETRIES = int(
    os.environ.get("GTOS_FILE_PROVIDER_MATERIALIZE_TIMEOUT_RETRIES", "8")
)
FILE_PROVIDER_MATERIALIZE_RETRY_SLEEP_SECONDS = float(
    os.environ.get("GTOS_FILE_PROVIDER_MATERIALIZE_RETRY_SLEEP_SECONDS", "2.0")
)
FILE_PROVIDER_MATERIALIZE_COMMAND_TIMEOUT_SECONDS = float(
    os.environ.get("GTOS_FILE_PROVIDER_MATERIALIZE_COMMAND_TIMEOUT_SECONDS", "15.0")
)
FILE_PROVIDER_DATALESS_MIN_BYTES = int(
    os.environ.get("GTOS_FILE_PROVIDER_DATALESS_MIN_BYTES", "1000000")
)


class RouteArtifactMaterializationError(TimeoutError):
    """Raised when a required route artifact is present but not locally readable."""


def route_artifact_is_dataless_placeholder(stat_result: os.stat_result) -> bool:
    """Return true for large route artifacts with no local data blocks."""

    return (
        int(getattr(stat_result, "st_size", 0) or 0)
        >= FILE_PROVIDER_DATALESS_MIN_BYTES
        and int(getattr(stat_result, "st_blocks", 1) or 0) == 0
    )


def route_artifact_has_no_local_data_blocks(stat_result: os.stat_result) -> bool:
    return (
        int(getattr(stat_result, "st_size", 0) or 0) > 0
        and int(getattr(stat_result, "st_blocks", 1) or 0) == 0
    )


def route_artifact_read_probe_succeeds(path: Path) -> bool:
    """Return true when a dataless-looking route artifact can be read."""

    try:
        with path.open("rb") as handle:
            handle.read(1)
        return True
    except (AttributeError, OSError, TimeoutError):
        return False


def materialize_file_provider_artifact(path: Path, *, force: bool = False) -> bool:
    """Ask macOS/iCloud to hydrate dataless route artifacts before streaming."""

    path_key = str(path)
    if not force and path_key in _FILE_PROVIDER_MATERIALIZED_PATHS:
        return False
    try:
        stat_result = path.stat()
    except OSError:
        return False
    if not route_artifact_has_no_local_data_blocks(stat_result):
        return False
    timeout_exc: TimeoutError | None = None
    for attempt in range(1, FILE_PROVIDER_MATERIALIZE_TIMEOUT_RETRIES + 1):
        command_error: str | None = None
        brctl = Path("/usr/bin/brctl")
        if brctl.exists():
            try:
                subprocess.run(
                    [str(brctl), "download", str(path)],
                    check=False,
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.PIPE,
                    text=True,
                    timeout=FILE_PROVIDER_MATERIALIZE_COMMAND_TIMEOUT_SECONDS,
                )
            except (OSError, subprocess.TimeoutExpired) as exc:
                command_error = f"{type(exc).__name__}:{exc}"
        try:
            refreshed_stat = path.stat()
        except OSError:
            return False
        if not route_artifact_has_no_local_data_blocks(refreshed_stat):
            _FILE_PROVIDER_MATERIALIZED_PATHS.add(path_key)
            return True
        if route_artifact_read_probe_succeeds(path):
            _FILE_PROVIDER_MATERIALIZED_PATHS.add(path_key)
            return True
        timeout_exc = RouteArtifactMaterializationError(
            f"route_artifact_dataless_not_materialized:{path}:"
            f"size={getattr(refreshed_stat, 'st_size', None)}:"
            f"blocks={getattr(refreshed_stat, 'st_blocks', None)}:"
            f"attempt={attempt}:command_error={command_error or 'none'}"
        )
        if attempt >= FILE_PROVIDER_MATERIALIZE_TIMEOUT_RETRIES:
            break
        time.sleep(FILE_PROVIDER_MATERIALIZE_RETRY_SLEEP_SECONDS)
    raise RouteArtifactMaterializationError(
        f"timed out materializing route artifact {path} after "
        f"{FILE_PROVIDER_MATERIALIZE_TIMEOUT_RETRIES} hydration attempt(s); "
        "artifact remains dataless and cannot be used as deterministic proof"
    ) from timeout_exc


def iter_binary_text_lines_with_retries(
    path: Path,
    *,
    chunk_size: int = 4 * 1024 * 1024,
    max_timeout_retries: int = 120,
):
    """Stream large JSONL files without TextIOWrapper.readline() stalls."""

    materialize_file_provider_artifact(path)
    pending = b""
    timeout_retries = 0
    offset = 0
    while True:
        with path.open("rb") as handle:
            seek = getattr(handle, "seek", None)
            seekable_stream = callable(seek)
            if seekable_stream:
                seek(offset)
            elif offset:
                raise OSError(
                    f"route artifact stream for {path} is not seekable at byte offset {offset}"
                )
            while True:
                try:
                    current_size = path.stat().st_size
                except (AttributeError, OSError):
                    current_size = None
                if current_size is not None and offset >= current_size:
                    if pending:
                        yield pending.decode("utf-8")
                    return
                try:
                    chunk = handle.read(chunk_size)
                except TimeoutError as exc:
                    timeout_retries += 1
                    materialized = materialize_file_provider_artifact(
                        path,
                        force=True,
                    )
                    if timeout_retries > max_timeout_retries:
                        raise TimeoutError(
                            f"timed out reading route artifact {path} after "
                            f"{timeout_retries} timeout(s) at byte offset {offset}; "
                            f"materialization_attempted={materialized}"
                        ) from exc
                    if not seekable_stream and timeout_retries >= 2:
                        raise TimeoutError(
                            f"timed out reading route artifact {path} after "
                            f"{timeout_retries} timeout(s) at byte offset {offset}; "
                            f"materialization_attempted={materialized}"
                        ) from exc
                    time.sleep(0.5)
                    break
                timeout_retries = 0
                if not chunk:
                    if pending:
                        yield pending.decode("utf-8")
                    return
                tell = getattr(handle, "tell", None)
                offset = int(tell()) if callable(tell) else offset + len(chunk)
                parts = chunk.splitlines(keepends=True)
                if pending:
                    parts[0] = pending + parts[0]
                    pending = b""
                if parts and not parts[-1].endswith((b"\n", b"\r")):
                    pending = parts.pop()
                for raw_line in parts:
                    yield raw_line.decode("utf-8")


def count_nonblank_binary_lines_with_retries(
    path: Path,
    *,
    chunk_size: int = 8 * 1024 * 1024,
    max_timeout_retries: int = 120,
) -> int:
    """Count nonblank JSONL rows without decoding or forking over large ledgers."""

    materialize_file_provider_artifact(path)
    pending = b""
    row_count = 0
    timeout_retries = 0
    offset = 0
    while True:
        with path.open("rb") as handle:
            seek = getattr(handle, "seek", None)
            seekable_stream = callable(seek)
            if seekable_stream:
                seek(offset)
            elif offset:
                raise OSError(
                    f"route artifact stream for {path} is not seekable at byte offset {offset}"
                )
            while True:
                try:
                    current_size = path.stat().st_size
                except (AttributeError, OSError):
                    current_size = None
                if current_size is not None and offset >= current_size:
                    if pending.strip():
                        row_count += 1
                    return row_count
                try:
                    chunk = handle.read(chunk_size)
                except TimeoutError as exc:
                    timeout_retries += 1
                    materialized = materialize_file_provider_artifact(
                        path,
                        force=True,
                    )
                    if timeout_retries > max_timeout_retries:
                        raise TimeoutError(
                            f"timed out counting route artifact {path} after "
                            f"{timeout_retries} timeout(s) at byte offset {offset}; "
                            f"materialization_attempted={materialized}"
                        ) from exc
                    if not seekable_stream and timeout_retries >= 2:
                        raise TimeoutError(
                            f"timed out counting route artifact {path} after "
                            f"{timeout_retries} timeout(s) at byte offset {offset}; "
                            f"materialization_attempted={materialized}"
                        ) from exc
                    time.sleep(0.5)
                    break
                timeout_retries = 0
                if not chunk:
                    if pending.strip():
                        row_count += 1
                    return row_count
                tell = getattr(handle, "tell", None)
                offset = int(tell()) if callable(tell) else offset + len(chunk)
                if pending:
                    chunk = pending + chunk
                    pending = b""
                parts = chunk.splitlines(keepends=True)
                if parts and not parts[-1].endswith((b"\n", b"\r")):
                    pending = parts.pop()
                for raw_line in parts:
                    if raw_line.strip():
                        row_count += 1


TEXT_LINE_BINARY_STREAM_MIN_BYTES = 1
BROAD_QUALITY_ROW_COUNT_PHYSICAL_SCAN_MAX_BYTES = 1_000_000


def iter_text_lines_with_retries(
    path: Path,
    *,
    max_timeout_retries: int = 1200,
):
    path_size = path.stat().st_size if path.exists() else 0
    if path_size >= TEXT_LINE_BINARY_STREAM_MIN_BYTES:
        for line in iter_binary_text_lines_with_retries(
            path,
            max_timeout_retries=max_timeout_retries,
        ):
            yield line
        return
    with path.open("r", encoding="utf-8") as handle:
        timeout_retries = 0
        while True:
            try:
                line = handle.readline()
            except TimeoutError:
                timeout_retries += 1
                if timeout_retries > max_timeout_retries:
                    raise
                time.sleep(0.5)
                continue
            if line == "":
                break
            timeout_retries = 0
            yield line


class ExactRelationalCandidateSource:
    """Reconstruct one candidate row per exact terminal candidate instance."""

    def __init__(self, paths: Sequence[Path]) -> None:
        self.paths = tuple(paths)
        self.name = "EXACT_MISSED_ORDER_TRADE_RELATIONAL_CANDIDATE_SURFACE"

    def exists(self) -> bool:
        return bool(self.paths) and all(path.exists() for path in self.paths)

    def __iter__(self) -> Iterable[Mapping[str, Any]]:
        seen: set[str] = set()
        for path in self.paths:
            for row_number, line in enumerate(
                iter_text_lines_with_retries(path),
                start=1,
            ):
                if not line.strip():
                    continue
                row = json.loads(line)
                if not isinstance(row, Mapping):
                    continue
                profile = str(
                    row.get("profile") or row.get("broad_replay_profile") or ""
                ).strip()
                instance_key = str(
                    row.get("canonical_replay_candidate_instance_key") or ""
                ).strip()
                key = (
                    f"{profile}@@{instance_key}"
                    if instance_key
                    else f"missing@@{path.name}@@{row_number}"
                )
                if key in seen:
                    continue
                seen.add(key)
                yield row

    def __str__(self) -> str:
        return self.name + ":" + "|".join(str(path) for path in self.paths)


def replay_row_source_exists(source: Any) -> bool:
    if isinstance(source, Path):
        return source.exists()
    exists = getattr(source, "exists", None)
    if callable(exists):
        return bool(exists())
    return isinstance(source, Iterable) and not isinstance(
        source,
        (str, bytes, bytearray, Mapping),
    )


def scan_broad_candidate_quality_parity(source: Any) -> dict[str, Any]:
    required = (
        "probability",
        "candidate_probability",
        "ev_r",
        "candidate_ev_r",
        "expected_cost_r",
        "cost_r",
        "expected_net_r",
        "candidate_expected_net_r",
        "fill_probability",
        "source_completeness",
        "source_completeness_status",
        "candidate_decision_quality_field_sources",
        "candidate_decision_quality_source_boundary",
        "source_boundary",
    )
    scheduler_required = (
        "scheduler_candidate_decision_inputs",
        "scheduler_expected_net_r",
        "scheduler_probability",
        "scheduler_fill_probability",
        "scheduler_source_completeness",
        "candidate_scheduler_quality_parity_status",
    )
    scheduler_selection_evidence = (
        "scheduler_option_status",
        "scheduler_option_score",
        "scheduler_score",
        "scheduler_rank",
        "selected_candidate_id",
        "selected_candidate_ids",
        "selected_scheduler_option_status",
        "selected_scheduler_action_class",
    )
    identity_required = (
        "canonical_replay_candidate_instance_key",
        "risk_finalizer_probe_instance_key",
        "source_bound_replay_candidate_instance_key",
        "candidate_instance_identity_status",
    )
    risk_provenance_required = (
        "risk_authority",
        "risk_authority_status",
        "risk_authority_packet_hash_sha256",
        "risk_config_source",
        "risk_per_trade_pct",
        "selected_cell_risk_pct",
        "scheduler_approved_risk_pct",
    )
    stop_hazard_required = (
        "predecision_stop_hazard_guard_status",
        "predecision_stop_hazard_guard_reason",
        "predecision_stop_hazard_guard_action",
        "predecision_stop_hazard_guard_source_boundary",
        "predecision_stop_hazard_guard_outcome_fields_used",
    )
    stop_hazard_cap_required = (
        "predecision_stop_hazard_guard_risk_cap_applied",
        "predecision_stop_hazard_guard_risk_cap_pct",
        "predecision_stop_hazard_guard_unit_risk_atr",
        "predecision_stop_hazard_guard_distance_to_limit_risk",
        "predecision_stop_hazard_guard_limit_fill_probability",
    )
    source_name = str(getattr(source, "name", ""))
    is_candidate_index = source_name.endswith("_CANDIDATE_INDEX_LEDGER.jsonl")
    counts: Counter[str] = Counter()
    missing: Counter[str] = Counter()
    scheduler_missing: Counter[str] = Counter()
    mismatches: Counter[str] = Counter()
    candidate_index_bad: Counter[str] = Counter()
    sample_missing: list[dict[str, Any]] = []
    required_field_source_keys = (
        "probability",
        "expected_net_r",
        "fill_probability",
        "source_completeness",
    )

    def _row_value(row: Mapping[str, Any], field: str) -> Any:
        value = row.get(field)
        if value not in (None, "", [], {}):
            return value
        if field == "cost_r":
            return row.get("expected_cost_r")
        if field == "expected_cost_r":
            return row.get("cost_r")
        if field == "risk_authority_status":
            risk_authority = row.get("risk_authority")
            if isinstance(risk_authority, Mapping):
                return (
                    risk_authority.get("risk_authority_status")
                    or risk_authority.get("status")
                )
        return value

    def _row_value_present(row: Mapping[str, Any], field: str) -> bool:
        return _row_value(row, field) not in (None, "", [], {})

    def _selected_cell_risk_present(row: Mapping[str, Any]) -> bool:
        if _row_value_present(row, "selected_cell_risk_pct"):
            return True
        for field in (
            "risk_per_trade_pct",
            "requested_risk_pct",
            "runtime_final_risk_pct",
            "approved_risk_pct",
            "scheduler_approved_risk_pct",
        ):
            if _row_value_present(row, field):
                return True
        ladder = row.get("risk_expression_ladder")
        ladder = ladder if isinstance(ladder, Mapping) else {}
        for field in (
            "selected_cell_risk_pct",
            "package_risk_expression_selected_cell_risk_pct_before",
            "requested_risk_pct",
        ):
            if ladder.get(field) not in (None, "", [], {}):
                return True
        return False

    def _risk_provenance_field_present(row: Mapping[str, Any], field: str) -> bool:
        if field == "selected_cell_risk_pct":
            return _selected_cell_risk_present(row)
        return _row_value_present(row, field)

    if not replay_row_source_exists(source):
        return {
            "path": str(source),
            "exists": False,
            "row_count": 0,
            "package_row_count": 0,
            "materialized_scheduler_backfill_rows": 0,
            "provisional_authority_finalized_rows": 0,
            "missing_counts": {},
            "scheduler_missing_counts": {},
            "scheduler_parity_mismatch_counts": {},
            "candidate_index_bad_counts": {},
            "sample_missing": [],
            "scan_truncated": False,
    }
    try:
        for row in _iter_broad_poi_scan_rows(source):
            counts["row_count"] += 1
            if is_candidate_index:
                for field, expected in (
                    ("row_type", "candidate_index"),
                    ("candidate_index_schema", "compact_broad_replay_candidate_index_v1"),
                    ("candidate_packet_sidecar_payload_omitted", True),
                    ("candidate_index_lossless_candidate_payload", False),
                ):
                    if row.get(field) != expected:
                        candidate_index_bad[f"{field}_mismatch"] += 1
            is_package = bool(row.get("ultimate_package_source_bound_candidate_use_allowed")) or (
                float(row.get("ultimate_package_admission_sleeve_match_count") or 0.0) > 0.0
            )
            if not is_package:
                continue
            counts["package_row_count"] += 1
            expected_cost_r = numeric_or_none(row.get("expected_cost_r"))
            cost_r = numeric_or_none(row.get("cost_r"))
            if (
                expected_cost_r is not None
                and cost_r is not None
                and not math.isclose(
                    expected_cost_r,
                    cost_r,
                    rel_tol=0.0,
                    abs_tol=1e-12,
                )
            ):
                candidate_index_bad["expected_cost_r_cost_r_alias_mismatch"] += 1
            risk_authority = row.get("risk_authority")
            nested_risk_authority_status = (
                risk_authority.get("risk_authority_status")
                or risk_authority.get("status")
                if isinstance(risk_authority, Mapping)
                else None
            )
            if (
                row.get("risk_authority_status") not in (None, "")
                and nested_risk_authority_status not in (None, "")
                and row.get("risk_authority_status")
                != nested_risk_authority_status
            ):
                candidate_index_bad["risk_authority_status_alias_mismatch"] += 1
            if row.get(
                "scheduler_materialization_provisional_authority_finalized"
            ) is True:
                counts["provisional_authority_finalized_rows"] += 1
                if (
                    row.get("ultimate_package_member_axis_evidence_class")
                    != "source_member_axis_overlap_not_additive_exact_execution_r"
                    or row.get("ultimate_package_member_axis_match_status")
                    != "exact_current_source_member_axis_match"
                ):
                    candidate_index_bad[
                        "provisional_authority_finalized_without_exact_member_axis_evidence"
                    ] += 1
                if row.get(
                    "scheduler_materialization_exact_member_axis_authority_finalization_allowed"
                ) is not True:
                    candidate_index_bad[
                        "provisional_authority_finalized_without_finalization_contract"
                    ] += 1
                if row.get(
                    "scheduler_materialization_exact_member_axis_atomic_fillability_available"
                ) is not True:
                    candidate_index_bad[
                        "provisional_authority_finalized_without_atomic_fillability"
                    ] += 1
                execution_fill_probability = numeric_or_none(
                    row.get(
                        "scheduler_materialization_exact_member_axis_execution_fill_probability"
                    )
                )
                if (
                    execution_fill_probability is None
                    or execution_fill_probability <= 0.0
                ):
                    candidate_index_bad[
                        "provisional_authority_finalized_without_positive_execution_fillability"
                    ] += 1
                if row.get("package_new_entry_authority_valid") is not True:
                    candidate_index_bad[
                        "provisional_authority_finalized_without_valid_signed_authority"
                    ] += 1
                if provisional_package_new_entry_authority_marker_paths(row):
                    candidate_index_bad[
                        "provisional_authority_finalized_with_provisional_marker_leak"
                    ] += 1
            row_missing = [
                field
                for field in required
                if not _row_value_present(row, field)
            ]
            for field in row_missing:
                missing[field] += 1
            identity_missing = [
                field
                for field in identity_required
                if row.get(field) in (None, "", [], {})
            ]
            for field in identity_missing:
                missing[field] += 1
            candidate_id = str(row.get("candidate_id") or "").strip()
            decision_time = str(
                row.get("decision_time_utc")
                or row.get("candle_close_utc")
                or row.get("source_candle_time_utc")
                or ""
            ).strip()
            if candidate_id and decision_time:
                expected_instance_key = f"{candidate_id}@@{decision_time}"
                for key_field in (
                    "canonical_replay_candidate_instance_key",
                    "risk_finalizer_probe_instance_key",
                    "source_bound_replay_candidate_instance_key",
                ):
                    if row.get(key_field) != expected_instance_key:
                        missing[f"{key_field}_mismatch"] += 1
                        identity_missing.append(f"{key_field}_mismatch")
                if row.get("candidate_instance_identity_status") != "materialized":
                    missing["candidate_instance_identity_status_not_materialized"] += 1
                    identity_missing.append("candidate_instance_identity_status_not_materialized")
            risk_missing = [
                field
                for field in risk_provenance_required
                if not _risk_provenance_field_present(row, field)
            ]
            for field in risk_missing:
                missing[field] += 1
            field_sources = row.get("candidate_decision_quality_field_sources")
            field_sources = field_sources if isinstance(field_sources, dict) else {}
            scheduler_inputs = row.get("scheduler_candidate_decision_inputs")
            scheduler_inputs = scheduler_inputs if isinstance(scheduler_inputs, dict) else {}
            confidence_present = row.get("confidence") not in (None, "", [], {}) or row.get(
                "candidate_confidence"
            ) not in (None, "", [], {})
            confidence_source_present = field_sources.get("confidence") not in (
                None,
                "",
                [],
                {},
            )
            scheduler_confidence_present = any(
                scheduler_inputs.get(field) not in (None, "", [], {})
                for field in (
                    "confidence",
                    "candidate_confidence",
                    "scheduler_confidence",
                )
            )
            confidence_required = (
                confidence_present
                or confidence_source_present
                or scheduler_confidence_present
            )
            for field in required_field_source_keys:
                if field_sources.get(field) in (None, "", [], {}):
                    missing[f"candidate_decision_quality_field_sources.{field}"] += 1
                    if len(sample_missing) < 5:
                        row_missing.append(
                            f"candidate_decision_quality_field_sources.{field}"
                        )
            if confidence_required:
                for field in ("confidence", "candidate_confidence"):
                    if row.get(field) in (None, "", [], {}):
                        missing[field] += 1
                        if len(sample_missing) < 5:
                            row_missing.append(field)
                if field_sources.get("confidence") in (None, "", [], {}):
                    missing["candidate_decision_quality_field_sources.confidence"] += 1
                    if len(sample_missing) < 5:
                        row_missing.append(
                            "candidate_decision_quality_field_sources.confidence"
                        )
            if row.get("candidate_decision_quality_alias_status") != "materialized":
                missing["candidate_decision_quality_alias_status"] += 1
                if len(sample_missing) < 5:
                    row_missing.append("candidate_decision_quality_alias_status")
            nested_quality_missing = candidate_decision_quality_missing_fields(row)
            for field in nested_quality_missing:
                missing[field] += 1
                if len(sample_missing) < 5:
                    row_missing.append(field)
            default_confidence_issues = default_confidence_provenance_issues(row)
            for issue in default_confidence_issues:
                missing[f"candidate_decision_quality.{issue}"] += 1
                if len(sample_missing) < 5:
                    row_missing.append(f"candidate_decision_quality.{issue}")
            all_missing = row_missing + identity_missing + risk_missing
            if all_missing and len(sample_missing) < 5:
                sample_missing.append(
                    {
                        "candidate_id": row.get("candidate_id"),
                        "decision_time_utc": row.get("decision_time_utc"),
                        "symbol": row.get("symbol"),
                        "missing_fields": all_missing,
                    }
                )
            scheduler_quality_required = row.get("scheduler_quality_backfill_status") == "materialized" or any(
                row.get(field) not in (None, "", [], {}) for field in scheduler_selection_evidence
            )
            if scheduler_quality_required:
                counts["materialized_scheduler_backfill_rows"] += 1
                row_scheduler_missing = [
                    field
                    for field in scheduler_required
                    if row.get(field) in (None, "", [], {})
                ]
                if confidence_required and row.get("scheduler_confidence") in (
                    None,
                    "",
                    [],
                    {},
                ):
                    row_scheduler_missing.append("scheduler_confidence")
                if row.get("scheduler_quality_backfill_status") != "materialized":
                    row_scheduler_missing.append("scheduler_quality_backfill_status")
                for field in row_scheduler_missing:
                    scheduler_missing[field] += 1
            parity_status = row.get("candidate_scheduler_quality_parity_status")
            parity_mismatches = row.get("candidate_scheduler_quality_parity_mismatches")
            parity_mismatches = (
                parity_mismatches
                if isinstance(parity_mismatches, list)
                else []
            )
            scheduler_quality_not_applicable = (
                parity_status == "not_applicable_scheduler_option_missing"
                and not scheduler_quality_required
                and not parity_mismatches
            )
            if (
                parity_status not in (None, "", "pass")
                and not scheduler_quality_not_applicable
            ) or parity_mismatches:
                for field in parity_mismatches or [parity_status or "unknown"]:
                    mismatches[str(field)] += 1
            stop_hazard_projection_present = any(
                row.get(field) not in (None, "", [], {})
                for field in (
                    "predecision_stop_hazard_guard_status",
                    "predecision_stop_hazard_guard_reason",
                    "predecision_stop_hazard_guard_action",
                    "predecision_stop_hazard_guard_risk_cap_applied",
                    "predecision_stop_hazard_guard_risk_cap_pct",
                )
            )
            if stop_hazard_projection_present:
                counts["stop_hazard_projection_rows"] += 1
                for field in stop_hazard_required:
                    if row.get(field) in (None, "", [], {}):
                        candidate_index_bad[
                            f"predecision_stop_hazard_guard_missing:{field}"
                        ] += 1
                status = str(
                    row.get("predecision_stop_hazard_guard_status") or ""
                ).strip()
                action = str(
                    row.get("predecision_stop_hazard_guard_action") or ""
                ).strip()
                if action not in {"clear", "cap", "block", "penalize"}:
                    candidate_index_bad[
                        "predecision_stop_hazard_guard_action_invalid"
                    ] += 1
                if row.get("predecision_stop_hazard_guard_outcome_fields_used") is not False:
                    candidate_index_bad[
                        "predecision_stop_hazard_guard_outcome_fields_used_not_false"
                    ] += 1
                if status == "capped":
                    for field in stop_hazard_cap_required:
                        if row.get(field) in (None, "", [], {}):
                            candidate_index_bad[
                                f"predecision_stop_hazard_guard_missing:{field}"
                            ] += 1
                    if row.get("predecision_stop_hazard_guard_risk_cap_applied") is not True:
                        candidate_index_bad[
                            "predecision_stop_hazard_guard_capped_without_risk_cap"
                        ] += 1
    except (json.JSONDecodeError, OSError, TimeoutError):
        candidate_index_bad["candidate_quality_parity_ledger_unreadable"] += 1
    return {
        "path": str(source),
        "exists": True,
        "row_count": counts["row_count"],
        "package_row_count": counts["package_row_count"],
        "materialized_scheduler_backfill_rows": counts[
            "materialized_scheduler_backfill_rows"
        ],
        "provisional_authority_finalized_rows": counts[
            "provisional_authority_finalized_rows"
        ],
        "stop_hazard_projection_rows": counts["stop_hazard_projection_rows"],
        "missing_counts": json_safe_counter(missing),
        "scheduler_missing_counts": json_safe_counter(scheduler_missing),
        "scheduler_parity_mismatch_counts": json_safe_counter(mismatches),
        "candidate_index_bad_counts": json_safe_counter(candidate_index_bad),
        "sample_missing": sample_missing,
        "scan_truncated": False,
        "scan_sample_max_rows": None,
    }


def quality_field_missing(value: Any) -> bool:
    return value in (None, "", [], {})


DEFAULT_CONFIDENCE_SOURCE = SCHEDULER_DEFAULT_CONFIDENCE_SOURCE


def _mapping_value(value: Any) -> Mapping[str, Any]:
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except json.JSONDecodeError:
            value = {}
    return value if isinstance(value, Mapping) else {}


CANONICAL_SELECTED_QUALITY_FIELDS = (
    "expected_net_r",
    "probability",
    "source_completeness",
)
CANONICAL_SELECTED_QUALITY_COMPATIBILITY_ALIASES = {
    "expected_net_r": ("candidate_expected_net_r",),
    "probability": ("candidate_probability",),
    "source_completeness": ("candidate_source_completeness",),
}
ZERO_TRADE_EXPLICIT_QUALITY_PREFIXES = (
    "scorecard_reported_",
    "finalizer_primary_probe_",
    "risk_finalizer_best_package_probe_",
    "pre_risk_finalizer_",
)


def _quality_values_equal(left: Any, right: Any) -> bool:
    left_numeric = numeric_or_none(left)
    right_numeric = numeric_or_none(right)
    if left_numeric is not None and right_numeric is not None:
        return math.isclose(left_numeric, right_numeric, rel_tol=0.0, abs_tol=1e-12)
    return left == right


def _quality_surface_parts(
    row: Mapping[str, Any],
    prefix: str = "",
) -> tuple[Mapping[str, Any], Mapping[str, Any], Mapping[str, Any]]:
    envelope = _mapping_value(row.get(f"{prefix}candidate_decision_quality"))
    direct_sources = _mapping_value(
        row.get(f"{prefix}candidate_decision_quality_field_sources")
    )
    nested_sources = _mapping_value(
        envelope.get("candidate_decision_quality_field_sources")
        or envelope.get("field_sources")
    )
    return envelope, direct_sources, nested_sources


def _single_quality_source_reason(source: Any, *, field: str) -> str | None:
    if quality_field_missing(source):
        return f"canonical_quality_source_missing:{field}"
    if not isinstance(source, str) or not source.strip():
        return f"canonical_quality_source_not_single_scalar:{field}"
    return None


def selected_quality_source_contract_reasons(
    row: Mapping[str, Any],
) -> list[str]:
    """Validate producer-backed canonical quality on a selected execution row."""

    envelope, direct_sources, nested_sources = _quality_surface_parts(row)
    reasons: list[str] = []
    for field in CANONICAL_SELECTED_QUALITY_FIELDS:
        canonical_value = row.get(field)
        if quality_field_missing(canonical_value):
            reasons.append(f"canonical_quality_value_missing:{field}")
            continue
        source = direct_sources.get(field)
        source_reason = _single_quality_source_reason(source, field=field)
        if source_reason:
            reasons.append(source_reason)
        nested_value = envelope.get(field)
        if quality_field_missing(nested_value):
            reasons.append(f"canonical_quality_envelope_value_missing:{field}")
        elif not _quality_values_equal(canonical_value, nested_value):
            reasons.append(f"canonical_quality_envelope_value_mismatch:{field}")
        nested_source = nested_sources.get(field)
        nested_source_reason = _single_quality_source_reason(
            nested_source,
            field=field,
        )
        if nested_source_reason:
            reasons.append(f"canonical_quality_envelope_{nested_source_reason}")
        elif source_reason is None and source != nested_source:
            reasons.append(f"canonical_quality_source_mismatch:{field}")
        for alias in CANONICAL_SELECTED_QUALITY_COMPATIBILITY_ALIASES[field]:
            alias_value = row.get(alias)
            if quality_field_missing(alias_value):
                continue
            if not _quality_values_equal(canonical_value, alias_value):
                reasons.append(f"canonical_quality_compatibility_alias_mismatch:{alias}")
    return list(dict.fromkeys(reasons))


def zero_trade_scorecard_quality_source_contract_reasons(
    row: Mapping[str, Any],
) -> list[str]:
    """Keep zero-trade scorecard quality explicitly probe/report scoped."""

    reasons: list[str] = []
    stale_top_level_fields = {
        *CANONICAL_SELECTED_QUALITY_FIELDS,
        *(
            alias
            for aliases in CANONICAL_SELECTED_QUALITY_COMPATIBILITY_ALIASES.values()
            for alias in aliases
        ),
    }
    for field in sorted(stale_top_level_fields):
        if not quality_field_missing(row.get(field)):
            reasons.append(f"zero_trade_scorecard_stale_top_level_quality_alias:{field}")

    top_envelope, top_sources, top_nested_sources = _quality_surface_parts(row)
    for field in CANONICAL_SELECTED_QUALITY_FIELDS:
        if not quality_field_missing(top_envelope.get(field)):
            reasons.append(
                "zero_trade_scorecard_stale_top_level_quality_alias:"
                f"candidate_decision_quality.{field}"
            )
        if not quality_field_missing(top_sources.get(field)):
            reasons.append(
                "zero_trade_scorecard_stale_top_level_quality_alias:"
                f"candidate_decision_quality_field_sources.{field}"
            )
        if not quality_field_missing(top_nested_sources.get(field)):
            reasons.append(
                "zero_trade_scorecard_stale_top_level_quality_alias:"
                f"candidate_decision_quality.field_sources.{field}"
            )
        for prefix in ZERO_TRADE_EXPLICIT_QUALITY_PREFIXES:
            value = row.get(f"{prefix}{field}")
            if quality_field_missing(value):
                continue
            envelope, direct_sources, nested_sources = _quality_surface_parts(row, prefix)
            source = direct_sources.get(field)
            nested_source = nested_sources.get(field)
            source_reason = _single_quality_source_reason(source, field=field)
            if source_reason:
                reasons.append(f"zero_trade_{prefix}{source_reason}")
            if not quality_field_missing(envelope.get(field)) and not _quality_values_equal(
                value,
                envelope.get(field),
            ):
                reasons.append(
                    f"zero_trade_{prefix}canonical_quality_envelope_value_mismatch:{field}"
                )
            if (
                source_reason is None
                and not quality_field_missing(nested_source)
                and source != nested_source
            ):
                reasons.append(f"zero_trade_{prefix}canonical_quality_source_mismatch:{field}")
    return list(dict.fromkeys(reasons))


def _row_has_selected_candidate(row: Mapping[str, Any]) -> bool:
    for field in (
        "selected_candidate_id",
        "candidate_id",
        "replay_candidate_id",
    ):
        if str(row.get(field) or "").strip():
            return True
    selected_ids = row.get("selected_candidate_ids")
    if isinstance(selected_ids, str):
        return bool(selected_ids.strip())
    if isinstance(selected_ids, Sequence) and not isinstance(
        selected_ids,
        (str, bytes, bytearray),
    ):
        return any(str(value or "").strip() for value in selected_ids)
    return False


def _scorecard_has_selected_candidate(row: Mapping[str, Any]) -> bool:
    if str(row.get("selected_candidate_id") or "").strip():
        return True
    selected_ids = row.get("selected_candidate_ids")
    if isinstance(selected_ids, str):
        return bool(selected_ids.strip())
    if isinstance(selected_ids, Sequence) and not isinstance(
        selected_ids,
        (str, bytes, bytearray),
    ):
        return any(str(value or "").strip() for value in selected_ids)
    return False


def scan_broad_selected_quality_source_contract(
    paths: Mapping[str, Path],
) -> dict[str, Any]:
    counts: Counter[str] = Counter()
    bad_counts: Counter[str] = Counter()
    sample_bad: list[dict[str, Any]] = []
    for ledger_name in ("scorecard", "order", "trade"):
        path = paths.get(ledger_name)
        if path is None or not path.exists() or path.stat().st_size <= 0:
            bad_counts[f"{ledger_name}:ledger_missing_or_empty"] += 1
            continue
        try:
            for row_index, line in enumerate(iter_text_lines_with_retries(path), start=1):
                if not line.strip():
                    continue
                row = json.loads(line)
                if not isinstance(row, Mapping):
                    bad_counts[f"{ledger_name}:row_not_mapping"] += 1
                    continue
                counts[f"{ledger_name}_rows"] += 1
                selected = (
                    _scorecard_has_selected_candidate(row)
                    if ledger_name == "scorecard"
                    else _row_has_selected_candidate(row)
                )
                if ledger_name == "scorecard" and not selected:
                    counts["zero_trade_scorecard_rows"] += 1
                    reasons = zero_trade_scorecard_quality_source_contract_reasons(row)
                elif selected:
                    counts[f"selected_{ledger_name}_rows"] += 1
                    reasons = selected_quality_source_contract_reasons(row)
                else:
                    counts[f"passive_{ledger_name}_rows"] += 1
                    continue
                for reason in reasons:
                    bad_counts[f"{ledger_name}:{reason}"] += 1
                if reasons and len(sample_bad) < 12:
                    sample_bad.append(
                        {
                            "ledger": ledger_name,
                            "row_index": row_index,
                            "candidate_id": row.get("selected_candidate_id")
                            or row.get("candidate_id")
                            or row.get("replay_candidate_id"),
                            "reasons": reasons,
                        }
                    )
        except (json.JSONDecodeError, OSError, TimeoutError):
            bad_counts[f"{ledger_name}:ledger_unreadable"] += 1
    return {
        "paths": {name: str(path) for name, path in paths.items()},
        "row_counts": json_safe_counter(counts),
        "bad_counts": json_safe_counter(bad_counts),
        "sample_bad": sample_bad,
    }


def _list_values(value: Any) -> list[Any]:
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        return list(value)
    return [value] if value not in (None, "") else []


def _truthy_flag(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    return str(value or "").strip().lower() in {"1", "true", "yes", "y"}


def default_confidence_provenance_issues(row: Mapping[str, Any]) -> list[str]:
    quality = _mapping_value(row.get("candidate_decision_quality"))
    field_sources = _mapping_value(row.get("candidate_decision_quality_field_sources"))
    quality_sources = _mapping_value(
        quality.get("candidate_decision_quality_field_sources")
        or quality.get("field_sources")
    )
    scheduler_inputs = _mapping_value(row.get("scheduler_candidate_decision_inputs"))
    scheduler_sources = _mapping_value(
        scheduler_inputs.get("candidate_decision_quality_field_sources")
    )
    authority_sources = _mapping_value(
        row.get("package_new_entry_authority_candidate_decision_quality_field_sources")
    )
    sources = {
        "row": field_sources.get("confidence"),
        "quality": quality_sources.get("confidence"),
        "scheduler": scheduler_sources.get("confidence"),
        "authority": authority_sources.get("confidence"),
    }
    default_surfaces = [
        surface for surface, source in sources.items() if source == DEFAULT_CONFIDENCE_SOURCE
    ]
    if not default_surfaces:
        return []
    warnings = []
    for source in (
        row.get("candidate_decision_quality_optional_provenance_warnings"),
        row.get("scheduler_candidate_decision_quality_optional_provenance_warnings"),
        quality.get("candidate_decision_quality_optional_provenance_warnings"),
        quality.get("optional_provenance_warnings"),
        scheduler_inputs.get("candidate_decision_quality_optional_provenance_warnings"),
        row.get(
            "package_new_entry_authority_candidate_decision_quality_optional_provenance_warnings"
        ),
    ):
        warnings.extend(str(item) for item in _list_values(source))
    has_warning = any(DEFAULT_CONFIDENCE_SOURCE in warning for warning in warnings)
    has_flag = any(
        _truthy_flag(value)
        for value in (
            row.get("confidence_missing_degraded_default_applied"),
            row.get("scheduler_confidence_missing_degraded_default_applied"),
            scheduler_inputs.get("confidence_missing_degraded_default_applied"),
            quality.get("confidence_missing_degraded_default_applied"),
        )
    )
    issues: list[str] = []
    if not has_warning:
        issues.append("default_confidence_source_without_warning")
    if not has_flag:
        issues.append("default_confidence_source_without_degraded_default_flag")
    confidence_values = []
    for surface in (row, quality, scheduler_inputs):
        for field in ("confidence", "candidate_confidence", "scheduler_confidence"):
            value = surface.get(field)
            if value in (None, "") or isinstance(value, bool):
                continue
            try:
                number = float(value)
            except (TypeError, ValueError):
                continue
            if math.isfinite(number):
                confidence_values.append(number)
    explicit_default_semantics = bool(
        has_warning
        and has_flag
        and confidence_values
        and all(abs(value - 0.55) <= 0.000000001 for value in confidence_values)
    )
    declared_sources = [str(source) for source in sources.values() if source not in (None, "")]
    semantically_default_sources = {
        DEFAULT_CONFIDENCE_SOURCE,
        *DEFAULT_MISSING_CONFIDENCE_COMPATIBILITY_SOURCES,
    }
    all_sources_semantically_default = bool(
        declared_sources
        and all(source in semantically_default_sources for source in declared_sources)
    )
    alias_statuses = {
        str(value or "").strip().lower()
        for value in (
            row.get("candidate_decision_quality_alias_status"),
            quality.get("candidate_decision_quality_alias_status")
            or quality.get("alias_status"),
            scheduler_inputs.get("candidate_decision_quality_alias_status"),
            row.get(
                "package_new_entry_authority_candidate_decision_quality_alias_status"
            ),
        )
        if str(value or "").strip()
    }
    alias_mismatches: list[str] = []
    for value in (
        row.get("candidate_decision_quality_alias_mismatches"),
        quality.get("candidate_decision_quality_alias_mismatches")
        or quality.get("alias_mismatches"),
        scheduler_inputs.get("candidate_decision_quality_alias_mismatches"),
        row.get(
            "package_new_entry_authority_candidate_decision_quality_alias_mismatches"
        ),
    ):
        alias_mismatches.extend(str(item) for item in _list_values(value))
    confidence_source_mismatches = [
        mismatch
        for mismatch in alias_mismatches
        if mismatch.startswith("field_sources:confidence:")
    ]
    if (
        explicit_default_semantics
        and all_sources_semantically_default
        and ("mismatch" in alias_statuses or confidence_source_mismatches)
    ):
        issues.append("stale_default_confidence_source_mismatch")
    genuine_source_conflict = bool(
        any(source == DEFAULT_CONFIDENCE_SOURCE for source in declared_sources)
        and any(
            source not in semantically_default_sources for source in declared_sources
        )
    )
    if genuine_source_conflict and (
        "mismatch" not in alias_statuses or not confidence_source_mismatches
    ):
        issues.append("genuine_confidence_source_conflict_not_fail_closed")
    if (
        sources.get("row") not in (None, "", DEFAULT_CONFIDENCE_SOURCE)
        and any(
            surface in default_surfaces
            for surface in ("quality", "scheduler", "authority")
        )
        and not (
            explicit_default_semantics
            and sources.get("row") in semantically_default_sources
        )
    ):
        issues.append("default_confidence_hidden_by_top_level_source")
    return list(dict.fromkeys(issues))


def dynamic_execution_fillability_floor_issues(
    row: Mapping[str, Any],
) -> list[str]:
    """Reject a stale dynamic-floor veto when canonical fillability clears it."""

    decision_inputs = _mapping_value(
        row.get("scheduler_candidate_decision_inputs")
        or row.get("candidate_decision_inputs")
    )
    floor_value = row.get("dynamic_budget_min_fill_probability")
    if floor_value in (None, ""):
        floor_value = decision_inputs.get("dynamic_budget_min_fill_probability")
    try:
        floor = float(floor_value)
    except (TypeError, ValueError):
        return []
    if not math.isfinite(floor):
        return []
    fillability = resolve_execution_fillability_surfaces(row, decision_inputs)
    value = fillability.get("value")
    try:
        execution_fill_probability = float(value)
    except (TypeError, ValueError):
        return []
    if not math.isfinite(execution_fill_probability):
        return []
    vetoes: list[str] = []
    for field in (
        "vetoes",
        "scheduler_option_vetoes",
        "scheduler_terminal_vetoes",
        "terminal_vetoes",
    ):
        vetoes.extend(str(item) for item in _list_values(row.get(field)))
    stale_dynamic_veto = any(
        "fill_probability_below_dynamic_allocator_floor" in veto
        for veto in vetoes
    )
    if execution_fill_probability + 0.000000001 >= floor and stale_dynamic_veto:
        return ["stale_dynamic_fill_floor_veto_above_canonical_execution_floor"]
    return []


def confidence_source_omission_issues(row: Mapping[str, Any]) -> list[str]:
    quality = _mapping_value(row.get("candidate_decision_quality"))
    field_sources = _mapping_value(row.get("candidate_decision_quality_field_sources"))
    quality_sources = _mapping_value(
        quality.get("candidate_decision_quality_field_sources")
        or quality.get("field_sources")
    )
    scheduler_inputs = _mapping_value(row.get("scheduler_candidate_decision_inputs"))
    scheduler_sources = _mapping_value(
        scheduler_inputs.get("candidate_decision_quality_field_sources")
    )
    authority_sources = _mapping_value(
        row.get("package_new_entry_authority_candidate_decision_quality_field_sources")
    )
    confidence_present = any(
        value not in (None, "", [], {})
        for value in (
            row.get("confidence"),
            row.get("candidate_confidence"),
            row.get("scheduler_confidence"),
            quality.get("confidence"),
            quality.get("candidate_confidence"),
            scheduler_inputs.get("confidence"),
            scheduler_inputs.get("candidate_confidence"),
            scheduler_inputs.get("scheduler_confidence"),
        )
    )
    source_present = any(
        sources.get("confidence") not in (None, "", [], {})
        for sources in (
            field_sources,
            quality_sources,
            scheduler_sources,
            authority_sources,
        )
    )
    if confidence_present and not source_present:
        return ["confidence_present_without_confidence_source"]
    return []


