def candidate_decision_quality_missing_fields(row: Mapping[str, Any]) -> list[str]:
    """Require nested selected-policy quality when flat compatibility fields exist."""

    present_flat_fields = [
        field
        for field in SELECTED_POLICY_FLAT_QUALITY_FIELDS
        if not quality_field_missing(row.get(field))
    ]
    if not present_flat_fields:
        return []
    envelope = row.get("candidate_decision_quality")
    if isinstance(envelope, str):
        try:
            envelope = json.loads(envelope)
        except json.JSONDecodeError:
            envelope = {}
    if not isinstance(envelope, Mapping) or not envelope:
        return ["candidate_decision_quality"]
    missing: list[str] = []
    for field in present_flat_fields:
        aliases = SELECTED_POLICY_NESTED_QUALITY_ALIASES.get(field, (field,))
        if all(quality_field_missing(envelope.get(alias)) for alias in aliases):
            missing.append(f"candidate_decision_quality.{field}")
    return missing


def safe_int_value(value: Any, default: int = 0) -> int:
    if value in (None, "") or isinstance(value, bool):
        return default
    try:
        return int(float(value))
    except (TypeError, ValueError):
        return default


def first_present_mapping_value(row: Mapping[str, Any], fields: Sequence[str]) -> Any:
    for field in fields:
        value: Any = row
        found = True
        for part in str(field).split("."):
            if not isinstance(value, Mapping) or part not in value:
                found = False
                break
            value = value.get(part)
        if found and value not in (None, "", [], {}):
            return value
    return None


def candidate_decision_quality_limit_fillability_alias_reasons(
    row: Mapping[str, Any],
) -> list[str]:
    sources = row.get("candidate_decision_quality_field_sources")
    if isinstance(sources, str):
        try:
            sources = json.loads(sources)
        except json.JSONDecodeError:
            sources = {}
    if not isinstance(sources, Mapping):
        sources = {}
    reasons: list[str] = []
    for field in ("fill_probability", "candidate_fill_probability"):
        source = str(sources.get(field) or "").strip().lower()
        if source and "limit_fillability" in source:
            reasons.append(
                f"candidate_decision_quality_field_sources.{field}_limit_fillability_alias"
            )
    return reasons


def package_displacement_quality_failure_reasons(row: Mapping[str, Any]) -> list[str]:
    """Return fatal package-soft-authority displacement failures on selected rows."""

    def truthy(value: Any) -> bool:
        if isinstance(value, bool):
            return value
        return str(value or "").strip().lower() in {"1", "true", "yes", "y", "on"}

    def nested_records(source: Mapping[str, Any]) -> list[Mapping[str, Any]]:
        records: list[Mapping[str, Any]] = []
        for field in (
            "package_displacement_quality",
            "scheduler_candidate_decision_inputs.package_displacement_quality",
            "selected_scheduler_decision_inputs.package_displacement_quality",
            "candidate_decision_inputs.package_displacement_quality",
            "score_components.package_displacement_quality",
            "score_components.candidate_decision_inputs.package_displacement_quality",
        ):
            value = first_present_mapping_value(source, (field,))
            if isinstance(value, Mapping):
                records.append(value)
        return records

    def selected_trace_rows(source: Mapping[str, Any]) -> list[Mapping[str, Any]]:
        rows: list[Mapping[str, Any]] = [source]
        for field in (
            "selected_scheduler_option_trace",
            "selected_scheduler_option",
            "selected_option",
        ):
            value = source.get(field)
            if isinstance(value, Mapping):
                rows.append(value)
            elif isinstance(value, list):
                rows.extend(item for item in value if isinstance(item, Mapping))
        packet = source.get("scheduler_packet")
        packet = packet if isinstance(packet, Mapping) else {}
        decision = packet.get("decision")
        decision = decision if isinstance(decision, Mapping) else {}
        selected_option = decision.get("selected_option")
        if isinstance(selected_option, Mapping):
            rows.append(selected_option)
        selected_options = decision.get("selected_options")
        if isinstance(selected_options, list):
            rows.extend(item for item in selected_options if isinstance(item, Mapping))
        return rows

    reasons: list[str] = []
    for source in selected_trace_rows(row):
        if str(source.get("decision_status") or "") == (
            "candidate_vetoed_package_displacement_quality_failed"
        ):
            reasons.append("package_soft_authority_displacement_quality_failed")
        vetoes = source.get("vetoes") or ()
        if isinstance(vetoes, str):
            veto_iterable: Iterable[Any] = (vetoes,)
        elif isinstance(vetoes, Sequence) and not isinstance(vetoes, (bytes, bytearray)):
            veto_iterable = vetoes
        else:
            veto_iterable = ()
        if any(
            str(veto).startswith("package_soft_authority_displacement_quality_failed")
            for veto in veto_iterable
        ):
            reasons.append("package_soft_authority_displacement_quality_failed")
        for diagnostic in nested_records(source):
            if (
                truthy(diagnostic.get("applies"))
                and truthy(diagnostic.get("enabled"))
                and diagnostic.get("allowed") is False
            ):
                reasons.append("package_soft_authority_displacement_quality_failed")
    return list(dict.fromkeys(reasons))


def package_displacement_diagnostics(row: Mapping[str, Any]) -> list[Mapping[str, Any]]:
    """Return unique displacement diagnostics from full or compact ledger rows."""
    diagnostics: list[Mapping[str, Any]] = []
    for field in (
        "package_displacement_quality",
        "scheduler_candidate_decision_inputs.package_displacement_quality",
        "selected_scheduler_decision_inputs.package_displacement_quality",
        "candidate_decision_inputs.package_displacement_quality",
        "score_components.package_displacement_quality",
        "score_components.candidate_decision_inputs.package_displacement_quality",
    ):
        value = first_present_mapping_value(row, (field,))
        if isinstance(value, Mapping) and value not in diagnostics:
            diagnostics.append(value)
    return diagnostics


def package_displacement_threshold_truth_reasons(row: Mapping[str, Any]) -> list[str]:
    """Validate comparator-margin and no-comparator absolute-floor semantics."""

    def truthy(value: Any) -> bool:
        if isinstance(value, bool):
            return value
        return str(value or "").strip().lower() in {"1", "true", "yes", "y", "on"}

    reasons: list[str] = []
    for diagnostic in package_displacement_diagnostics(row):
        if not truthy(diagnostic.get("applies")) or not truthy(
            diagnostic.get("enabled")
        ):
            continue
        best_primary_present = bool(
            diagnostic.get("best_primary_candidate_id") not in (None, "")
            or numeric_or_none(diagnostic.get("best_primary_edge_score")) is not None
        )
        if diagnostic.get("primary_comparator_present") is not best_primary_present:
            reasons.append("primary_comparator_presence_flag_mismatch")
        threshold_mode = str(diagnostic.get("threshold_mode") or "").strip()
        if best_primary_present:
            if threshold_mode and threshold_mode != "primary_comparator_edge_delta":
                reasons.append("primary_comparator_threshold_mode_invalid")
            if diagnostic.get("min_edge_delta_applies") is not True:
                reasons.append("primary_comparator_delta_applies_flag_invalid")
            if diagnostic.get("no_primary_min_edge_score_applies") is not False:
                reasons.append("primary_comparator_standalone_floor_applies_flag_invalid")
            continue

        candidate_edge = numeric_or_none(diagnostic.get("candidate_edge_score"))
        no_primary_floor = numeric_or_none(
            diagnostic.get("no_primary_min_edge_score")
        )
        edge_delta = numeric_or_none(diagnostic.get("edge_delta"))
        if threshold_mode != "no_primary_absolute_expected_transfer_score":
            reasons.append("no_primary_comparator_threshold_mode_missing_or_invalid")
        if no_primary_floor is None:
            reasons.append("no_primary_comparator_absolute_edge_floor_missing")
            no_primary_floor = 0.0
        if edge_delta is not None:
            reasons.append("no_primary_comparator_edge_delta_present")
        if diagnostic.get("min_edge_delta_applies") is not False:
            reasons.append("no_primary_comparator_delta_applies_flag_invalid")
        if diagnostic.get("no_primary_min_edge_score_applies") is not True:
            reasons.append("no_primary_comparator_standalone_floor_applies_flag_invalid")
        if str(diagnostic.get("reason") or "") == (
            "no_primary_comparator_package_edge_below_zero_floor"
        ):
            reasons.append("no_primary_comparator_legacy_comparator_delta_floor_reason")

        threshold_met = bool(
            candidate_edge is not None
            and candidate_edge > 1e-12
            and candidate_edge + 1e-12 >= max(0.0, no_primary_floor)
        )
        displacement_inputs_valid = bool(
            truthy(
                diagnostic.get("no_primary_comparator_policy_allowed")
                if "no_primary_comparator_policy_allowed" in diagnostic
                else diagnostic.get("no_primary_comparator_override_allowed")
            )
            and truthy(
                diagnostic.get(
                    "signed_new_entry_authority_effective_valid_for_displacement"
                )
                if "signed_new_entry_authority_effective_valid_for_displacement"
                in diagnostic
                else diagnostic.get("signed_new_entry_authority_valid")
            )
            and truthy(diagnostic.get("broker_cost_executable"))
            and (
                "router_refusal_origin_family_allowed" not in diagnostic
                or truthy(diagnostic.get("router_refusal_origin_family_allowed"))
            )
        )
        allowed = diagnostic.get("allowed") is True
        if displacement_inputs_valid and threshold_met and not allowed:
            reasons.append("no_primary_comparator_eligible_positive_edge_rejected")
        if allowed and not displacement_inputs_valid:
            reasons.append("no_primary_comparator_allowed_without_required_authority")
        if allowed and not threshold_met:
            reasons.append("no_primary_comparator_allowed_below_absolute_edge_floor")
    return list(dict.fromkeys(reasons))


def canonical_selector_action(value: Any) -> str:
    raw = str(value or "").strip().lower().replace("_", "-")
    return {
        "reduce": "reduce-risk",
        "reduced-risk": "reduce-risk",
        "risk-reduce": "reduce-risk",
        "open-reduce-risk": "open-reduced-risk",
        "open-risk-reduced": "open-reduced-risk",
        "source-required": "source-required",
        "source-required-hold": "source-required",
    }.get(raw, raw)


def canonical_scheduler_action_intent(value: Any) -> str:
    raw = str(value or "").strip().lower().replace("_", "-")
    canonical = {
        "scale": "same-direction-scale-in",
        "scale-in": "same-direction-scale-in",
        "same-side-scale-in": "same-direction-scale-in",
        "reduce": "reduce-existing",
        "close": "close-existing",
        "reverse": "close-and-reverse",
        "replace": "replace-pending",
    }.get(raw, raw)
    return canonical.replace("-", "_")


def selected_execution_policy_value(row: Mapping[str, Any], fields: Sequence[str]) -> Any:
    policy_packet = row.get("selected_execution_policy")
    policy_packet = policy_packet if isinstance(policy_packet, Mapping) else {}
    execution_policy_packet = row.get("selected_execution_policy_packet")
    execution_policy_packet = (
        execution_policy_packet if isinstance(execution_policy_packet, Mapping) else {}
    )
    replay_exit = row.get("selected_execution_policy_replay_exit")
    replay_exit = replay_exit if isinstance(replay_exit, Mapping) else {}
    for source in (row, policy_packet, execution_policy_packet, replay_exit):
        value = first_present_mapping_value(source, fields)
        if value not in (None, "", [], {}):
            return value
    return None


def stable_projection_sha256(value: Any) -> str:
    material = json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        default=str,
    )
    return hashlib.sha256(material.encode("utf-8")).hexdigest()


COMPACT_SCORECARD_PROJECTION_SCHEMA = (
    "gtos.final_moonshot.broad_replay.compact_scorecard_projection.v1"
)


def compact_scorecard_projection_reasons(
    row: Mapping[str, Any],
) -> list[str]:
    schema = row.get("compact_scorecard_projection_schema")
    status = row.get("scheduler_option_trace_projection_status")
    if schema in (None, "") and status in (None, ""):
        return []
    reasons: list[str] = []
    if schema != COMPACT_SCORECARD_PROJECTION_SCHEMA:
        reasons.append("compact_scorecard_projection_schema_invalid")
    allowed_statuses = {
        "canonical_trace_preserved_exact_duplicate_aliases_omitted",
        "canonical_trace_preserved_distinct_aliases_not_compacted",
        "canonical_trace_preserved_no_aliases_present",
    }
    if status not in allowed_statuses:
        reasons.append("compact_scorecard_projection_status_invalid")
    canonical_trace = row.get("scheduler_option_trace")
    if not isinstance(canonical_trace, list) or not canonical_trace:
        reasons.append("compact_scorecard_canonical_trace_missing")
    aliases = row.get("scheduler_option_trace_omitted_duplicate_aliases")
    expected_aliases = {
        "pre_risk_finalizer_scheduler_option_trace",
        "post_risk_finalizer_scheduler_option_trace",
    }
    aliases_are_sequence = isinstance(aliases, Sequence) and not isinstance(
        aliases,
        (str, bytes, bytearray),
    )
    alias_values = list(aliases) if aliases_are_sequence else []
    observed_aliases = {
        str(value) for value in alias_values if str(value or "").strip()
    }
    if (
        not aliases_are_sequence
        or len(alias_values) != len(observed_aliases)
        or not observed_aliases.issubset(expected_aliases)
    ):
        reasons.append("compact_scorecard_omitted_alias_set_invalid")
    if (
        status == "canonical_trace_preserved_exact_duplicate_aliases_omitted"
        and not observed_aliases
    ):
        reasons.append("compact_scorecard_omitted_alias_set_empty")
    if (
        status
        in {
            "canonical_trace_preserved_distinct_aliases_not_compacted",
            "canonical_trace_preserved_no_aliases_present",
        }
        and observed_aliases
    ):
        reasons.append("compact_scorecard_noop_status_declares_omitted_aliases")
    for alias in observed_aliases:
        if row.get(alias) not in (None, "", [], {}):
            reasons.append(f"compact_scorecard_omitted_alias_still_present:{alias}")
    retained_aliases = expected_aliases - observed_aliases
    retained_values = {
        alias: row.get(alias)
        for alias in retained_aliases
        if row.get(alias) not in (None, "", [], {})
    }
    for alias, value in retained_values.items():
        if value == canonical_trace:
            reasons.append(
                f"compact_scorecard_duplicate_alias_not_omitted:{alias}"
            )
    if (
        status == "canonical_trace_preserved_distinct_aliases_not_compacted"
        and not retained_values
    ):
        reasons.append("compact_scorecard_distinct_alias_missing")
    if (
        status == "canonical_trace_preserved_no_aliases_present"
        and retained_values
    ):
        reasons.append("compact_scorecard_unexpected_retained_alias")
    if isinstance(canonical_trace, list) and canonical_trace:
        if row.get("scheduler_option_trace_projection_sha256") != (
            stable_projection_sha256(canonical_trace)
        ):
            reasons.append("compact_scorecard_canonical_trace_hash_mismatch")
    return reasons


def scorecard_scheduler_options(row: dict[str, Any]) -> list[dict[str, Any]]:
    options: list[dict[str, Any]] = []
    for field in ("scheduler_option_trace",):
        value = row.get(field)
        if isinstance(value, list):
            options.extend(item for item in value if isinstance(item, dict))
    for field in (
        "selected_scheduler_option_trace",
        "pre_risk_finalizer_scheduler_option_trace",
        "post_risk_finalizer_scheduler_option_trace",
    ):
        value = row.get(field)
        if isinstance(value, dict):
            options.append(value)
        elif isinstance(value, list):
            options.extend(item for item in value if isinstance(item, dict))
    packet = row.get("scheduler_packet")
    packet = packet if isinstance(packet, dict) else {}
    all_options = packet.get("all_options_preserved")
    if isinstance(all_options, list):
        options.extend(item for item in all_options if isinstance(item, dict))
    decision = packet.get("decision")
    decision = decision if isinstance(decision, dict) else {}
    selected_option = decision.get("selected_option")
    if isinstance(selected_option, dict):
        options.append(selected_option)
    selected_options = decision.get("selected_options")
    if isinstance(selected_options, list):
        options.extend(item for item in selected_options if isinstance(item, dict))
    return options


