def row_source_bound_router_refusal_materialized(row: Mapping[str, Any]) -> bool:
    fields = (
        "selector_reason",
        "effective_selector_reason",
        "scheduler_materialization_selector_reason",
        "package_new_entry_authority_selector_reason",
        "replay_candidate_use_allowed_now_reason",
        "package_replay_executable_candidate_use_allowed_reason",
        "package_replay_order_executable_candidate_use_allowed_reason",
        "selected_scheduler_package_replay_executable_candidate_use_allowed_reason",
        "selected_scheduler_package_replay_order_executable_candidate_use_allowed_reason",
        "risk_finalizer_package_replay_executable_candidate_use_allowed_reason",
        "risk_finalizer_package_replay_order_executable_candidate_use_allowed_reason",
        "reason",
    )
    for field in fields:
        value = row.get(field)
        if value in (None, "", [], {}):
            continue
        if ROUTER_REFUSAL_SOURCE_BOUND_MATERIALIZATION_REASON in str(value):
            return True
    return False


def row_signed_new_entry_authority_contract_valid(
    row: Mapping[str, Any],
    *,
    require_immutable_payload: bool = False,
) -> bool:
    surfaces: list[Mapping[str, Any]] = [row]
    for field in (
        "ultimate_candidate_package_open_reduced_risk_authority",
        "ultimate_candidate_package_reduce_risk_authority",
        "ultimate_candidate_package_reduced_risk_authority",
        "selector_reduced_risk_new_position_signed_authority",
    ):
        nested = parse_mapping(row.get(field))
        if nested:
            surfaces.append(nested)
    for surface in surfaces:
        status = str(
            first_present_mapping_value(
                surface,
                ("package_new_entry_authority_status", "status"),
            )
            or ""
        ).strip()
        valid = value_bool_true(
            first_present_mapping_value(
                surface,
                ("package_new_entry_authority_valid", "valid"),
            )
        )
        if not valid or (
            status and status != "valid_signed_predecision_new_entry_authority"
        ):
            continue
        signed_flag = first_present_mapping_value(
            surface,
            (
                "package_new_entry_authority_signed",
                "signed_package_new_entry_authority",
                "signed",
            ),
        )
        if signed_flag is not None and value_bool_false(signed_flag):
            continue
        authority_hash = first_present_mapping_value(
            surface,
            (
                "package_new_entry_authority_hash_sha256",
                "hash_sha256",
            ),
        )
        expected_hash = first_present_mapping_value(
            surface,
            ("expected_package_new_entry_authority_hash_sha256",),
        )
        if not looks_like_sha256(authority_hash):
            continue
        if expected_hash not in (None, "") and (
            not looks_like_sha256(expected_hash)
            or str(authority_hash).strip() != str(expected_hash).strip()
        ):
            continue
        source_key = str(
            first_present_mapping_value(
                surface,
                (
                    "package_new_entry_authority_source_bound_replay_candidate_instance_key",
                    "source_bound_replay_candidate_instance_key",
                ),
            )
            or row.get(
                "package_new_entry_authority_source_bound_replay_candidate_instance_key"
            )
            or row.get("source_bound_replay_candidate_instance_key")
            or ""
        ).strip()
        if not source_key or "@@" not in source_key:
            continue
        combined_surface = {**row, **surface}
        payload = parse_mapping(
            combined_surface.get("package_new_entry_authority_payload")
        )
        action_intent = canonical_scheduler_action_intent(
            first_present_mapping_value(
                combined_surface,
                (
                    "package_new_entry_authority_target_action_intent",
                    "scheduler_materialization_action_intent",
                    "selected_scheduler_action_class",
                    "scheduler_action_class",
                    "action_intent",
                    "lifecycle_action",
                ),
            )
            or payload.get("target_action_intent")
            or "new_position"
        )
        if package_new_entry_authority_payload_contract_reasons(
            combined_surface,
            action_intent=action_intent,
            require_immutable_payload=require_immutable_payload,
        ):
            continue
        return True
    return False


def unsigned_router_refusal_executable_authority_leak_reasons(
    row: Mapping[str, Any],
) -> list[str]:
    if not row_source_bound_router_refusal_materialized(row):
        return []
    executable_flags = [
        field
        for field in UNSIGNED_ROUTER_REFUSAL_EXECUTABLE_FLAG_FIELDS
        if value_bool_true(first_present_mapping_value(row, (field,)))
    ]
    if not executable_flags:
        return []
    if row_signed_new_entry_authority_contract_valid(row):
        return []
    return [
        "unsigned_router_refusal_executable_authority:"
        + ",".join(executable_flags)
    ]


def parse_mapping(value: Any) -> Mapping[str, Any]:
    if isinstance(value, Mapping):
        return value
    if isinstance(value, str) and value.strip():
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError:
            return {}
        return parsed if isinstance(parsed, Mapping) else {}
    return {}


def package_execution_scope_is_diagnostic(row: Mapping[str, Any]) -> bool:
    scope = str(
        first_present_mapping_value(
            row,
            (
                "package_execution_result_scope",
                "execution_result_scope",
                "package_replay_result_scope",
            ),
        )
        or ""
    ).strip().lower()
    if any(token in scope for token in ("diagnostic", "counterfactual")):
        return True
    profile = str(row.get("broad_replay_profile") or "").strip().lower()
    return profile.startswith("raw_") and "executable" not in scope


def row_cost_authority_executable_claim(
    row: Mapping[str, Any],
    *,
    ledger_name: str,
) -> bool:
    """Return whether broker-cost authority is executable proof, not diagnostic."""

    if package_execution_scope_is_diagnostic(row):
        return False
    if value_bool_true(row.get("execution_claim")):
        return True
    if any(
        value_bool_true(first_present_mapping_value(row, (field,)))
        for field in (
            "package_replay_executable_candidate_use_allowed",
            "package_replay_order_executable_candidate_use_allowed",
            "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed",
            "selected_scheduler_package_replay_executable_candidate_use_allowed",
            "selected_scheduler_package_replay_order_executable_candidate_use_allowed",
            "scheduler_option_package_replay_executable_candidate_use_allowed",
            "scheduler_option_package_replay_order_executable_candidate_use_allowed",
            "ultimate_package_effective_executable_authority_allowed",
            "broker_pretrade_cost_executable",
        )
    ):
        return True
    if ledger_name == "trade":
        return True
    if ledger_name == "order":
        order_status = str(row.get("order_status") or "").strip().lower()
        return order_status not in {
            "",
            "risk_rejected",
            "execution_manager_blocked",
            "diagnostic_only",
            "counterfactual_only",
        }
    return False


