def signed_authority_current_identity_values(
    row: Mapping[str, Any],
    current_field: str,
) -> list[str]:
    if signed_package_authority_scorecard_projection_allowed(row):
        projected_values: list[str] = []
        signed_field = f"package_new_entry_authority_{current_field}"
        reported_field = f"scorecard_reported_package_new_entry_authority_{current_field}"
        for field in (reported_field, signed_field):
            value = first_present_mapping_value(row, (field,))
            if value not in (None, "", [], {}):
                projected_values.append(str(value))
        if projected_values:
            return list(dict.fromkeys(projected_values))
    values: list[str] = []
    for field in SIGNED_AUTHORITY_CURRENT_IDENTITY_FIELDS.get(current_field, (current_field,)):
        value = first_present_mapping_value(row, (field,))
        if value not in (None, "", [], {}):
            values.append(str(value))
    return list(dict.fromkeys(values))


