def nested_mapping_surfaces(
    value: Any,
) -> Iterable[tuple[str, Mapping[str, Any]]]:
    pending: list[tuple[str, Any]] = [("root", value)]
    seen: set[int] = set()
    while pending:
        path, current = pending.pop()
        if isinstance(current, Mapping):
            marker = id(current)
            if marker in seen:
                continue
            seen.add(marker)
            yield path, current
            for key, nested in reversed(tuple(current.items())):
                child_path = f"{path}.{key}"
                if isinstance(nested, Mapping):
                    pending.append((child_path, nested))
                elif isinstance(nested, Sequence) and not isinstance(
                    nested,
                    (str, bytes, bytearray),
                ):
                    for index in range(len(nested) - 1, -1, -1):
                        item = nested[index]
                        if isinstance(item, Mapping):
                            pending.append((f"{child_path}[{index}]", item))


def provisional_package_new_entry_authority_marker_paths(
    row: Mapping[str, Any],
) -> list[str]:
    return [
        f"{path}.{PACKAGE_NEW_ENTRY_AUTHORITY_PROVISIONAL_MARKER}"
        for path, surface in nested_mapping_surfaces(row)
        if PACKAGE_NEW_ENTRY_AUTHORITY_PROVISIONAL_MARKER in surface
    ]


def stable_member_axis_id(value: Any) -> bool:
    if not isinstance(value, str):
        return False
    text = value.strip()
    return bool(
        text
        and text == value
        and len(text) <= 512
        and text.lower() not in INVALID_STABLE_MEMBER_AXIS_IDS
        and numeric_or_none(text) is None
        and text.isprintable()
        and not any(character.isspace() for character in text)
        and any(character.isalnum() for character in text)
    )


def stable_member_axis_ids(value: Any) -> tuple[str, ...]:
    if isinstance(value, str):
        values: tuple[Any, ...] = (value,)
    elif isinstance(value, Sequence) and not isinstance(
        value,
        (str, bytes, bytearray, Mapping),
    ):
        values = tuple(value)
    else:
        return ()
    if not values or not all(stable_member_axis_id(item) for item in values):
        return ()
    return tuple(sorted(set(str(item) for item in values)))


def canonical_payload_member_axis_ids(value: Any) -> tuple[str, ...]:
    if not isinstance(value, Sequence) or isinstance(
        value,
        (str, bytes, bytearray, Mapping),
    ):
        return ()
    values = tuple(value)
    canonical = stable_member_axis_ids(values)
    if not canonical or tuple(str(item) for item in values) != canonical:
        return ()
    return canonical


def finalized_executable_member_axis_identity_reasons(
    row: Mapping[str, Any],
    *,
    executable_authority_stage: str = "final",
) -> list[str]:
    action_intent = canonical_scheduler_action_intent(
        first_present_mapping_value(
            row,
            (
                "scheduler_materialization_action_intent",
                "selected_scheduler_action_class",
                "scheduler_action_class",
                "action_intent",
                "lifecycle_action",
            ),
        )
        or "new_position"
    )
    envelope = package_new_entry_authority_envelope_selection(
        row,
        action_intent=action_intent,
    )
    positive_counts: list[float] = []
    root_member_axis_claim = False
    for field in FINALIZED_EXECUTABLE_MEMBER_AXIS_COUNT_FIELDS:
        if field not in row:
            continue
        count = numeric_or_none(row.get(field))
        if count is not None and count > 0.0:
            positive_counts.append(count)
            root_member_axis_claim = True
    for field in FINALIZED_EXECUTABLE_MEMBER_AXIS_ID_FIELDS:
        if field in row and row.get(field) not in (None, "", [], {}):
            root_member_axis_claim = True

    selected_payload = envelope.get("payload") if envelope.get("valid") is True else None
    payload_ids = (
        canonical_payload_member_axis_ids(selected_payload.get("matched_member_axis_ids"))
        if isinstance(selected_payload, Mapping)
        else ()
    )
    member_axis_claim = bool(root_member_axis_claim or payload_ids)
    if not member_axis_claim:
        return []
    if runtime_reduced_risk_trade_admission_contract_valid(
        row,
        executable_authority_stage=executable_authority_stage,
    ):
        root_id_sets: list[tuple[str, tuple[str, ...]]] = []
        invalid_root_id_value_present = False
        for field in FINALIZED_EXECUTABLE_MEMBER_AXIS_ID_FIELDS:
            if field not in row:
                continue
            value = row.get(field)
            field_ids = stable_member_axis_ids(value)
            if not field_ids:
                if value not in (None, "", [], {}):
                    invalid_root_id_value_present = True
                continue
            root_id_sets.append((field, field_ids))
        reasons: list[str] = []
        if invalid_root_id_value_present:
            reasons.append("member_axis_id_alias_contains_non_stable_value")
        if positive_counts and not root_id_sets:
            reasons.append(
                "nonrequired_trade_admission_member_axis_count_without_exact_ids"
            )
        if root_id_sets:
            reference_ids = root_id_sets[0][1]
            if any(ids != reference_ids for _field, ids in root_id_sets[1:]):
                reasons.append("member_axis_id_aliases_mismatch_each_other")
            if positive_counts and max(positive_counts) > len(reference_ids):
                reasons.append(
                    "member_axis_count_exceeds_exact_stable_member_axis_id_count"
                )
        return reasons
    if envelope.get("valid") is not True or not isinstance(selected_payload, Mapping):
        return [
            "selected_immutable_authority_payload_missing_or_invalid_for_member_axis_identity"
        ]
    if not payload_ids:
        return [
            "selected_immutable_authority_payload_matched_member_axis_ids_not_canonical_nonempty"
        ]

    selected_surface = envelope.get("surface")
    selected_source = str(envelope.get("source") or "selected_authority")
    trusted_surfaces: list[tuple[str, Mapping[str, Any]]] = [("root", row)]
    if isinstance(selected_surface, Mapping) and selected_surface is not row:
        trusted_surfaces.append((selected_source, selected_surface))

    alias_id_sets: list[tuple[str, tuple[str, ...]]] = []
    invalid_id_value_present = False
    seen_surfaces: set[int] = set()
    for path, surface in trusted_surfaces:
        surface_id = id(surface)
        if surface_id in seen_surfaces:
            continue
        seen_surfaces.add(surface_id)
        for field in FINALIZED_EXECUTABLE_MEMBER_AXIS_COUNT_FIELDS:
            if field not in surface:
                continue
            count = numeric_or_none(surface.get(field))
            if count is not None and count > 0.0:
                positive_counts.append(count)
        for field in FINALIZED_EXECUTABLE_MEMBER_AXIS_ID_FIELDS:
            if field not in surface:
                continue
            value = surface.get(field)
            field_ids = stable_member_axis_ids(value)
            if not field_ids:
                if value not in (None, "", [], {}):
                    invalid_id_value_present = True
                continue
            alias_id_sets.append((f"{path}.{field}", field_ids))
    reasons: list[str] = []
    if invalid_id_value_present:
        reasons.append("member_axis_id_alias_contains_non_stable_value")
    if any(ids != payload_ids for _path, ids in alias_id_sets):
        reasons.append(
            "member_axis_id_aliases_mismatch_selected_signed_authority_payload"
        )
    if positive_counts and max(positive_counts) > len(payload_ids):
        reasons.append("member_axis_count_exceeds_exact_stable_member_axis_id_count")
    return reasons


