def package_new_entry_authority_payload_atom_reasons(
    payload: Mapping[str, Any],
) -> list[str]:
    reasons: list[str] = []
    for atom_class, fields in PACKAGE_NEW_ENTRY_AUTHORITY_REQUIRED_PAYLOAD_ATOMS.items():
        for field in fields:
            if field not in payload:
                reasons.append(
                    f"package_new_entry_authority_payload_atom_missing:{atom_class}:{field}"
                )
                continue
            value = payload.get(field)
            invalid = False
            if field in PACKAGE_NEW_ENTRY_AUTHORITY_REQUIRED_SEQUENCE_ATOMS:
                invalid = not isinstance(value, list)
            elif field in PACKAGE_NEW_ENTRY_AUTHORITY_REQUIRED_BOOLEAN_ATOMS:
                invalid = not isinstance(value, bool)
            elif field in PACKAGE_NEW_ENTRY_AUTHORITY_REQUIRED_NUMERIC_ATOMS:
                invalid = (
                    isinstance(value, bool)
                    or not isinstance(value, (int, float))
                    or not math.isfinite(float(value))
                )
            elif field == "matched_member_axis_ids":
                invalid = not canonical_payload_member_axis_ids(value)
            elif field == "candidate_decision_quality_field_sources":
                invalid = not isinstance(value, Mapping) or not value
            elif field not in PACKAGE_NEW_ENTRY_AUTHORITY_EMPTY_POLICY_ATOMS:
                invalid = value in (None, "", [], {})
            if invalid:
                reasons.append(
                    f"package_new_entry_authority_payload_atom_invalid:{atom_class}:{field}"
                )
    return reasons


def broad_summary_requires_immutable_package_new_entry_authority_payload(
    summary: Mapping[str, Any],
) -> bool:
    return bool(
        summary.get("schema") == BROAD_REPLAY_IMMUTABLE_AUTHORITY_SUMMARY_SCHEMA
    )


def broad_summary_package_new_entry_authority_payload_contract_issues(
    summary: Mapping[str, Any],
) -> list[str]:
    contract = summary.get("package_new_entry_authority_payload_contract")
    required = summary.get(
        "package_new_entry_authority_payload_required_for_signed_executable_rows"
    )
    schema = summary.get("schema")
    immutable_schema = schema == BROAD_REPLAY_IMMUTABLE_AUTHORITY_SUMMARY_SCHEMA
    if not immutable_schema and contract in (None, "") and required in (None, ""):
        return []
    issues: list[str] = []
    if not immutable_schema:
        issues.append(
            "broad_summary_immutable_authority_contract_requires_summary_v2"
        )
    if contract != PACKAGE_NEW_ENTRY_AUTHORITY_IMMUTABLE_PAYLOAD_CONTRACT:
        issues.append(
            "broad_summary_package_new_entry_authority_payload_contract_invalid"
        )
    if required is not True:
        issues.append(
            "broad_summary_package_new_entry_authority_payload_requirement_not_true"
        )
    return issues


def broad_summary_candidate_relational_materialization_issues(
    summary: Mapping[str, Any],
) -> list[str]:
    if not (
        summary.get("candidate_ledger_omitted") is True
        and summary.get("candidate_index_ledger_omitted") is True
    ):
        return []
    issues: list[str] = []
    relational = summary.get("candidate_relational_materialization")
    if not isinstance(relational, Mapping):
        return ["broad_summary_candidate_relational_materialization_missing"]
    if relational.get("schema") != (
        "gtos.final_moonshot.broad_replay.candidate_relational_materialization.v1"
    ):
        issues.append("broad_summary_candidate_relational_schema_invalid")
    if relational.get("enabled") is not True:
        issues.append("broad_summary_candidate_relational_not_enabled")
    if relational.get("exact") is not True:
        issues.append("broad_summary_candidate_relational_materialization_not_exact")
    if relational.get("status") != (
        "exact_candidate_equals_missed_order_trade_union"
    ):
        issues.append("broad_summary_candidate_relational_status_invalid")
    candidate_rows = int(summary.get("candidate_rows") or 0)
    relational_rows = int(relational.get("candidate_rows") or 0)
    relational_unique = int(
        relational.get("candidate_unique_profile_scoped_instance_keys") or 0
    )
    terminal_unique = int(
        relational.get("terminal_union_unique_profile_scoped_instance_keys")
        or 0
    )
    if candidate_rows != relational_rows:
        issues.append("broad_summary_candidate_relational_row_count_mismatch")
    if relational_unique != relational_rows:
        issues.append("broad_summary_candidate_relational_candidate_unique_mismatch")
    if terminal_unique != relational_unique:
        issues.append("broad_summary_candidate_relational_terminal_union_mismatch")
    if int(
        relational.get("candidate_duplicate_profile_scoped_instance_rows") or 0
    ):
        issues.append("broad_summary_candidate_relational_duplicate_candidates")
    if int(relational.get("candidate_minus_terminal_union_count") or 0):
        issues.append("broad_summary_candidate_relational_missing_terminal_rows")
    if int(relational.get("terminal_union_minus_candidate_count") or 0):
        issues.append("broad_summary_candidate_relational_extra_terminal_rows")
    missing_counts = relational.get("missing_instance_key_counts")
    missing_counts = missing_counts if isinstance(missing_counts, Mapping) else {}
    required_missing_count_keys = {"candidate", "missed", "order", "trade"}
    if not required_missing_count_keys.issubset(missing_counts):
        issues.append(
            "broad_summary_candidate_relational_missing_key_accounting_incomplete"
        )
    if any(int(value or 0) for value in missing_counts.values()):
        issues.append("broad_summary_candidate_relational_instance_keys_missing")
    if int(summary.get("candidate_rows_written") or 0):
        issues.append("broad_summary_omitted_candidate_rows_were_written")
    if int(summary.get("candidate_index_rows_written") or 0):
        issues.append("broad_summary_omitted_candidate_index_rows_were_written")
    if int(
        summary.get("candidate_rows_serialized_in_dedicated_candidate_ledger")
        or 0
    ):
        issues.append("broad_summary_omitted_candidate_dedicated_rows_nonzero")
    artifacts = summary.get("artifacts")
    artifacts = artifacts if isinstance(artifacts, Mapping) else {}
    if artifacts.get("candidate") not in (None, ""):
        issues.append("broad_summary_omitted_candidate_artifact_path_present")
    if artifacts.get("candidate_index") not in (None, ""):
        issues.append("broad_summary_omitted_candidate_index_artifact_path_present")
    return issues


def broad_summary_requires_ultimate_package_runtime_input_contract(
    summary: Mapping[str, Any],
) -> bool:
    """Limit the new dependency proof to current compact relational runs."""

    return bool(
        summary.get("schema") == BROAD_REPLAY_IMMUTABLE_AUTHORITY_SUMMARY_SCHEMA
        and summary.get("candidate_ledger_omitted") is True
        and summary.get("candidate_index_ledger_omitted") is True
        and summary.get("decision_ledger_compacted") is True
        and summary.get("scorecard_ledger_compacted") is True
    )


def broad_summary_ultimate_package_runtime_input_contract_issues(
    summary: Mapping[str, Any],
) -> list[str]:
    if not broad_summary_requires_ultimate_package_runtime_input_contract(summary):
        return []
    contract = summary.get("ultimate_package_runtime_input_contract")
    if not isinstance(contract, Mapping):
        return ["broad_summary_ultimate_package_runtime_input_contract_missing"]

    issues: list[str] = []
    if contract.get("schema") != ULTIMATE_PACKAGE_RUNTIME_INPUT_CONTRACT_SCHEMA:
        issues.append(
            "broad_summary_ultimate_package_runtime_input_contract_schema_invalid"
        )
    if contract.get("valid") is not True:
        issues.append(
            "broad_summary_ultimate_package_runtime_input_contract_not_valid"
        )
    if contract.get("status") != "complete_runtime_authority_inputs_bound":
        issues.append(
            "broad_summary_ultimate_package_runtime_input_contract_status_invalid"
        )
    if contract.get("member_axis_execution_authority_required") is not True:
        issues.append(
            "broad_summary_ultimate_package_member_axis_not_required"
        )
    if contract.get("full_82_sleeve_surface_required") is not True:
        issues.append("broad_summary_ultimate_package_full_surface_not_required")
    if int(contract.get("expected_sleeve_count") or 0) != 82:
        issues.append("broad_summary_ultimate_package_expected_sleeve_count_invalid")
    if int(contract.get("expected_member_axis_count") or 0) != 1101:
        issues.append(
            "broad_summary_ultimate_package_expected_member_axis_count_invalid"
        )
    if contract.get("invalid_input_runtime_effect") != "fail_before_run_campaign":
        issues.append(
            "broad_summary_ultimate_package_invalid_input_runtime_effect_invalid"
        )
    if contract.get("failure_reasons") not in ([], ()):
        issues.append(
            "broad_summary_ultimate_package_runtime_input_failures_present"
        )

    inputs = contract.get("inputs")
    if not isinstance(inputs, Mapping):
        return [
            *issues,
            "broad_summary_ultimate_package_runtime_input_entries_missing",
        ]
    for input_name, expectation in ULTIMATE_PACKAGE_RUNTIME_INPUT_EXPECTATIONS.items():
        expected_rows = int(expectation["rows"])
        input_contract = inputs.get(input_name)
        prefix = f"broad_summary_ultimate_package_{input_name}"
        if not isinstance(input_contract, Mapping):
            issues.append(f"{prefix}_contract_missing")
            continue
        if input_contract.get("valid") is not True:
            issues.append(f"{prefix}_contract_not_valid")
        if input_contract.get("status") != "runtime_input_valid":
            issues.append(f"{prefix}_status_invalid")
        if input_contract.get("identity_field") != expectation["identity_field"]:
            issues.append(f"{prefix}_identity_field_invalid")
        if input_contract.get("expected_schema") != expectation["schema"]:
            issues.append(f"{prefix}_expected_schema_invalid")
        if int(input_contract.get("expected_row_count") or 0) != expected_rows:
            issues.append(f"{prefix}_expected_row_count_invalid")
        if int(input_contract.get("row_count") or 0) != expected_rows:
            issues.append(f"{prefix}_row_count_invalid")
        if int(input_contract.get("unique_identity_count") or 0) != expected_rows:
            issues.append(f"{prefix}_unique_identity_count_invalid")
        if int(input_contract.get("bytes") or 0) <= 0:
            issues.append(f"{prefix}_bytes_missing")
        digest = str(input_contract.get("sha256") or "")
        if len(digest) != 64 or any(
            character not in "009abcdef" for character in digest.lower()
        ):
            issues.append(f"{prefix}_sha256_invalid")
        if not str(input_contract.get("path") or "").strip():
            issues.append(f"{prefix}_path_missing")
        for field in (
            "missing_identity_rows",
            "duplicate_identity_rows",
            "schema_mismatch_rows",
            "invalid_json_rows",
            "non_mapping_rows",
        ):
            if int(input_contract.get(field) or 0):
                issues.append(f"{prefix}_{field}_nonzero")
        if input_contract.get("issues") not in ([], ()):
            issues.append(f"{prefix}_issues_present")
    return issues


def broad_summary_capacity_safe_chunk_execution_issues(
    summary: Mapping[str, Any],
) -> list[str]:
    """Verify the current opt-in broad chunk cleanup and continuity contract."""

    if summary.get("capacity_safe_chunk_execution_required") is not True:
        return []
    contract = summary.get("capacity_safe_chunk_execution_contract")
    if not isinstance(contract, Mapping):
        return ["broad_summary_capacity_safe_chunk_execution_contract_missing"]
    issues: list[str] = []
    if contract.get("schema") != BROAD_REPLAY_CAPACITY_SAFE_CHUNK_EXECUTION_SCHEMA:
        issues.append("broad_summary_capacity_safe_chunk_execution_schema_invalid")
    if contract.get("valid") is not True:
        issues.append("broad_summary_capacity_safe_chunk_execution_not_valid")
    if contract.get("status") != "complete_capacity_safe_chunk_execution":
        issues.append("broad_summary_capacity_safe_chunk_execution_status_invalid")
    planned = int(contract.get("planned_chunk_count") or 0)
    completed = int(contract.get("completed_chunk_count") or 0)
    checkpoint_count = int(contract.get("cleanup_checkpoint_count") or 0)
    if planned <= 0:
        issues.append("broad_summary_capacity_safe_chunk_planned_count_invalid")
    if completed != planned:
        issues.append("broad_summary_capacity_safe_chunk_completion_count_mismatch")
    if checkpoint_count != completed:
        issues.append("broad_summary_capacity_safe_chunk_checkpoint_count_mismatch")
    if int(contract.get("configured_chunk_size") or 0) <= 0:
        issues.append("broad_summary_capacity_safe_chunk_size_invalid")
    for field in (
        "same_simulated_broker_reused_across_chunks",
        "same_account_state_reused_across_chunks",
        "selected_order_sequence_monotonic_across_chunks",
        "completed_chunk_day_scoped_source_caches_released",
        "completed_source_authority_scoped_caches_released",
        "completed_replay_source_caches_released",
        "explicit_gc_requirement_satisfied",
        "cleanup_complete_for_all_completed_chunks",
        "caller_automatic_gc_state_restored_after_harness",
    ):
        if contract.get(field) is not True:
            issues.append(f"broad_summary_capacity_safe_chunk_{field}_not_true")
    if planned > 1 and contract.get(
        "explicit_gc_after_result_release_enabled"
    ) is not True:
        issues.append("broad_summary_capacity_safe_chunk_explicit_gc_not_enabled")
    if contract.get("automatic_gc_disabled_during_replay_chunks") is not True:
        issues.append("broad_summary_capacity_safe_chunk_automatic_gc_not_disabled")
    if contract.get("automatic_gc_reenabled_between_chunks") is not False:
        issues.append(
            "broad_summary_capacity_safe_chunk_automatic_gc_reenable_claim_invalid"
        )
    if contract.get("current_chunk_cleanup_pending") is not False:
        issues.append("broad_summary_capacity_safe_chunk_cleanup_still_pending")
    checkpoints = contract.get("checkpoints")
    if not isinstance(checkpoints, list) or len(checkpoints) != completed:
        issues.append("broad_summary_capacity_safe_chunk_checkpoints_invalid")
        return issues
    prior_ending_by_profile: dict[str, int] = {}
    for index, checkpoint in enumerate(checkpoints):
        if not isinstance(checkpoint, Mapping):
            issues.append(
                f"broad_summary_capacity_safe_chunk_checkpoint_not_mapping:{index}"
            )
            continue
        if checkpoint.get("cleanup_status") != "completed":
            issues.append(
                f"broad_summary_capacity_safe_chunk_cleanup_not_completed:{index}"
            )
        for field in (
            "broker_object_continuity",
            "account_object_continuity",
            "selected_order_sequence_monotonic",
        ):
            if checkpoint.get(field) is not True:
                issues.append(
                    f"broad_summary_capacity_safe_chunk_{field}_invalid:{index}"
                )
        if planned > 1 and checkpoint.get("explicit_gc_completed") is not True:
            issues.append(
                f"broad_summary_capacity_safe_chunk_gc_not_completed:{index}"
            )
        if checkpoint.get(
            "automatic_gc_enabled_before_explicit_collection"
        ) is not False or checkpoint.get(
            "automatic_gc_enabled_after_explicit_collection"
        ) is not False:
            issues.append(
                f"broad_summary_capacity_safe_chunk_automatic_gc_state_invalid:{index}"
            )
        release = checkpoint.get("source_cache_release")
        if not isinstance(release, Mapping) or int(
            release.get("completed_chunk_day_scoped_entries_remaining") or 0
        ):
            issues.append(
                f"broad_summary_capacity_safe_chunk_source_cache_release_invalid:{index}"
            )
        if not isinstance(release, Mapping) or int(
            release.get("completed_source_authority_scoped_entries_remaining")
            or 0
        ):
            issues.append(
                "broad_summary_capacity_safe_chunk_source_authority_cache_"
                f"release_invalid:{index}"
            )
        if not isinstance(release, Mapping) or release.get(
            "completed_replay_source_caches_released"
        ) is not True:
            issues.append(
                "broad_summary_capacity_safe_chunk_replay_source_cache_"
                f"release_invalid:{index}"
            )
        if not isinstance(release, Mapping) or int(
            release.get("completed_replay_source_cache_entries_remaining") or 0
        ):
            issues.append(
                "broad_summary_capacity_safe_chunk_replay_source_cache_"
                f"entries_remaining:{index}"
            )
        replay_cache_after = (
            release.get("replay_source_cache_after")
            if isinstance(release, Mapping)
            else None
        )
        expected_replay_cache_keys = {
            "closed_bar_index",
            "row_time_index",
            "predecision_tick_query",
        }
        if not isinstance(replay_cache_after, Mapping) or not expected_replay_cache_keys.issubset(
            replay_cache_after
        ):
            issues.append(
                "broad_summary_capacity_safe_chunk_replay_source_cache_"
                f"counts_missing:{index}"
            )
        elif any(
            int(replay_cache_after.get(key) or 0) != 0
            for key in expected_replay_cache_keys
        ):
            issues.append(
                "broad_summary_capacity_safe_chunk_replay_source_cache_"
                f"counts_nonzero:{index}"
            )
        profile = str(checkpoint.get("profile") or "")
        starting = int(checkpoint.get("starting_order_sequence") or 0)
        ending = int(checkpoint.get("ending_order_sequence") or 0)
        if ending < starting:
            issues.append(
                f"broad_summary_capacity_safe_chunk_order_sequence_decreased:{index}"
            )
        if profile in prior_ending_by_profile and starting != prior_ending_by_profile[profile]:
            issues.append(
                f"broad_summary_capacity_safe_chunk_order_sequence_discontinuous:{index}"
            )
        prior_ending_by_profile[profile] = ending
    return issues


def broad_summary_source_authority_chunk_invariance_issues(
    summary: Mapping[str, Any],
) -> list[str]:
    """Verify full-window authority and each chunk's exact M1 subset."""

    if summary.get("source_authority_chunk_invariance_required") is not True:
        return []
    contract = summary.get("source_authority_chunk_invariance_contract")
    if not isinstance(contract, Mapping):
        return ["broad_summary_source_authority_chunk_invariance_contract_missing"]
    issues: list[str] = []
    contract_schema = str(contract.get("schema") or "")
    current_v2_contract = (
        contract_schema
        == BROAD_REPLAY_SOURCE_AUTHORITY_CHUNK_INVARIANCE_SCHEMA
    )
    if contract_schema not in {
        BROAD_REPLAY_SOURCE_AUTHORITY_CHUNK_INVARIANCE_SCHEMA,
        BROAD_REPLAY_SOURCE_AUTHORITY_CHUNK_INVARIANCE_HISTORICAL_SCHEMA,
    }:
        issues.append("broad_summary_source_authority_chunk_invariance_schema_invalid")
    if contract.get("valid") is not True:
        issues.append("broad_summary_source_authority_chunk_invariance_not_valid")
    if contract.get("status") != "complete_source_authority_chunk_invariance":
        issues.append("broad_summary_source_authority_chunk_invariance_status_invalid")
    if (
        contract.get("source_authority_scope_mode")
        != BROAD_REPLAY_SOURCE_AUTHORITY_SCOPE_MODE
    ):
        issues.append("broad_summary_source_authority_scope_mode_invalid")
    planned = int(contract.get("planned_chunk_count") or 0)
    completed = int(contract.get("completed_chunk_count") or 0)
    checkpoint_count = int(contract.get("checkpoint_count") or 0)
    if planned <= 0:
        issues.append("broad_summary_source_authority_planned_count_invalid")
    if completed != planned:
        issues.append("broad_summary_source_authority_completion_count_mismatch")
    if checkpoint_count != completed:
        issues.append("broad_summary_source_authority_checkpoint_count_mismatch")
    if int(contract.get("canonical_plan_count") or 0) <= 0:
        issues.append("broad_summary_source_authority_canonical_plan_count_invalid")
    if contract.get("current_chunk_pending") is not False:
        issues.append("broad_summary_source_authority_chunk_still_pending")
    for field in (
        "all_execution_days_inside_authority_scope",
        "all_source_plans_valid",
        "all_chunk_source_plans_match_canonical",
    ):
        if contract.get(field) is not True:
            issues.append(f"broad_summary_source_authority_{field}_not_true")
    canonical_plans = contract.get("canonical_plans")
    if not isinstance(canonical_plans, Mapping) or len(canonical_plans) != int(
        contract.get("canonical_plan_count") or 0
    ):
        issues.append("broad_summary_source_authority_canonical_plans_invalid")
    else:
        for key, plan in canonical_plans.items():
            if not isinstance(plan, Mapping):
                issues.append(f"broad_summary_source_authority_plan_not_mapping:{key}")
                continue
            scope = plan.get("source_authority_scope")
            scope = scope if isinstance(scope, Mapping) else {}
            digest = str(plan.get("plan_digest_sha256") or "")
            if (
                current_v2_contract
                and plan.get("schema")
                != BROAD_REPLAY_SOURCE_AUTHORITY_PLAN_SCHEMA
            ):
                issues.append(
                    f"broad_summary_source_authority_plan_schema_invalid:{key}"
                )
            if plan.get("valid") is not True:
                issues.append(f"broad_summary_source_authority_plan_not_valid:{key}")
            if scope.get("mode") != BROAD_REPLAY_SOURCE_AUTHORITY_SCOPE_MODE:
                issues.append(f"broad_summary_source_authority_plan_scope_invalid:{key}")
            if not scope.get("days"):
                issues.append(f"broad_summary_source_authority_plan_days_missing:{key}")
            if len(digest) != 64:
                issues.append(f"broad_summary_source_authority_plan_digest_invalid:{key}")
            if current_v2_contract:
                requested_symbol_count = int(
                    plan.get("requested_symbol_count") or 0
                )
                if requested_symbol_count <= 0 or int(
                    plan.get("resolved_symbol_count") or 0
                ) != requested_symbol_count:
                    issues.append(
                        "broad_summary_source_authority_plan_symbol_count_"
                        f"invalid:{key}"
                    )
                if plan.get("missing_symbols") or plan.get(
                    "incomplete_sources"
                ):
                    issues.append(
                        "broad_summary_source_authority_plan_source_gaps_"
                        f"present:{key}"
                    )
                expected_static = int(
                    plan.get("expected_static_source_row_count") or 0
                )
                if expected_static <= 0 or int(
                    plan.get("static_source_row_count") or 0
                ) != expected_static:
                    issues.append(
                        "broad_summary_source_authority_plan_static_count_"
                        f"invalid:{key}"
                    )
                expected_m1 = int(
                    plan.get(
                        "expected_m1_symbol_day_authority_row_count"
                    )
                    or 0
                )
                if (
                    expected_m1 <= 0
                    or int(
                        plan.get("m1_symbol_day_authority_row_count") or 0
                    )
                    != expected_m1
                    or int(
                        plan.get(
                            "m1_symbol_day_authority_unique_id_count"
                        )
                        or 0
                    )
                    != expected_m1
                    or int(
                        plan.get("m1_unresolved_symbol_day_count") or 0
                    )
                    != 0
                ):
                    issues.append(
                        "broad_summary_source_authority_plan_m1_count_"
                        f"invalid:{key}"
                    )
                if int(
                    plan.get("tick_window_authority_row_count") or 0
                ) != requested_symbol_count:
                    issues.append(
                        "broad_summary_source_authority_plan_tick_count_"
                        f"invalid:{key}"
                    )
                if plan.get("tick_window_integrity_failure_symbols"):
                    issues.append(
                        "broad_summary_source_authority_plan_tick_integrity_"
                        f"invalid:{key}"
                    )
                for digest_field in (
                    "static_source_digest_sha256",
                    "m1_day_plan_digest_sha256",
                    "tick_window_plan_digest_sha256",
                    "tick_component_source_digest_sha256",
                ):
                    if len(str(plan.get(digest_field) or "")) != 64:
                        issues.append(
                            "broad_summary_source_authority_plan_"
                            f"{digest_field}_invalid:{key}"
                        )
                requested_symbols = tuple(
                    str(symbol) for symbol in plan.get("requested_symbols") or ()
                )
                scope_days = tuple(
                    str(day) for day in scope.get("days") or ()
                )
                static_rows = [
                    row
                    for row in plan.get("static_source_rows") or ()
                    if isinstance(row, Mapping)
                ]
                m1_rows = [
                    row
                    for row in plan.get("m1_symbol_day_authority_rows") or ()
                    if isinstance(row, Mapping)
                ]
                tick_rows = [
                    row
                    for row in plan.get("tick_window_authority_rows") or ()
                    if isinstance(row, Mapping)
                ]
                expected_static_keys = {
                    (symbol, timeframe)
                    for symbol in requested_symbols
                    for timeframe in ("D1", "H4", "H1", "M15")
                }
                actual_static_keys = [
                    (str(row.get("symbol")), str(row.get("timeframe")))
                    for row in static_rows
                ]
                if (
                    set(actual_static_keys) != expected_static_keys
                    or len(actual_static_keys) != len(set(actual_static_keys))
                ):
                    issues.append(
                        "broad_summary_source_authority_plan_static_join_"
                        f"invalid:{key}"
                    )
                expected_m1_keys = {
                    (symbol, day)
                    for symbol in requested_symbols
                    for day in scope_days
                }
                actual_m1_keys = [
                    (str(row.get("symbol")), str(row.get("trading_day")))
                    for row in m1_rows
                ]
                if (
                    set(actual_m1_keys) != expected_m1_keys
                    or len(actual_m1_keys) != len(set(actual_m1_keys))
                ):
                    issues.append(
                        "broad_summary_source_authority_plan_m1_symbol_day_"
                        f"join_invalid:{key}"
                    )
                if any(
                    len(str(row.get("source_day_authority_id") or "")) < 24
                    or len(
                        str(
                            row.get(
                                "source_day_authority_hash_sha256"
                            )
                            or ""
                        )
                    )
                    != 64
                    or row.get("diagnostic_fallback_only") is True
                    for row in m1_rows
                ):
                    issues.append(
                        "broad_summary_source_authority_plan_m1_disposition_"
                        f"invalid:{key}"
                    )
                actual_tick_symbols = [
                    str(row.get("symbol")) for row in tick_rows
                ]
                if (
                    set(actual_tick_symbols) != set(requested_symbols)
                    or len(actual_tick_symbols)
                    != len(set(actual_tick_symbols))
                    or any(
                        row.get("status") not in {"covered", "partial", "none"}
                        or row.get("integrity_valid") is not True
                        for row in tick_rows
                    )
                ):
                    issues.append(
                        "broad_summary_source_authority_plan_tick_window_"
                        f"join_invalid:{key}"
                    )
                recomputed_static_digest = stable_projection_sha256(
                    static_rows
                )
                recomputed_m1_digest = stable_projection_sha256(m1_rows)
                recomputed_tick_digest = stable_projection_sha256(tick_rows)
                recomputed_tick_component_digest = stable_projection_sha256(
                    [
                        {
                            "symbol": row.get("symbol"),
                            "components": row.get("components"),
                        }
                        for row in tick_rows
                    ]
                )
                if (
                    plan.get("static_source_digest_sha256")
                    != recomputed_static_digest
                    or plan.get("m1_day_plan_digest_sha256")
                    != recomputed_m1_digest
                    or plan.get("tick_window_plan_digest_sha256")
                    != recomputed_tick_digest
                    or plan.get("tick_component_source_digest_sha256")
                    != recomputed_tick_component_digest
                ):
                    issues.append(
                        "broad_summary_source_authority_plan_component_digest_"
                        f"mismatch:{key}"
                    )
                digest_payload = {
                    "source_authority_scope": scope,
                    "requested_symbols": list(requested_symbols),
                    "missing_symbols": list(plan.get("missing_symbols") or ()),
                    "incomplete_sources": list(
                        plan.get("incomplete_sources") or ()
                    ),
                    "static_source_digest_sha256": recomputed_static_digest,
                    "m1_day_plan_digest_sha256": recomputed_m1_digest,
                    "tick_window_plan_digest_sha256": recomputed_tick_digest,
                    "tick_component_source_digest_sha256": (
                        recomputed_tick_component_digest
                    ),
                }
                if plan.get("plan_digest_sha256") != stable_projection_sha256(
                    digest_payload
                ):
                    issues.append(
                        "broad_summary_source_authority_plan_digest_content_"
                        f"mismatch:{key}"
                    )
    if current_v2_contract:
        preflight_checkpoints = summary.get(
            "source_authority_preflight_checkpoints"
        )
        if (
            not isinstance(preflight_checkpoints, list)
            or len(preflight_checkpoints)
            != int(contract.get("canonical_plan_count") or 0)
        ):
            issues.append(
                "broad_summary_source_authority_preflight_checkpoints_invalid"
            )
        else:
            for index, checkpoint in enumerate(preflight_checkpoints):
                if not isinstance(checkpoint, Mapping):
                    issues.append(
                        "broad_summary_source_authority_preflight_checkpoint_"
                        f"not_mapping:{index}"
                    )
                    continue
                source_plan_key = str(
                    checkpoint.get("source_plan_key") or ""
                )
                plan = (
                    canonical_plans.get(source_plan_key)
                    if isinstance(canonical_plans, Mapping)
                    else None
                )
                if (
                    checkpoint.get("canonical_source_plan_valid") is not True
                    or checkpoint.get("cleanup_valid") is not True
                    or not isinstance(plan, Mapping)
                    or checkpoint.get(
                        "canonical_source_plan_digest_sha256"
                    )
                    != plan.get("plan_digest_sha256")
                ):
                    issues.append(
                        "broad_summary_source_authority_preflight_checkpoint_"
                        f"invalid:{index}"
                    )
    checkpoints = contract.get("checkpoints")
    if not isinstance(checkpoints, list) or len(checkpoints) != completed:
        issues.append("broad_summary_source_authority_checkpoints_invalid")
        return issues
    for index, checkpoint in enumerate(checkpoints):
        if not isinstance(checkpoint, Mapping):
            issues.append(
                f"broad_summary_source_authority_checkpoint_not_mapping:{index}"
            )
            continue
        for field in (
            "execution_days_subset_of_source_authority",
            "source_plan_valid",
            "source_plan_matches_canonical",
        ):
            if checkpoint.get(field) is not True:
                issues.append(
                    f"broad_summary_source_authority_{field}_invalid:{index}"
                )
        if (
            checkpoint.get("source_authority_scope_mode")
            != BROAD_REPLAY_SOURCE_AUTHORITY_SCOPE_MODE
        ):
            issues.append(
                f"broad_summary_source_authority_checkpoint_scope_invalid:{index}"
            )
        digest = str(checkpoint.get("source_plan_digest_sha256") or "")
        canonical_digest = str(
            checkpoint.get("canonical_source_plan_digest_sha256") or ""
        )
        if (
            len(digest) != 64
            or len(canonical_digest) != 64
            or (not current_v2_contract and digest != canonical_digest)
        ):
            issues.append(
                f"broad_summary_source_authority_checkpoint_digest_invalid:{index}"
            )
        if current_v2_contract:
            for field in (
                "static_sources_match_canonical",
                "tick_component_sources_match_canonical",
                "m1_execution_day_authority_matches_canonical",
            ):
                if checkpoint.get(field) is not True:
                    issues.append(
                        f"broad_summary_source_authority_{field}_invalid:{index}"
                    )
            expected_m1_digest = str(
                checkpoint.get(
                    "expected_m1_execution_day_authority_digest_sha256"
                )
                or ""
            )
            actual_m1_digest = str(
                checkpoint.get(
                    "actual_m1_execution_day_authority_digest_sha256"
                )
                or ""
            )
            expected_m1_count = int(
                checkpoint.get(
                    "expected_m1_execution_day_authority_row_count"
                )
                or 0
            )
            actual_m1_count = int(
                checkpoint.get(
                    "actual_m1_execution_day_authority_row_count"
                )
                or 0
            )
            if (
                len(expected_m1_digest) != 64
                or expected_m1_digest != actual_m1_digest
                or expected_m1_count <= 0
                or expected_m1_count != actual_m1_count
            ):
                issues.append(
                    "broad_summary_source_authority_checkpoint_m1_subset_"
                    f"invalid:{index}"
                )
    return issues


def broad_summary_compact_projection_issues(
    summary: Mapping[str, Any],
    poi_scan: Mapping[str, Any],
) -> list[str]:
    """Require compact-mode summaries to match every serialized proof row."""

    issues: list[str] = []
    row_counts = poi_scan.get("row_counts")
    row_counts = row_counts if isinstance(row_counts, Mapping) else {}
    compact_contract = summary.get("broad_replay_compact_ledgers")
    compact_contract = (
        compact_contract if isinstance(compact_contract, Mapping) else {}
    )
    projection_counts = compact_contract.get("compact_projection_counts")
    projection_counts = (
        projection_counts if isinstance(projection_counts, Mapping) else {}
    )
    modes = (
        (
            "decision",
            "decision_ledger_compacted",
            "decision_rows",
            "decision_compact_projection_eligible_rows",
            "decision_compact_projection_rows",
            "decision_projection_schema",
            COMPACT_DECISION_PROJECTION_SCHEMA,
        ),
        (
            "scorecard",
            "scorecard_ledger_compacted",
            "scorecard_rows",
            "scorecard_compact_projection_eligible_rows",
            "scorecard_compact_projection_rows",
            "scorecard_projection_schema",
            COMPACT_SCORECARD_PROJECTION_SCHEMA,
        ),
    )
    for (
        ledger,
        flag_key,
        row_count_key,
        eligible_row_count_key,
        projection_row_count_key,
        schema_key,
        expected_schema,
    ) in modes:
        enabled = summary.get(flag_key) is True
        rows = int(row_counts.get(row_count_key) or 0)
        eligible_rows = int(row_counts.get(eligible_row_count_key) or 0)
        projected_rows = int(row_counts.get(projection_row_count_key) or 0)
        declared_input_rows = int(
            projection_counts.get(f"{ledger}_input_rows") or 0
        )
        declared_rows = int(projection_counts.get(row_count_key) or 0)
        declared_eligible_rows = int(
            projection_counts.get(f"{ledger}_projection_eligible_rows") or 0
        )
        if enabled:
            if rows <= 0:
                issues.append(
                    f"broad_summary_compact_{ledger}_ledger_missing_or_empty"
                )
            if projected_rows != eligible_rows:
                issues.append(
                    f"broad_summary_compact_{ledger}_projection_incomplete"
                )
            if compact_contract.get(schema_key) != expected_schema:
                issues.append(
                    f"broad_summary_compact_{ledger}_projection_schema_invalid"
                )
            if declared_input_rows != rows or declared_rows != rows:
                issues.append(
                    f"broad_summary_compact_{ledger}_input_count_mismatch"
                )
            if declared_eligible_rows != eligible_rows:
                issues.append(
                    f"broad_summary_compact_{ledger}_projection_count_mismatch"
                )
        elif projected_rows:
            issues.append(
                f"broad_summary_compact_{ledger}_rows_present_without_mode"
            )
    return issues


def b7_5_execution_contract_authority_partition(
    shared: Mapping[str, Any],
) -> dict[str, Any]:
    behavioral = {
        field: shared.get(field)
        for field in B7_5_BEHAVIORAL_EXECUTION_CONTRACT_FIELDS
    }
    behavioral["code_authority"] = [
        row
        for row in shared.get("code_authority") or ()
        if isinstance(row, Mapping)
        and str(row.get("path") or "")
        not in B7_5_POSTRUN_PROOF_CONSUMER_CODE_PATHS
    ]
    behavioral["missing_code_paths"] = [
        str(path)
        for path in shared.get("missing_code_paths") or ()
        if str(path) not in B7_5_POSTRUN_PROOF_CONSUMER_CODE_PATHS
    ]
    proof = {
        "schema": "gtos.final_moonshot.b7_5.postrun_proof_consumers.v1",
        "code_authority": [
            row
            for row in shared.get("code_authority") or ()
            if isinstance(row, Mapping)
            and str(row.get("path") or "")
            in B7_5_POSTRUN_PROOF_CONSUMER_CODE_PATHS
        ],
        "missing_code_paths": [
            str(path)
            for path in shared.get("missing_code_paths") or ()
            if str(path) in B7_5_POSTRUN_PROOF_CONSUMER_CODE_PATHS
        ],
    }
    proof_paths = {
        str(row.get("path") or "")
        for row in proof["code_authority"]
        if isinstance(row, Mapping)
    }
    return {
        "schema": "gtos.final_moonshot.b7_5.execution_contract_partition.v1",
        "valid": bool(
            proof_paths == B7_5_POSTRUN_PROOF_CONSUMER_CODE_PATHS
            and not proof["missing_code_paths"]
        ),
        "behavioral_execution_contract_digest_sha256": (
            stable_projection_sha256(behavioral)
        ),
        "behavioral_execution_contract_projection": behavioral,
        "postrun_proof_consumer_contract_digest_sha256": (
            stable_projection_sha256(proof)
        ),
        "postrun_proof_consumer_contract_projection": proof,
        "legacy_full_shared_execution_contract_digest_sha256": shared.get(
            "shared_execution_contract_digest_sha256"
        ),
        "legacy_full_digest_semantics": (
            "compatibility_only_includes_behavior_and_postrun_proof_consumers"
        ),
        "excluded_from_behavioral_digest": sorted(
            B7_5_POSTRUN_PROOF_CONSUMER_CODE_PATHS
        ),
    }


def b7_5_extended_history_source_window_contract_issues(
    contract: Mapping[str, Any],
) -> list[str]:
    """Verify replay-free source, selector, capacity, and config bindings."""

    if not contract:
        return ["b7_5_extended_history_source_window_contract_missing"]
    issues: list[str] = []
    if contract.get("schema") != (
        B7_5_EXTENDED_HISTORY_SOURCE_WINDOW_CONTRACT_SCHEMA
    ):
        issues.append("b7_5_source_window_contract_schema_invalid")
    if contract.get("valid") is not True:
        issues.append("b7_5_source_window_contract_not_valid")
    if contract.get("replay_free_builder") is not True or int(
        contract.get("run_campaign_call_count") or 0
    ) != 0:
        issues.append("b7_5_source_window_contract_not_replay_free")
    if any(
        contract.get(field) is not False
        for field in (
            "live_broker_authority",
            "broker_mutation_enabled",
            "final_selection_claim",
        )
    ):
        issues.append("b7_5_source_window_contract_live_boundary_invalid")
    signal_semantics = contract.get("source_bound_signal_semantics")
    signal_semantics = (
        signal_semantics if isinstance(signal_semantics, Mapping) else {}
    )
    if (
        signal_semantics.get("evidence_class")
        != B7_5_SOURCE_BOUND_SIGNAL_EVIDENCE_CLASS
        or signal_semantics.get("additive_allowed") is not False
        or signal_semantics.get("executable_r_percentage_allowed") is not False
        or signal_semantics.get("canonical_window_field")
        != (
            "window_present_member_axis_combined_source_bound_signal_r_"
            "non_additive"
        )
        or signal_semantics.get("legacy_compatibility_alias")
        != "window_available_source_bound_r"
        or signal_semantics.get("legacy_alias_semantics")
        != B7_5_SOURCE_BOUND_LEGACY_ALIAS_SEMANTICS
    ):
        issues.append("b7_5_source_window_signal_semantics_invalid")
    declared_contract_digest = str(
        contract.get("contract_digest_sha256") or ""
    )
    contract_payload = dict(contract)
    contract_payload.pop("contract_digest_sha256", None)
    if declared_contract_digest != stable_projection_sha256(contract_payload):
        issues.append("b7_5_source_window_contract_digest_mismatch")

    shared = contract.get("shared_execution_contract")
    shared = shared if isinstance(shared, Mapping) else {}
    shared_digest = str(
        shared.get("shared_execution_contract_digest_sha256") or ""
    )
    shared_payload = dict(shared)
    for field in (
        "valid",
        "status",
        "shared_execution_contract_digest_sha256",
    ):
        shared_payload.pop(field, None)
    if (
        shared.get("valid") is not True
        or len(shared_digest) != 64
        or shared_digest != stable_projection_sha256(shared_payload)
    ):
        issues.append("b7_5_shared_execution_contract_invalid")
    declared_execution_partition = contract.get(
        "execution_contract_authority_partition"
    )
    declared_execution_partition = (
        declared_execution_partition
        if isinstance(declared_execution_partition, Mapping)
        else {}
    )
    expected_execution_partition = b7_5_execution_contract_authority_partition(
        shared
    )
    if (
        declared_execution_partition.get("valid") is not True
        or declared_execution_partition != expected_execution_partition
    ):
        issues.append("b7_5_execution_contract_authority_partition_invalid")
    effective_hash_semantics = shared.get(
        "effective_profile_config_hash_semantics"
    )
    effective_hash_semantics = (
        effective_hash_semantics
        if isinstance(effective_hash_semantics, Mapping)
        else {}
    )
    expected_diagnostic_field = (
        "broad_live_as_if_replay_owner_approved_reconstructed_proxy_"
        "selected_policy_expected_net_source_artifact_sha256"
    )
    excluded_runtime_fields = effective_hash_semantics.get(
        "excluded_runtime_fields"
    )
    excluded_runtime_fields = (
        list(excluded_runtime_fields)
        if isinstance(excluded_runtime_fields, (list, tuple))
        else []
    )
    if (
        effective_hash_semantics.get("projection")
        != "execution_semantic_config_excludes_diagnostic_provenance"
        or effective_hash_semantics.get(
            "raw_artifact_sha256_retained_in_runtime_and_ledgers"
        )
        is not True
        or excluded_runtime_fields != [expected_diagnostic_field]
    ):
        issues.append("b7_5_effective_profile_config_hash_semantics_invalid")
    effective_profile_hashes = shared.get("effective_profile_config_hashes")
    effective_profile_hashes = (
        effective_profile_hashes
        if isinstance(effective_profile_hashes, Mapping)
        else {}
    )
    if (
        len(effective_profile_hashes) != 1
        or any(len(str(value or "")) != 64 for value in effective_profile_hashes.values())
    ):
        issues.append("b7_5_effective_profile_config_hashes_invalid")
    runtime_inputs = shared.get("ultimate_package_runtime_input_contract")
    runtime_inputs = runtime_inputs if isinstance(runtime_inputs, Mapping) else {}
    if (
        runtime_inputs.get("valid") is not True
        or int(runtime_inputs.get("expected_sleeve_count") or 0) != 82
        or int(runtime_inputs.get("expected_member_axis_count") or 0) != 1101
    ):
        issues.append("b7_5_runtime_input_contract_invalid")
    if contract.get("unexpected_config_delta_paths") not in ([], ()):
        issues.append("b7_5_unexpected_config_delta_present")

    capacity = contract.get("capacity_projection")
    capacity = capacity if isinstance(capacity, Mapping) else {}
    observed_free_bytes = int(capacity.get("observed_free_bytes") or 0)
    required_free_bytes = int(
        capacity.get("required_free_bytes_before_both_windows") or 0
    )
    capacity_ready = bool(
        capacity.get("valid") is True
        and observed_free_bytes >= required_free_bytes > 0
    )
    if (
        int(capacity.get("planned_chunk_count_total") or 0) != 61
        or int(capacity.get("v258_retained_bytes") or 0) <= 0
        or len(str(capacity.get("v258_size_manifest_sha256") or "")) != 64
        or observed_free_bytes <= 0
        or required_free_bytes <= 0
        or contract.get("new_replay_capacity_ready") is not capacity_ready
        or contract.get("replay_launch_claim") is not False
        or contract.get("capacity_gate_disposition")
        != (
            "new_replay_capacity_ready"
            if capacity_ready
            else "source_contract_valid_new_replay_requires_storage_checkpoint"
        )
    ):
        issues.append("b7_5_capacity_projection_invalid")

    windows = contract.get("windows")
    windows = windows if isinstance(windows, list) else []
    expected_windows = (
        ("b7_5_2026_01", "2026-01-01", "2026-01-31", 31),
        ("b7_5_2026_04", "2026-04-01", "2026-04-30", 30),
    )
    if len(windows) != len(expected_windows):
        issues.append("b7_5_window_count_invalid")
    window_by_id = {
        str(row.get("window_id") or ""): row
        for row in windows
        if isinstance(row, Mapping)
    }
    for window_id, start_day, end_day, day_count in expected_windows:
        window = window_by_id.get(window_id)
        if not isinstance(window, Mapping):
            issues.append(f"b7_5_window_missing:{window_id}")
            continue
        if (
            window.get("start_day") != start_day
            or window.get("end_day") != end_day
            or int(window.get("day_count") or 0) != day_count
        ):
            issues.append(f"b7_5_window_scope_invalid:{window_id}")
        plan = window.get("source_authority_plan")
        plan = plan if isinstance(plan, Mapping) else {}
        expected_m1_rows = 24 * day_count
        if (
            window.get("source_plan_valid") is not True
            or window.get("source_cache_cleanup_valid") is not True
            or plan.get("schema") != BROAD_REPLAY_SOURCE_AUTHORITY_PLAN_SCHEMA
            or plan.get("valid") is not True
            or int(plan.get("requested_symbol_count") or 0) != 24
            or int(plan.get("resolved_symbol_count") or 0) != 24
            or int(plan.get("static_source_row_count") or 0) != 96
            or int(plan.get("m1_symbol_day_authority_row_count") or 0)
            != expected_m1_rows
            or int(plan.get("m1_symbol_day_authority_unique_id_count") or 0)
            != expected_m1_rows
            or int(plan.get("m1_unresolved_symbol_day_count") or 0) != 0
            or int(plan.get("tick_window_authority_row_count") or 0) != 24
            or plan.get("missing_symbols")
            or plan.get("incomplete_sources")
            or plan.get("tick_window_integrity_failure_symbols")
        ):
            issues.append(f"b7_5_source_plan_contract_invalid:{window_id}")
        static_rows = [
            row
            for row in plan.get("static_source_rows") or ()
            if isinstance(row, Mapping)
        ]
        m1_rows = [
            row
            for row in plan.get("m1_symbol_day_authority_rows") or ()
            if isinstance(row, Mapping)
        ]
        tick_rows = [
            row
            for row in plan.get("tick_window_authority_rows") or ()
            if isinstance(row, Mapping)
        ]
        static_digest = stable_projection_sha256(static_rows)
        m1_digest = stable_projection_sha256(m1_rows)
        tick_digest = stable_projection_sha256(tick_rows)
        tick_component_digest = stable_projection_sha256(
            [
                {
                    "symbol": row.get("symbol"),
                    "components": row.get("components"),
                }
                for row in tick_rows
            ]
        )
        if (
            plan.get("static_source_digest_sha256") != static_digest
            or plan.get("m1_day_plan_digest_sha256") != m1_digest
            or plan.get("tick_window_plan_digest_sha256") != tick_digest
            or plan.get("tick_component_source_digest_sha256")
            != tick_component_digest
        ):
            issues.append(f"b7_5_source_plan_component_digest_invalid:{window_id}")
        plan_digest_payload = {
            "source_authority_scope": plan.get("source_authority_scope"),
            "requested_symbols": list(plan.get("requested_symbols") or ()),
            "missing_symbols": list(plan.get("missing_symbols") or ()),
            "incomplete_sources": list(plan.get("incomplete_sources") or ()),
            "static_source_digest_sha256": static_digest,
            "m1_day_plan_digest_sha256": m1_digest,
            "tick_window_plan_digest_sha256": tick_digest,
            "tick_component_source_digest_sha256": tick_component_digest,
        }
        plan_digest = str(plan.get("plan_digest_sha256") or "")
        if plan_digest != stable_projection_sha256(plan_digest_payload):
            issues.append(f"b7_5_source_plan_digest_invalid:{window_id}")

        selector_summary = window.get("selector_disposition_summary")
        selector_summary = (
            selector_summary if isinstance(selector_summary, Mapping) else {}
        )
        dispositions = [
            row
            for row in window.get("selector_axis_dispositions") or ()
            if isinstance(row, Mapping)
        ]
        stable_ids = [
            str(row.get("stable_member_axis_id") or "")
            for row in dispositions
        ]
        canonical_signal_sum = sum(
            float(
                row.get(
                    "window_present_member_axis_combined_source_bound_signal_r_"
                    "non_additive"
                )
                or 0.0
            )
            for row in dispositions
        )
        disposition_signal_semantics_valid = all(
            row.get("combined_source_bound_signal_r_evidence_class")
            == B7_5_SOURCE_BOUND_SIGNAL_EVIDENCE_CLASS
            and row.get("combined_source_bound_signal_r_additive_allowed")
            is False
            and nearly_equal(
                row.get(
                    "window_present_member_axis_combined_source_bound_signal_r_"
                    "non_additive"
                ),
                row.get("window_available_source_bound_r"),
            )
            and row.get("window_available_source_bound_r_semantics")
            == B7_5_SOURCE_BOUND_LEGACY_ALIAS_SEMANTICS
            for row in dispositions
        )
        if (
            window.get("selector_disposition_valid") is not True
            or len(dispositions) != 1101
            or len(set(stable_ids)) != 1101
            or not all(stable_ids)
            or int(selector_summary.get("member_axis_disposition_rows") or 0)
            != 1101
            or int(selector_summary.get("member_axes_present") or 0)
            + int(selector_summary.get("member_axes_absent") or 0)
            != 1101
            or int(
                selector_summary.get(
                    "selector_rows_unmatched_to_package_axis"
                )
                or 0
            )
            != 0
            or selector_summary.get("disposition_digest_sha256")
            != stable_projection_sha256(dispositions)
            or selector_summary.get("source_bound_signal_evidence_class")
            != B7_5_SOURCE_BOUND_SIGNAL_EVIDENCE_CLASS
            or selector_summary.get("source_bound_r_additive_allowed") is not False
            or selector_summary.get(
                "executable_r_to_source_bound_r_percentage_allowed"
            )
            is not False
            or selector_summary.get("window_available_source_bound_r_semantics")
            != B7_5_SOURCE_BOUND_LEGACY_ALIAS_SEMANTICS
            or not nearly_equal(
                selector_summary.get(
                    "window_present_member_axis_combined_source_bound_signal_r_"
                    "non_additive"
                ),
                canonical_signal_sum,
                1e-6,
            )
            or not nearly_equal(
                selector_summary.get("window_available_source_bound_r"),
                canonical_signal_sum,
                1e-6,
            )
            or not disposition_signal_semantics_valid
        ):
            issues.append(f"b7_5_selector_disposition_invalid:{window_id}")
        command = str(window.get("replay_command") or "")
        if (
            f"--expected-shared-execution-contract-sha256 {shared_digest}"
            not in command
            or f"--expected-source-plan-digest-sha256 {plan_digest}"
            not in command
            or "_B7_5_" not in command
        ):
            issues.append(f"b7_5_replay_command_binding_invalid:{window_id}")

    pair_payload = contract.get("pair_binding_payload")
    pair_payload = pair_payload if isinstance(pair_payload, Mapping) else {}
    if contract.get("pair_binding_sha256") != stable_projection_sha256(
        pair_payload
    ):
        issues.append("b7_5_pair_binding_digest_invalid")
    if pair_payload.get("source_bound_signal_semantics_sha256") != (
        stable_projection_sha256(signal_semantics)
    ):
        issues.append("b7_5_pair_binding_signal_semantics_digest_invalid")
    if (
        pair_payload.get("shared_execution_contract_digest_sha256")
        != shared_digest
        or pair_payload.get("behavioral_execution_contract_digest_sha256")
        != expected_execution_partition.get(
            "behavioral_execution_contract_digest_sha256"
        )
        or pair_payload.get(
            "postrun_proof_consumer_contract_digest_sha256"
        )
        != expected_execution_partition.get(
            "postrun_proof_consumer_contract_digest_sha256"
        )
    ):
        issues.append("b7_5_pair_binding_execution_partition_invalid")
    return issues


def b7_5_artifact_file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(8 * 1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def b7_5_extended_history_behavior_issues(
    report: Mapping[str, Any], *, root: Path = ROUTE
) -> list[str]:
    """Verify the normalized B7.5 cross-window behavior proof."""

    if not report:
        return ["b7_5_extended_history_behavior_missing"]
    issues: list[str] = []

    def number(value: Any) -> float:
        try:
            result = float(value)
        except (TypeError, ValueError):
            return 0.0
        return result if math.isfinite(result) else 0.0

    def close(left: Any, right: Any) -> bool:
        return math.isclose(number(left), number(right), abs_tol=1e-8)

    if report.get("schema") != B7_5_EXTENDED_HISTORY_BEHAVIOR_SCHEMA:
        issues.append("b7_5_extended_history_behavior_schema_invalid")
    if report.get("broker_live_final_closed") is not True:
        issues.append("b7_5_extended_history_behavior_live_boundary_invalid")
    windows = [
        row for row in report.get("windows") or () if isinstance(row, Mapping)
    ]
    expected_window_ids = {
        "b7_5_2026_01",
        "b7_5_2026_04",
        "hostile_2026_05",
        "broad_2026_06",
    }
    window_ids = [str(row.get("window_id") or "") for row in windows]
    if (
        int(report.get("window_count") or 0) != 4
        or len(windows) != 4
        or set(window_ids) != expected_window_ids
        or len(set(window_ids)) != 4
    ):
        issues.append("b7_5_extended_history_behavior_window_set_invalid")

    pair = report.get("paired_extended_history")
    pair = pair if isinstance(pair, Mapping) else {}
    paired_ids = list(pair.get("window_ids") or ())
    if (
        int(report.get("paired_extended_history_window_count") or 0) != 2
        or set(paired_ids) != {"b7_5_2026_01", "b7_5_2026_04"}
        or pair.get("same_execution_contract") is not True
        or pair.get("distinct_source_window_contracts") is not True
        or pair.get("pair_binding_valid") is not True
        or pair.get("paired_dates_valid") is not True
        or pair.get("paired_windows_disjoint") is not True
        or pair.get("paired_windows_non_adjacent") is not True
        or pair.get("no_opportunity_collapse") is not True
        or pair.get("stress_rows_present_in_every_window") is not True
        or pair.get("truth_integrity_pass") is not True
        or pair.get("source_window_contract_binding_valid") is not True
        or pair.get("source_window_contract_window_bindings_valid") is not True
        or int(pair.get("non_additive_source_signal_truth_window_count") or 0)
        != 2
    ):
        issues.append("b7_5_extended_history_behavior_pair_truth_invalid")
    behavioral_digests = list(
        pair.get("behavioral_execution_contract_digests_sha256") or ()
    )
    shared_digests = list(
        pair.get("shared_execution_contract_digests_sha256") or ()
    )
    legacy_full_shared_digests = list(
        pair.get("legacy_full_shared_execution_contract_digests_sha256") or ()
    )
    source_digests = list(pair.get("source_plan_digests_sha256") or ())
    if (
        len(behavioral_digests) != 1
        or not looks_like_sha256(behavioral_digests[0])
        or shared_digests != behavioral_digests
        or pair.get("shared_execution_contract_digest_semantics")
        != "behavioral_authority_excludes_postrun_proof_consumers"
        or len(legacy_full_shared_digests) != 1
        or not looks_like_sha256(legacy_full_shared_digests[0])
        or len(source_digests) != 2
        or len(set(source_digests)) != 2
        or not all(looks_like_sha256(value) for value in source_digests)
    ):
        issues.append("b7_5_extended_history_behavior_digest_set_invalid")
    source_contract_binding = pair.get("source_window_contract_binding")
    source_contract_binding = (
        source_contract_binding
        if isinstance(source_contract_binding, Mapping)
        else {}
    )
    source_contract_artifact = source_contract_binding.get("artifact")
    source_contract_artifact = (
        source_contract_artifact
        if isinstance(source_contract_artifact, Mapping)
        else {}
    )
    source_contract_filename = str(source_contract_artifact.get("path") or "")
    source_contract_path = root / source_contract_filename
    source_contract_payload = (
        read_json(source_contract_path)
        if source_contract_filename
        and Path(source_contract_filename).name == source_contract_filename
        and source_contract_path.is_file()
        else {}
    )
    if (
        source_contract_filename != "B7_5_EXTENDED_HISTORY_SOURCE_WINDOW_CONTRACT.json"
        or source_contract_artifact.get("required") is not True
        or source_contract_artifact.get("present") is not True
        or source_contract_artifact.get("hash_bound") is not True
        or not source_contract_path.is_file()
        or source_contract_artifact.get("sha256")
        != b7_5_artifact_file_sha256(source_contract_path)
        or source_contract_binding.get("valid") is not True
        or source_contract_binding.get("contract_digest_sha256")
        != source_contract_payload.get("contract_digest_sha256")
        or source_contract_binding.get("pair_binding_sha256")
        != source_contract_payload.get("pair_binding_sha256")
        or source_contract_binding.get(
            "shared_execution_contract_digest_sha256"
        )
        != (
            (source_contract_payload.get("shared_execution_contract") or {}).get(
                "shared_execution_contract_digest_sha256"
            )
        )
        or source_contract_binding.get(
            "behavioral_execution_contract_digest_sha256"
        )
        != (
            (
                source_contract_payload.get(
                    "execution_contract_authority_partition"
                )
                or {}
            ).get("behavioral_execution_contract_digest_sha256")
        )
        or source_contract_binding.get(
            "postrun_proof_consumer_contract_digest_sha256"
        )
        != (
            (
                source_contract_payload.get(
                    "execution_contract_authority_partition"
                )
                or {}
            ).get("postrun_proof_consumer_contract_digest_sha256")
        )
        or source_contract_binding.get(
            "execution_contract_authority_partition_valid"
        )
        is not True
        or source_contract_binding.get(
            "behavioral_execution_contract_digest_sha256"
        )
        not in behavioral_digests
        or source_contract_binding.get("source_bound_signal_semantics")
        != source_contract_payload.get("source_bound_signal_semantics")
    ):
        issues.append("b7_5_extended_history_source_contract_binding_invalid")

    economic_pass = pair.get("economic_generalization_pass") is True
    expected_gate = pair.get("truth_integrity_pass") is True and economic_pass
    expected_status = (
        "b7_5_truth_and_economic_generalization_green"
        if expected_gate
        else "b7_5_truth_green_economic_generalization_failed"
    )
    if (
        pair.get("b7_5_gate_pass") is not expected_gate
        or report.get("status") != expected_status
    ):
        issues.append("b7_5_extended_history_behavior_gate_status_invalid")

    paired_windows: list[Mapping[str, Any]] = []
    for window in windows:
        window_id = str(window.get("window_id") or "unknown")
        role = str(window.get("role") or "")
        if role == "paired_extended_history":
            paired_windows.append(window)
        truth = window.get("truth_contract")
        truth = truth if isinstance(truth, Mapping) else {}
        if truth.get("pass") is not True or list(truth.get("issues") or ()):
            issues.append(f"b7_5_window_truth_invalid:{window_id}")
        for field in (
            "completed",
            "all_required_artifacts_present",
            "full_82_sleeve_axis_surface",
            "non_additive_source_signal_truth_valid",
            "behavioral_execution_contract_partition_bound",
            "paired_row_level_artifacts_hash_bound",
            "candidate_transfer_nonzero",
            "scorecard_transfer_nonzero",
            "order_transfer_nonzero",
            "fill_transfer_nonzero",
            "physical_trade_count_reconciled",
            "headline_trade_count_reconciled",
            "broker_live_final_closed",
        ):
            if truth.get(field) is not True:
                issues.append(f"b7_5_window_truth_field_invalid:{window_id}:{field}")
        if (
            int(truth.get("executed_refused_cost_rows") or 0) != 0
            or int(truth.get("executed_source_gap_rows") or 0) != 0
        ):
            issues.append(f"b7_5_window_cost_execution_invalid:{window_id}")

        artifacts = window.get("artifacts")
        artifacts = artifacts if isinstance(artifacts, Mapping) else {}
        expected_artifact_names = {
            "summary",
            "flow_summary",
            "parity_summary",
            "trade_ledger",
            "source_bound_parity_ledger",
            "candidate_instance_projection_ledger",
        }
        if set(artifacts) != expected_artifact_names:
            issues.append(f"b7_5_window_artifact_set_invalid:{window_id}")
        for artifact_name, artifact in artifacts.items():
            artifact = artifact if isinstance(artifact, Mapping) else {}
            filename = str(artifact.get("path") or "")
            path = root / filename
            required = artifact.get("required") is True
            if not filename or Path(filename).name != filename:
                issues.append(
                    f"b7_5_window_artifact_binding_invalid:{window_id}:{artifact_name}"
                )
                continue
            if required and (
                artifact.get("present") is not True
                or artifact.get("hash_bound") is not True
                or not path.is_file()
                or path.stat().st_size <= 0
                or int(artifact.get("byte_count") or 0) != path.stat().st_size
                or str(artifact.get("sha256") or "")
                != b7_5_artifact_file_sha256(path)
            ):
                issues.append(
                    f"b7_5_window_artifact_binding_invalid:{window_id}:{artifact_name}"
                )
            if (
                role == "paired_extended_history"
                and artifact_name
                in {
                    "source_bound_parity_ledger",
                    "candidate_instance_projection_ledger",
                }
                and (
                    required is not True
                    or artifact.get("row_count") is None
                    or int(artifact.get("row_count") or 0) <= 0
                )
            ):
                issues.append(
                    f"b7_5_window_paired_row_artifact_invalid:{window_id}:{artifact_name}"
                )

        counts = window.get("artifact_row_counts")
        counts = counts if isinstance(counts, Mapping) else {}
        if (
            int(counts.get("summary_physical_trade_rows") or 0)
            != int(counts.get("loaded_physical_trade_rows") or 0)
            or int(counts.get("summary_headline_trade_rows") or 0)
            != int(counts.get("loaded_headline_trade_rows") or 0)
            or int(counts.get("trade_ledger_physical_fill_rows") or 0)
            != int(counts.get("loaded_physical_trade_rows") or 0)
            or int(counts.get("candidate_instance_rows") or 0)
            != int(counts.get("summary_candidate_rows") or 0)
        ):
            issues.append(f"b7_5_window_trade_count_binding_invalid:{window_id}")
        if role == "paired_extended_history" and (
            int(counts.get("candidate_instance_projection_ledger_rows") or 0)
            != int(counts.get("candidate_instance_rows") or 0)
            or int(counts.get("source_bound_parity_ledger_rows") or 0)
            != int(counts.get("parity_summary_declared_ledger_rows") or 0)
            or int(counts.get("source_member_axis_rows") or 0) != 1101
        ):
            issues.append(f"b7_5_window_row_unit_binding_invalid:{window_id}")
        if (
            int(counts.get("scorecard_ledger_rows") or 0) <= 0
            or int(counts.get("scorecard_present_candidate_instance_rows") or 0)
            <= 0
            or int(counts.get("scheduler_selected_candidate_instance_rows") or 0)
            < int(counts.get("order_present_candidate_instance_rows") or 0)
            or int(counts.get("order_present_candidate_instance_rows") or 0)
            < int(counts.get("loaded_physical_trade_rows") or 0)
            or int(counts.get("order_event_rows") or 0)
            < int(counts.get("terminal_order_rows") or 0)
            or int(counts.get("terminal_order_rows") or 0)
            < int(counts.get("loaded_physical_trade_rows") or 0)
        ):
            issues.append(f"b7_5_window_named_unit_partition_invalid:{window_id}")

        behavior = window.get("behavior")
        behavior = behavior if isinstance(behavior, Mapping) else {}
        for surface_name in ("physical", "headline", "diagnostic_only"):
            surface = behavior.get(surface_name)
            surface = surface if isinstance(surface, Mapping) else {}
            if int(surface.get("trade_rows") or 0) != sum(
                int(surface.get(key) or 0) for key in ("wins", "losses", "flats")
            ):
                issues.append(
                    f"b7_5_window_behavior_count_invalid:{window_id}:{surface_name}"
                )
        if (
            int(behavior.get("physical", {}).get("trade_rows") or 0)
            != int(counts.get("loaded_physical_trade_rows") or 0)
            or int(behavior.get("headline", {}).get("trade_rows") or 0)
            != int(counts.get("loaded_headline_trade_rows") or 0)
        ):
            issues.append(f"b7_5_window_behavior_ledger_count_invalid:{window_id}")

        transfer = window.get("transfer")
        transfer = transfer if isinstance(transfer, Mapping) else {}
        if (
            int(transfer.get("package_axes") or 0) != 1101
            or int(transfer.get("candidate_generated_axes") or 0) <= 0
            or int(transfer.get("scorecard_or_order_present_axes") or 0) <= 0
            or int(transfer.get("order_present_axes") or 0) <= 0
            or int(transfer.get("filled_trade_axes") or 0) <= 0
        ):
            issues.append(f"b7_5_window_transfer_invalid:{window_id}")
        if role == "paired_extended_history" and (
            transfer.get("source_bound_signal_evidence_class")
            != B7_5_SOURCE_BOUND_SIGNAL_EVIDENCE_CLASS
            or transfer.get("source_bound_r_additive_allowed") is not False
            or transfer.get(
                "executable_r_to_source_bound_r_percentage_allowed"
            )
            is not False
            or transfer.get("physical_r_pct_of_source_bound_signal") is not None
            or transfer.get("physical_r_pct_disposition")
            != B7_5_SOURCE_BOUND_PERCENTAGE_DISPOSITION
            or transfer.get(
                "non_additive_window_source_bound_signal_available"
            )
            is not True
        ):
            issues.append(f"b7_5_window_non_additive_signal_invalid:{window_id}")
        if role != "paired_extended_history" and truth.get(
            "source_bound_signal_semantics_authority"
        ) != "historical_comparator_not_pair_semantics_authority":
            issues.append(
                f"b7_5_window_historical_semantics_boundary_invalid:{window_id}"
            )

        cost = window.get("cost_source_execution")
        cost = cost if isinstance(cost, Mapping) else {}
        physical_rows = int(behavior.get("physical", {}).get("trade_rows") or 0)
        if (
            int(cost.get("executed_refused_cost_rows") or 0) != 0
            or int(cost.get("executed_source_gap_rows") or 0) != 0
            or sum(
                int(value or 0)
                for value in (
                    cost.get("pretrade_cost_packet_status_counts") or {}
                ).values()
            )
            != physical_rows
            or int(
                (cost.get("pretrade_cost_packet_status_counts") or {}).get("PASSED")
                or 0
            )
            != physical_rows
        ):
            issues.append(f"b7_5_window_cost_surface_invalid:{window_id}")

        headline_rows = int(behavior.get("headline", {}).get("trade_rows") or 0)
        stress = window.get("stress")
        stress = stress if isinstance(stress, Mapping) else {}
        monte_carlo = window.get("monte_carlo")
        monte_carlo = monte_carlo if isinstance(monte_carlo, Mapping) else {}
        if (
            not list(stress.get("guarded_stress_rows") or ())
            or int(stress.get("trade_count") or 0) != headline_rows
            or int(monte_carlo.get("trade_count") or 0) != headline_rows
        ):
            issues.append(f"b7_5_window_stress_mc_invalid:{window_id}")

    if len(paired_windows) != 2:
        issues.append("b7_5_extended_history_behavior_paired_rows_invalid")
    else:
        paired_windows = sorted(
            paired_windows, key=lambda row: str(row.get("date_start") or "")
        )
        try:
            paired_dates = [
                (
                    datetime.strptime(str(window.get("date_start")), "%Y-%m-%d").date(),
                    datetime.strptime(str(window.get("date_end")), "%Y-%m-%d").date(),
                )
                for window in paired_windows
            ]
        except (TypeError, ValueError):
            paired_dates = []
        if len(paired_dates) != 2:
            issues.append("b7_5_paired_window_dates_invalid")
        else:
            first_start, first_end = paired_dates[0]
            second_start, second_end = paired_dates[1]
            if (
                first_start > first_end
                or second_start > second_end
                or first_end >= second_start
                or (second_start.year * 12 + second_start.month)
                - (first_start.year * 12 + first_start.month)
                <= 1
            ):
                issues.append("b7_5_paired_window_separation_invalid")

        observed_behavioral_digests = {
            str(
                (window.get("contract_binding") or {}).get(
                    "behavioral_execution_contract_digest_sha256"
                )
                or ""
            )
            for window in paired_windows
        }
        observed_legacy_full_shared_digests = {
            str(
                (window.get("contract_binding") or {}).get(
                    "actual_shared_execution_contract_digest_sha256"
                )
                or ""
            )
            for window in paired_windows
        }
        observed_source_digests = {
            str(
                (window.get("contract_binding") or {}).get(
                    "expected_source_plan_digest_sha256"
                )
                or ""
            )
            for window in paired_windows
        }
        if (
            any(
                (window.get("contract_binding") or {}).get("valid") is not True
                for window in paired_windows
            )
            or observed_behavioral_digests != set(behavioral_digests)
            or observed_legacy_full_shared_digests
            != set(legacy_full_shared_digests)
            or observed_source_digests != set(source_digests)
        ):
            issues.append("b7_5_paired_window_contract_binding_invalid")

        combined_physical = pair.get("combined_physical") or {}
        combined_headline = pair.get("combined_headline") or {}
        for surface_name, combined in (
            ("physical", combined_physical),
            ("headline", combined_headline),
        ):
            for key in ("trade_rows", "wins", "losses", "flats", "net_r", "gross_r", "final_r", "cash_pnl"):
                expected = sum(
                    number(window["behavior"][surface_name].get(key))
                    for window in paired_windows
                )
                if not close(combined.get(key), expected):
                    issues.append(
                        f"b7_5_combined_behavior_invalid:{surface_name}:{key}"
                    )
        observed_negative = sorted(
            window["window_id"]
            for window in paired_windows
            if number(window["behavior"]["headline"].get("net_r")) <= 0
        )
        if sorted(pair.get("negative_headline_windows") or ()) != observed_negative:
            issues.append("b7_5_negative_window_disposition_invalid")
        observed_positive = sorted(
            window["window_id"]
            for window in paired_windows
            if number(window["behavior"]["headline"].get("net_r")) > 0
        )
        if sorted(pair.get("positive_headline_windows") or ()) != observed_positive:
            issues.append("b7_5_positive_window_disposition_invalid")
        observed_stress_positive = all(
            all(
                number(row.get("net_r")) > 0
                for row in window["stress"].get("guarded_stress_rows") or ()
            )
            for window in paired_windows
        )
        observed_economic_pass = (
            len(observed_positive) == len(paired_windows)
            and observed_stress_positive
        )
        if (
            pair.get("stress_positive_in_every_window")
            is not observed_stress_positive
            or pair.get("economic_generalization_pass")
            is not observed_economic_pass
        ):
            issues.append("b7_5_economic_gate_reconciliation_invalid")

        transfer_totals = pair.get("transfer_totals") or {}
        for key in (
            "package_axes",
            "candidate_generated_axes",
            "scorecard_or_order_present_axes",
            "order_present_axes",
            "filled_trade_axes",
            "actual_physical_executable_r",
            "actual_headline_executable_r",
        ):
            expected = sum(
                number(window["transfer"].get(key))
                for window in paired_windows
            )
            if not close(transfer_totals.get(key), expected):
                issues.append(f"b7_5_transfer_total_invalid:{key}")
        non_additive_by_window = pair.get(
            "non_additive_source_signal_by_window"
        ) or {}
        if set(non_additive_by_window) != {
            str(window.get("window_id") or "") for window in paired_windows
        } or any(
            not close(
                non_additive_by_window.get(window["window_id"]),
                window["transfer"].get(
                    "non_additive_window_source_bound_signal_r"
                ),
            )
            for window in paired_windows
        ):
            issues.append("b7_5_non_additive_signal_window_binding_invalid")
    return sorted(set(issues))


def broad_summary_full_verifier_schema_issues(
    summary: Mapping[str, Any],
) -> list[str]:
    schema = summary.get("schema")
    if schema == BROAD_REPLAY_IMMUTABLE_AUTHORITY_SUMMARY_SCHEMA:
        return []
    if schema == BROAD_REPLAY_HISTORICAL_SUMMARY_SCHEMA:
        return ["package_parity_repair_summary_v1_historical_only"]
    return ["package_parity_repair_summary_schema_mismatch"]


def broad_summary_verifier_mode(summary: Mapping[str, Any]) -> str:
    schema = summary.get("schema")
    if schema == BROAD_REPLAY_IMMUTABLE_AUTHORITY_SUMMARY_SCHEMA:
        return "current_summary_v2_full_verifier"
    if schema == BROAD_REPLAY_HISTORICAL_SUMMARY_SCHEMA:
        return "historical_summary_v1_diagnostic_only"
    return "unsupported_summary_schema"


def package_new_entry_authority_contract_field_missing(
    field: str,
    value: Any,
) -> bool:
    if field in PACKAGE_NEW_ENTRY_AUTHORITY_CLEAN_SEQUENCE_FIELDS:
        return value in (None, "", {})
    return quality_field_missing(value)


def package_new_entry_authority_claim_present(surface: Mapping[str, Any]) -> bool:
    return any(
        surface.get(field) not in (None, "", [], {})
        for field in (
            "package_new_entry_authority_payload",
            "package_new_entry_authority_payload_contract",
            "package_new_entry_authority_hash_sha256",
            "expected_package_new_entry_authority_hash_sha256",
            "package_new_entry_authority_status",
        )
    ) or surface.get("package_new_entry_authority_valid") is not None or any(
        str(field).startswith("package_new_entry_authority_")
        for field in surface
    ) or any(
        field in surface
        for field in ("allowed", "applies", "authority_family", "authority_source")
    )


def package_new_entry_authority_surfaces(
    row: Mapping[str, Any],
) -> list[tuple[str, Mapping[str, Any]]]:
    surfaces: list[tuple[str, Mapping[str, Any]]] = []
    for field in PACKAGE_NEW_ENTRY_AUTHORITY_SURFACE_FIELDS:
        surface = parse_mapping(row.get(field))
        if surface and package_new_entry_authority_claim_present(surface):
            surfaces.append((field, surface))
    if package_new_entry_authority_claim_present(row):
        surfaces.append(("root", row))
    return surfaces


def package_new_entry_authority_flat_namespace_surfaces(
    row: Mapping[str, Any],
) -> list[tuple[str, str, Mapping[str, Any]]]:
    """Reconstruct independently signed proposals flattened into ledger columns.

    A scorecard can retain several valid pre-finalizer proposals for different
    candidates. They are proof surfaces, not competing current execution
    envelopes, so each namespace is reconstructed and validated independently.
    """

    terminal_zero_trade_non_executable = bool(
        canonical_scheduler_action_intent(row.get("selected_action_class"))
        == "zero_trade"
        and not any(
            value_bool_true(row.get(field))
            for field in (
                "ledger_namespace_synthesized_executable_candidate_use_allowed",
                "package_replay_candidate_use_allowed",
                "package_replay_executable_candidate_use_allowed",
                "package_replay_order_executable_candidate_use_allowed",
                "replay_candidate_use_allowed_now",
                "ultimate_package_effective_executable_authority_allowed",
                "executable_finalized",
                "risk_finalizer_executable_finalized",
                "missed_row_executable_finalized",
            )
        )
        and not any(
            numeric_or_none(row.get(field)) not in (None, 0.0)
            for field in (
                "approved_risk_pct",
                "scheduler_approved_risk_pct",
                "selected_scheduler_approved_risk_pct",
                "risk_decision_approved_risk_pct",
            )
        )
        and row.get("simulated_order_id") in (None, "")
        and row.get("simulated_trade_id") in (None, "")
    )
    surfaces: list[tuple[str, str, Mapping[str, Any]]] = []
    claimed_fields = (
        "package_new_entry_authority_",
        "expected_package_new_entry_authority_hash_sha256",
    )
    for prefix in PACKAGE_NEW_ENTRY_AUTHORITY_FLAT_NAMESPACE_PREFIXES:
        surface: dict[str, Any] = {}
        for field, value in row.items():
            field_name = str(field)
            if not field_name.startswith(prefix):
                continue
            unprefixed = field_name[len(prefix) :]
            if not (
                unprefixed.startswith(claimed_fields[0])
                or unprefixed == claimed_fields[1]
            ):
                continue
            surface[unprefixed] = value
        if not surface or not any(
            value not in (None, "", [], {}) for value in surface.values()
        ):
            continue
        payload = parse_mapping(surface.get("package_new_entry_authority_payload"))
        demoted_nonrequired_claim_fields: list[str] = []
        if (
            terminal_zero_trade_non_executable
            and surface.get("package_new_entry_authority_required") is False
            and not payload
        ):
            for field in PACKAGE_NEW_ENTRY_AUTHORITY_IMMUTABLE_CLAIM_FIELDS:
                if surface.get(field) in (None, "", [], {}):
                    continue
                surface[field] = None
                demoted_nonrequired_claim_fields.append(field)
            if demoted_nonrequired_claim_fields:
                surface["package_new_entry_authority_valid"] = False
                surface["package_new_entry_authority_status"] = (
                    "not_required_for_selector_action_or_action_intent"
                )
                surface["package_new_entry_authority_failures"] = []
                surface["_terminal_nonrequired_hash_only_claim_demotions"] = tuple(
                    demoted_nonrequired_claim_fields
                )
        authority_hash = str(
            surface.get("package_new_entry_authority_hash_sha256") or ""
        ).strip()
        expected_hash = str(
            surface.get("expected_package_new_entry_authority_hash_sha256") or ""
        ).strip()
        repaired_projections: list[str] = []
        repaired_empty_projections: list[str] = []
        repaired_projection_drifts: list[str] = []
        if (
            payload
            and looks_like_sha256(authority_hash)
            and authority_hash == expected_hash
            and authority_hash
            == package_new_entry_authority_payload_hash_sha256(payload)
        ):
            for payload_field, payload_value in payload.items():
                projection_field = (
                    "package_new_entry_authority_payload_schema"
                    if payload_field == "payload_schema"
                    else "package_new_entry_authority_payload_contract"
                    if payload_field == "payload_contract"
                    else f"package_new_entry_authority_{payload_field}"
                )
                projected_value = surface.get(projection_field)
                payload_canonical = json.dumps(
                    payload_value,
                    sort_keys=True,
                    separators=(",", ":"),
                    default=str,
                )
                projected_canonical = json.dumps(
                    projected_value,
                    sort_keys=True,
                    separators=(",", ":"),
                    default=str,
                )
                if (
                    projection_field in surface
                    and projected_value is not None
                    and projected_canonical == payload_canonical
                ):
                    continue
                surface[projection_field] = (
                    dict(payload_value)
                    if isinstance(payload_value, Mapping)
                    else list(payload_value)
                    if isinstance(payload_value, list)
                    else payload_value
                )
                repaired_projections.append(projection_field)
                if payload_value in ("", [], {}):
                    repaired_empty_projections.append(projection_field)
                if projection_field in surface and projected_value is not None:
                    repaired_projection_drifts.append(projection_field)
        if repaired_projections:
            surface["_hash_bound_projection_repairs"] = tuple(
                repaired_projections
            )
        if repaired_empty_projections:
            surface["_hash_bound_empty_projection_repairs"] = tuple(
                repaired_empty_projections
            )
        if repaired_projection_drifts:
            surface["_hash_bound_projection_drift_repairs"] = tuple(
                repaired_projection_drifts
            )
        if terminal_zero_trade_non_executable:
            surface["_terminal_zero_trade_non_executable"] = True
        if package_new_entry_authority_claim_present(surface):
            surfaces.append(
                (
                    f"flat_namespace:{prefix.rstrip('_')}",
                    prefix,
                    surface,
                )
            )
    return surfaces


def package_new_entry_authority_flat_namespace_identity_row(
    row: Mapping[str, Any],
    surface: Mapping[str, Any],
) -> dict[str, Any]:
    """Bind a flattened proposal to its own immutable candidate identity."""

    identity_row = dict(row)
    for field in (
        "candidate_id",
        "canonical_replay_candidate_instance_key",
        "source_bound_replay_candidate_instance_key",
        "candidate_instance_identity_status",
    ):
        value = surface.get(f"package_new_entry_authority_{field}")
        if value not in (None, "", [], {}):
            identity_row[field] = value
    if identity_row.get("decision_time_utc") in (None, "", [], {}):
        decision_time = surface.get(
            "package_new_entry_authority_decision_time_utc"
        )
        if decision_time not in (None, "", [], {}):
            identity_row["decision_time_utc"] = decision_time
    return identity_row


def package_new_entry_authority_proof_surfaces(
    row: Mapping[str, Any],
) -> list[tuple[str, Mapping[str, Any]]]:
    """Return exact current authority surfaces without cross-surface merging."""

    surfaces: list[tuple[str, Mapping[str, Any]]] = []
    pending: list[tuple[str, Mapping[str, Any]]] = [("root", row)]
    seen: set[int] = set()
    while pending:
        path, container = pending.pop(0)
        identity = id(container)
        if identity in seen:
            continue
        seen.add(identity)
        if package_new_entry_authority_claim_present(container):
            surfaces.append((path, container))
        for field in PACKAGE_NEW_ENTRY_AUTHORITY_SURFACE_FIELDS:
            nested = parse_mapping(container.get(field))
            if nested and package_new_entry_authority_claim_present(nested):
                surfaces.append((f"{path}.{field}", nested))
        for field in PACKAGE_NEW_ENTRY_AUTHORITY_DECISION_CONTAINER_FIELDS:
            nested = parse_mapping(container.get(field))
            if nested:
                pending.append((f"{path}.{field}", nested))
    for path, _prefix, surface in package_new_entry_authority_flat_namespace_surfaces(
        row
    ):
        surfaces.append((path, surface))
    return surfaces


def nonrequired_package_new_entry_authority_immutable_claim_reasons(
    row: Mapping[str, Any],
) -> list[str]:
    """Reject immutable claims emitted by a surface that declares no authority."""

    reasons: list[str] = []
    for path, surface in package_new_entry_authority_proof_surfaces(row):
        required_is_false = (
            "package_new_entry_authority_required" in surface
            and surface.get("package_new_entry_authority_required") is False
        )
        status = str(
            surface.get("package_new_entry_authority_status") or ""
        ).strip()
        if not (
            required_is_false
            or status in PACKAGE_NEW_ENTRY_AUTHORITY_NOT_REQUIRED_STATUSES
        ):
            continue
        if surface.get("package_new_entry_authority_projection_failures") not in (
            None,
            "",
            [],
            {},
        ):
            reasons.append(
                "nonrequired_package_new_entry_authority_projection_failure:"
                f"{path}:package_new_entry_authority_projection_failures"
            )
        for field in PACKAGE_NEW_ENTRY_AUTHORITY_IMMUTABLE_CLAIM_FIELDS:
            if surface.get(field) in (None, "", [], {}):
                continue
            reasons.append(
                "nonrequired_package_new_entry_authority_immutable_claim:"
                f"{path}:{field}"
            )
    return list(dict.fromkeys(reasons))


def package_new_entry_authority_immutable_payload_required(
    row: Mapping[str, Any],
    *,
    require_immutable_payload: bool = False,
) -> bool:
    return bool(
        require_immutable_payload
        or row.get("package_new_entry_authority_payload_contract")
        == PACKAGE_NEW_ENTRY_AUTHORITY_IMMUTABLE_PAYLOAD_CONTRACT
        or package_new_entry_authority_surfaces(row)
        or any(
            value_bool_true(row.get(field))
            for field in (
                "package_replay_candidate_use_allowed",
                "package_replay_executable_candidate_use_allowed",
                "package_replay_order_executable_candidate_use_allowed",
                "replay_candidate_use_allowed_now",
                "ultimate_package_effective_executable_authority_allowed",
            )
        )
    )


def package_new_entry_authority_payload_contract_reasons(
    row: Mapping[str, Any],
    *,
    action_intent: str,
    require_immutable_payload: bool = False,
    identity_row: Mapping[str, Any] | None = None,
) -> list[str]:
    """Verify the immutable signed envelope without trusting flattened aliases.

    Historical replay rows produced before this contract may omit the payload.
    New broad summaries opt in explicitly, and any row that carries a payload is
    checked even when the surrounding artifact is historical.
    """

    required = package_new_entry_authority_immutable_payload_required(
        row,
        require_immutable_payload=require_immutable_payload,
    )
    payload = parse_mapping(row.get("package_new_entry_authority_payload"))
    if not payload:
        return ["package_new_entry_authority_payload_missing"] if required else []

    reasons: list[str] = []
    if (
        row.get("package_new_entry_authority_payload_contract")
        != PACKAGE_NEW_ENTRY_AUTHORITY_IMMUTABLE_PAYLOAD_CONTRACT
    ):
        reasons.append("package_new_entry_authority_payload_contract_invalid")
    if (
        payload.get("payload_contract")
        != PACKAGE_NEW_ENTRY_AUTHORITY_IMMUTABLE_PAYLOAD_CONTRACT
    ):
        reasons.append("package_new_entry_authority_payload_contract_unbound")
    if payload.get("payload_schema") != PACKAGE_NEW_ENTRY_AUTHORITY_PAYLOAD_SCHEMA:
        reasons.append("package_new_entry_authority_payload_schema_invalid")
    reasons.extend(package_new_entry_authority_payload_atom_reasons(payload))

    authority_hash = row.get("package_new_entry_authority_hash_sha256")
    expected_hash = row.get("expected_package_new_entry_authority_hash_sha256")
    computed_hash = package_new_entry_authority_payload_hash_sha256(payload)
    if not looks_like_sha256(authority_hash):
        reasons.append("package_new_entry_authority_hash_invalid")
    elif str(authority_hash).strip() != computed_hash:
        reasons.append("package_new_entry_authority_payload_hash_mismatch")
    if not looks_like_sha256(expected_hash):
        reasons.append("expected_package_new_entry_authority_hash_invalid")
    elif str(expected_hash).strip() != computed_hash:
        reasons.append("expected_package_new_entry_authority_payload_hash_mismatch")

    normalized_action = canonical_scheduler_action_intent(action_intent)
    payload_action = canonical_scheduler_action_intent(
        payload.get("target_action_intent")
    )
    if not payload_action or payload_action != normalized_action:
        reasons.append("package_new_entry_authority_payload_action_intent_mismatch")
    expected_scope = package_new_entry_authority_scope_for_action_intent(
        normalized_action
    )
    if payload.get("scope") != expected_scope:
        reasons.append("package_new_entry_authority_payload_scope_invalid")
    if row.get("package_new_entry_authority_scope") != payload.get("scope"):
        reasons.append("package_new_entry_authority_payload_scope_projection_mismatch")
    if canonical_scheduler_action_intent(
        row.get("package_new_entry_authority_target_action_intent")
    ) != payload_action:
        reasons.append(
            "package_new_entry_authority_payload_action_projection_mismatch"
        )

    if payload.get("uses_outcome_fields") is not False:
        reasons.append("package_new_entry_authority_payload_uses_outcome_fields")
    if not value_bool_true(payload.get("authority_applies")):
        reasons.append("package_new_entry_authority_payload_authority_not_applied")
    if not value_bool_true(payload.get("authority_allowed")):
        reasons.append("package_new_entry_authority_payload_authority_not_allowed")
    boundary_reason = predecision_boundary_bad_reason(
        payload.get("source_boundary"),
        field="package_new_entry_authority_payload.source_boundary",
    )
    if boundary_reason:
        reasons.append(boundary_reason)
    if (
        row.get("package_new_entry_authority_source_boundary")
        != payload.get("source_boundary")
    ):
        reasons.append(
            "package_new_entry_authority_payload_source_boundary_projection_mismatch"
        )

    payload_selector_action = canonical_selector_action(
        payload.get("selector_action")
    )
    projected_selector_action = canonical_selector_action(
        row.get("package_new_entry_authority_selector_action")
    )
    if not payload_selector_action or payload_selector_action != projected_selector_action:
        reasons.append(
            "package_new_entry_authority_payload_selector_action_projection_mismatch"
        )

    for field in (
        "authority_applies",
        "authority_allowed",
        "source_bound_package_candidate_use_allowed",
    ):
        if payload.get(field) is not True:
            reasons.append(f"package_new_entry_authority_payload_{field}_not_true")
    quality_sources = payload.get("candidate_decision_quality_field_sources")
    quality_sources = quality_sources if isinstance(quality_sources, Mapping) else {}
    for field in PACKAGE_NEW_ENTRY_AUTHORITY_QUALITY_FIELDS:
        if quality_field_missing(quality_sources.get(field)):
            reasons.append(
                f"package_new_entry_authority_payload_quality_source_missing:{field}"
            )
    if payload.get("candidate_decision_quality_alias_status") != "exact_materialized":
        reasons.append("package_new_entry_authority_payload_quality_alias_not_exact")
    if sequence_values(payload.get("candidate_decision_quality_alias_mismatches")):
        reasons.append(
            "package_new_entry_authority_payload_quality_alias_mismatches_present"
        )
    if sequence_values(payload.get("candidate_decision_quality_provenance_failures")):
        reasons.append(
            "package_new_entry_authority_payload_quality_provenance_failures_present"
        )
    if str(payload.get("pretrade_cost_packet_status") or "").upper() != "PASSED":
        reasons.append("package_new_entry_authority_payload_cost_status_not_passed")
    if payload.get("cost_source_gap_status") != "source_bound_cost_authority_present":
        reasons.append("package_new_entry_authority_payload_cost_source_gap")
    if payload.get("cost_authority") != "broker_calibrated_replay_cost":
        reasons.append("package_new_entry_authority_payload_cost_authority_invalid")
    if payload.get("candidate_cost_r_fallback_is_authority") is not False:
        reasons.append(
            "package_new_entry_authority_payload_cost_fallback_is_authority"
        )
    payload_fill_authority_class = str(
        payload.get("execution_fill_probability_authority_class") or ""
    ).strip()
    if not str(payload.get("execution_fill_probability_source") or "").strip():
        reasons.append("package_new_entry_authority_payload_fill_source_missing")
    elif payload_fill_authority_class != (
        PACKAGE_NEW_ENTRY_AUTHORITY_EXECUTION_FILLABILITY_CLASS
    ):
        reasons.append(
            "package_new_entry_authority_payload_fill_authority_class_invalid"
        )
    elif not execution_fillability_source_is_authoritative(
        payload.get("execution_fill_probability_source"),
        payload_fill_authority_class,
    ):
        reasons.append("package_new_entry_authority_payload_fill_source_unsafe")
    if row.get(
        "package_new_entry_authority_execution_fill_probability_authority_class"
    ) != payload.get("execution_fill_probability_authority_class"):
        reasons.append(
            "package_new_entry_authority_payload_fill_authority_class_"
            "projection_mismatch"
        )
    fill_source_boundary = payload.get("execution_fill_probability_source_boundary")
    if fill_source_boundary in (None, "", [], {}):
        reasons.append(
            "package_new_entry_authority_payload."
            "execution_fill_probability_source_boundary_missing"
        )
    elif not predecision_execution_fillability_source_boundary_allowed(
        fill_source_boundary
    ):
        reasons.append(
            "package_new_entry_authority_payload."
            "execution_fill_probability_source_boundary_unsafe"
        )
    fill_source_time = _parse_utc(
        payload.get("execution_fill_probability_source_time_utc")
    )
    fill_decision_time = _parse_utc(payload.get("decision_time_utc"))
    if fill_source_time is None:
        reasons.append(
            "package_new_entry_authority_payload_fill_source_time_invalid"
        )
    if fill_decision_time is None:
        reasons.append(
            "package_new_entry_authority_payload_fill_decision_time_invalid"
        )
    if (
        fill_source_time is not None
        and fill_decision_time is not None
        and fill_source_time >= fill_decision_time
    ):
        reasons.append(
            "package_new_entry_authority_payload_fill_source_time_not_before_decision"
        )
    policy_required = payload.get(
        "selected_policy_expected_net_calibration_required"
    )
    if policy_required is True:
        if payload.get("selected_policy_expected_net_calibrated") is not True:
            reasons.append(
                "package_new_entry_authority_payload_policy_calibration_not_true"
            )
        for field in (
            "selected_policy_expected_net_calibration_status",
            "selected_policy_expected_net_calibration_source",
            "selected_policy_expected_net_calibration_source_boundary",
            "selected_policy_expected_net_calibration_hash",
        ):
            if quality_field_missing(payload.get(field)):
                reasons.append(
                    f"package_new_entry_authority_payload_policy_atom_invalid:{field}"
                )
    if not isinstance(
        payload.get("package_replay_order_executable_candidate_use_allowed"),
        bool,
    ):
        reasons.append("package_new_entry_authority_payload_order_permission_invalid")
    for field in (
        "package_replay_order_executable_candidate_use_allowed_reason",
        "package_replay_order_executable_authority_source",
    ):
        if quality_field_missing(payload.get(field)):
            reasons.append(
                f"package_new_entry_authority_payload_order_atom_invalid:{field}"
            )

    identity_fields = (
        ("candidate_id", "package_new_entry_authority_candidate_id"),
        ("decision_time_utc", "package_new_entry_authority_decision_time_utc"),
        (
            "canonical_replay_candidate_instance_key",
            "package_new_entry_authority_canonical_replay_candidate_instance_key",
        ),
        (
            "source_bound_replay_candidate_instance_key",
            "package_new_entry_authority_source_bound_replay_candidate_instance_key",
        ),
        (
            "candidate_instance_identity_status",
            "package_new_entry_authority_candidate_instance_identity_status",
        ),
    )
    for payload_field, projected_field in identity_fields:
        payload_value = payload.get(payload_field)
        projected_value = row.get(projected_field)
        if quality_field_missing(payload_value):
            reasons.append(
                f"package_new_entry_authority_payload_{payload_field}_missing"
            )
            continue
        if str(payload_value) != str(projected_value or ""):
            reasons.append(
                f"package_new_entry_authority_payload_{payload_field}_projection_mismatch"
            )

    current_identity_fields = (
        "candidate_id",
        "decision_time_utc",
        "canonical_replay_candidate_instance_key",
        "source_bound_replay_candidate_instance_key",
    )
    current_identity_row = identity_row or row
    for current_field in current_identity_fields:
        payload_value = payload.get(current_field)
        current_values = signed_authority_current_identity_values(
            current_identity_row,
            current_field,
        )
        if not current_values:
            reasons.append(
                f"package_new_entry_authority_payload_current_{current_field}_missing"
            )
        elif str(payload_value) not in current_values:
            reasons.append(
                f"package_new_entry_authority_payload_{current_field}_mismatch"
            )

    projection_fields = (
        ("selector_reason", "package_new_entry_authority_selector_reason"),
        ("authority_family", "package_new_entry_authority_authority_family"),
        ("expected_net_r", "package_new_entry_authority_expected_net_r"),
        ("probability", "package_new_entry_authority_probability"),
        ("confidence", "package_new_entry_authority_confidence"),
        ("fill_probability", "package_new_entry_authority_fill_probability"),
        ("source_completeness", "package_new_entry_authority_source_completeness"),
        (
            "entry_quality_fill_probability",
            "package_new_entry_authority_entry_quality_fill_probability",
        ),
        (
            "limit_fillability_probability",
            "package_new_entry_authority_limit_fillability_probability",
        ),
        (
            "predecision_limit_fillability_probability",
            "package_new_entry_authority_predecision_limit_fillability_probability",
        ),
        (
            "execution_fill_probability",
            "package_new_entry_authority_execution_fill_probability",
        ),
        (
            "execution_fill_probability_source",
            "package_new_entry_authority_execution_fill_probability_source",
        ),
        (
            "execution_fill_probability_source_time_utc",
            "package_new_entry_authority_execution_fill_probability_source_time_utc",
        ),
        (
            "execution_fill_probability_source_boundary",
            "package_new_entry_authority_execution_fill_probability_source_boundary",
        ),
        (
            "pretrade_cost_packet_status",
            "package_new_entry_authority_pretrade_cost_packet_status",
        ),
        ("cost_source_gap_status", "package_new_entry_authority_cost_source_gap_status"),
        ("cost_authority", "package_new_entry_authority_cost_authority"),
        (
            "candidate_cost_r_fallback_is_authority",
            "package_new_entry_authority_candidate_cost_r_fallback_is_authority",
        ),
        (
            "source_completeness_status",
            "package_new_entry_authority_source_completeness_status",
        ),
        (
            "source_bound_package_candidate_use_allowed",
            "package_new_entry_authority_source_bound_package_candidate_use_allowed",
        ),
        (
            "source_bound_router_refusal_materialization_floors",
            "package_new_entry_authority_source_bound_router_refusal_materialization_floors",
        ),
        (
            "matched_member_axis_ids",
            "package_new_entry_authority_matched_member_axis_ids",
        ),
        (
            "candidate_decision_quality_field_sources",
            "package_new_entry_authority_candidate_decision_quality_field_sources",
        ),
        (
            "candidate_decision_quality_source_boundary",
            "package_new_entry_authority_candidate_decision_quality_source_boundary",
        ),
        (
            "candidate_decision_quality_alias_status",
            "package_new_entry_authority_candidate_decision_quality_alias_status",
        ),
        (
            "candidate_decision_quality_alias_mismatches",
            "package_new_entry_authority_candidate_decision_quality_alias_mismatches",
        ),
        (
            "candidate_decision_quality_provenance_failures",
            "package_new_entry_authority_candidate_decision_quality_provenance_failures",
        ),
        (
            "selected_policy_for_expected_net_r",
            "package_new_entry_authority_selected_policy_for_expected_net_r",
        ),
        (
            "selected_policy_expected_net_calibration_status",
            "package_new_entry_authority_selected_policy_expected_net_calibration_status",
        ),
        (
            "selected_policy_expected_net_calibrated",
            "package_new_entry_authority_selected_policy_expected_net_calibrated",
        ),
        (
            "selected_policy_expected_net_calibration_required",
            "package_new_entry_authority_selected_policy_expected_net_calibration_required",
        ),
        (
            "selected_policy_expected_net_calibration_source",
            "package_new_entry_authority_selected_policy_expected_net_calibration_source",
        ),
        (
            "selected_policy_expected_net_calibration_source_boundary",
            "package_new_entry_authority_selected_policy_expected_net_calibration_source_boundary",
        ),
        (
            "selected_policy_expected_net_calibration_hash",
            "package_new_entry_authority_selected_policy_expected_net_calibration_hash",
        ),
        (
            "package_replay_order_executable_candidate_use_allowed",
            "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed",
        ),
        (
            "package_replay_order_executable_candidate_use_allowed_reason",
            "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed_reason",
        ),
        (
            "package_replay_order_executable_authority_source",
            "package_new_entry_authority_package_replay_order_executable_authority_source",
        ),
    )
    for payload_field, projected_field in projection_fields:
        payload_value = payload.get(payload_field)
        projected_value = row.get(projected_field)
        if payload_value is None and projected_value is None:
            continue
        payload_canonical = json.dumps(
            payload_value,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        )
        projected_canonical = json.dumps(
            projected_value,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        )
        if payload_canonical != projected_canonical:
            reasons.append(
                "package_new_entry_authority_payload_"
                f"{payload_field}_projection_mismatch"
            )

    payload_member_axis_ids = canonical_payload_member_axis_ids(
        payload.get("matched_member_axis_ids")
    )
    if not payload_member_axis_ids:
        reasons.append(
            "package_new_entry_authority_payload_"
            "matched_member_axis_ids_not_canonical_nonempty"
        )

    return list(dict.fromkeys(reasons))


def package_new_entry_authority_surface_contract_reasons(
    surface: Mapping[str, Any],
    *,
    identity_row: Mapping[str, Any],
    action_intent: str,
) -> list[str]:
    reasons: list[str] = []
    if surface.get("package_new_entry_authority_required") is not True:
        reasons.append("package_new_entry_authority_required_missing_or_false")
    if surface.get("package_new_entry_authority_valid") is not True:
        status = str(surface.get("package_new_entry_authority_status") or "missing")
        reasons.append(f"package_new_entry_authority_invalid:{status}")
    if surface.get("package_new_entry_authority_status") != (
        "valid_signed_predecision_new_entry_authority"
    ):
        reasons.append("package_new_entry_authority_status_not_valid")
    failures = sequence_values(surface.get("package_new_entry_authority_failures"))
    reasons.extend(
        f"package_new_entry_authority_failure:{failure}"
        for failure in failures
        if str(failure or "").strip()
    )
    reasons.extend(
        package_new_entry_authority_payload_contract_reasons(
            surface,
            action_intent=action_intent,
            require_immutable_payload=True,
            identity_row=identity_row,
        )
    )
    return list(dict.fromkeys(reasons))


def package_new_entry_authority_flat_namespace_contract_records(
    row: Mapping[str, Any],
) -> list[dict[str, Any]]:
    """Validate flattened proposal namespaces without conflating candidates."""

    records: list[dict[str, Any]] = []
    for path, prefix, surface in package_new_entry_authority_flat_namespace_surfaces(
        row
    ):
        action_intent = canonical_scheduler_action_intent(
            surface.get("package_new_entry_authority_target_action_intent")
            or "new_position"
        )
        identity_row = package_new_entry_authority_flat_namespace_identity_row(
            row,
            surface,
        )
        full_authority_reasons = package_new_entry_authority_surface_contract_reasons(
            surface,
            identity_row=identity_row,
            action_intent=action_intent,
        )
        immutable_claim = any(
            surface.get(field) not in (None, "", [], {})
            for field in PACKAGE_NEW_ENTRY_AUTHORITY_IMMUTABLE_CLAIM_FIELDS
        )
        claim_bearing = bool(
            surface.get("package_new_entry_authority_valid") is True
        )
        integrity_bearing = bool(immutable_claim and not claim_bearing)
        if claim_bearing:
            reasons = full_authority_reasons
        elif integrity_bearing:
            reasons = package_new_entry_authority_payload_contract_reasons(
                surface,
                action_intent=action_intent,
                require_immutable_payload=True,
                identity_row=identity_row,
            )
            if surface.get("package_new_entry_authority_required") is not True:
                reasons.append(
                    "immutable_diagnostic_authority_payload_without_required_true"
                )
            if surface.get("package_new_entry_authority_status") == (
                "valid_signed_predecision_new_entry_authority"
            ):
                reasons.append(
                    "invalid_authority_payload_status_claims_valid_authority"
                )
            if not sequence_values(
                surface.get("package_new_entry_authority_failures")
            ):
                reasons.append(
                    "invalid_authority_payload_missing_explicit_failure_reasons"
                )
            reasons = list(dict.fromkeys(reasons))
        else:
            reasons = full_authority_reasons
        records.append(
            {
                "source": path,
                "prefix": prefix,
                "surface": surface,
                "identity_row": identity_row,
                "action_intent": action_intent,
                "claim_bearing": claim_bearing,
                "integrity_bearing": integrity_bearing,
                "authority_declared_valid": (
                    surface.get("package_new_entry_authority_valid") is True
                ),
                "hash_bound_empty_projection_repairs": list(
                    surface.get("_hash_bound_empty_projection_repairs") or []
                ),
                "hash_bound_projection_repairs": list(
                    surface.get("_hash_bound_projection_repairs") or []
                ),
                "hash_bound_projection_drift_repairs": list(
                    surface.get("_hash_bound_projection_drift_repairs") or []
                ),
                "terminal_nonrequired_hash_only_claim_demotions": list(
                    surface.get(
                        "_terminal_nonrequired_hash_only_claim_demotions"
                    )
                    or []
                ),
                "historical_cross_stitched_reported_authority_demoted": False,
                "candidate_instance": (
                    str(
                        surface.get(
                            "package_new_entry_authority_canonical_replay_candidate_instance_key"
                        )
                        or surface.get(
                            "package_new_entry_authority_source_bound_replay_candidate_instance_key"
                        )
                        or ""
                    )
                ),
                "digest": (
                    package_new_entry_authority_payload_hash_sha256(
                        parse_mapping(
                            surface.get("package_new_entry_authority_payload")
                        )
                    )
                    if parse_mapping(
                        surface.get("package_new_entry_authority_payload")
                    )
                    else ""
                ),
                "valid": not reasons,
                "reasons": reasons,
            }
        )
    valid_siblings_by_instance: dict[str, list[dict[str, Any]]] = {}
    for record in records:
        instance = str(record.get("candidate_instance") or "")
        if instance and record.get("claim_bearing") and record.get("valid"):
            valid_siblings_by_instance.setdefault(instance, []).append(record)
    for record in records:
        if (
            record.get("valid")
            or not record.get("claim_bearing")
            or record.get("source") != "flat_namespace:scorecard_reported"
            or not record.get("surface", {}).get(
                "_terminal_zero_trade_non_executable"
            )
        ):
            continue
        instance = str(record.get("candidate_instance") or "")
        siblings = valid_siblings_by_instance.get(instance, [])
        declared_hashes = {
            str(record.get("surface", {}).get(field) or "").strip()
            for field in (
                "package_new_entry_authority_hash_sha256",
                "expected_package_new_entry_authority_hash_sha256",
            )
            if looks_like_sha256(record.get("surface", {}).get(field))
        }
        matching_sibling = next(
            (
                sibling
                for sibling in siblings
                if str(sibling.get("digest") or "") in declared_hashes
            ),
            None,
        )
        if matching_sibling is None:
            continue
        record["claim_bearing"] = False
        record["integrity_bearing"] = False
        record["historical_cross_stitched_reported_authority_demoted"] = True
        record["historical_cross_stitched_authority_owner_source"] = (
            matching_sibling.get("source")
        )
    records_by_instance: dict[str, list[dict[str, Any]]] = {}
    for record in records:
        instance = str(record.get("candidate_instance") or "")
        if instance and record.get("claim_bearing") and record.get("valid"):
            records_by_instance.setdefault(instance, []).append(record)
    for instance, instance_records in records_by_instance.items():
        digests = {
            str(record.get("digest") or "")
            for record in instance_records
            if record.get("digest")
        }
        if len(digests) <= 1:
            continue
        reason = (
            "conflicting_flat_namespace_authority_envelopes_same_candidate_instance:"
            f"{instance}"
        )
        for record in instance_records:
            record["valid"] = False
            record["reasons"] = list(
                dict.fromkeys([*(record.get("reasons") or []), reason])
            )
    return records


def package_new_entry_authority_envelope_selection(
    row: Mapping[str, Any],
    *,
    action_intent: str,
) -> dict[str, Any]:
    records: list[dict[str, Any]] = []
    for source, surface in package_new_entry_authority_surfaces(row):
        payload = parse_mapping(surface.get("package_new_entry_authority_payload"))
        reasons = package_new_entry_authority_surface_contract_reasons(
            surface,
            identity_row=row,
            action_intent=action_intent,
        )
        records.append(
            {
                "source": source,
                "surface": surface,
                "payload": payload,
                "digest": (
                    package_new_entry_authority_payload_hash_sha256(payload)
                    if payload
                    else ""
                ),
                "valid": not reasons,
                "reasons": reasons,
            }
        )
    explicit_designations: list[str] = []
    for field in PACKAGE_NEW_ENTRY_AUTHORITY_DESIGNATION_FIELDS:
        designation = str(row.get(field) or "").strip()
        if (
            designation
            and designation in row
            and designation not in explicit_designations
        ):
            explicit_designations.append(designation)
    if len(explicit_designations) > 1:
        return {
            "valid": False,
            "status": "conflicting_explicit_authority_envelope_designations",
            "reasons": ["multiple_explicit_nested_authority_envelope_designations"],
            "records": records,
            "designated_sources": explicit_designations,
        }
    designated_source = explicit_designations[0] if explicit_designations else ""
    designated_record = next(
        (
            record
            for record in records
            if record["source"] == designated_source
        ),
        None,
    )
    if designated_source and designated_record is None:
        return {
            "valid": False,
            "status": "explicitly_designated_authority_envelope_invalid",
            "reasons": [
                "explicitly_designated_authority_envelope_missing_or_invalid:"
                f"{designated_source}"
            ],
            "records": records,
            "designated_source": designated_source,
        }
    if designated_record is not None and not designated_record["valid"]:
        return {
            **designated_record,
            "valid": False,
            "status": "explicitly_designated_authority_envelope_invalid",
            "reasons": [
                f"{designated_source}:{reason}"
                for reason in designated_record["reasons"]
            ]
            or [f"explicitly_designated_authority_envelope_invalid:{designated_source}"],
            "records": records,
            "designated_source": designated_source,
        }
    valid_records = [record for record in records if record["valid"]]
    valid_digests = {record["digest"] for record in valid_records}
    if len(valid_digests) > 1:
        return {
            "valid": False,
            "status": "conflicting_current_authority_envelopes",
            "reasons": ["multiple_distinct_current_authority_envelopes"],
            "records": records,
        }
    if designated_record is not None:
        return {
            **designated_record,
            "status": "single_current_schema_immutable_envelope",
            "records": records,
            "valid_sources": [record["source"] for record in valid_records],
            "selection_basis": "explicit_nested_authority_field",
            "designated_source": designated_source,
        }
    if valid_records:
        selected = valid_records[0]
        if any(
            record["payload"] and record["digest"] != selected["digest"]
            for record in records
        ):
            return {
                "valid": False,
                "status": "conflicting_current_authority_envelopes",
                "reasons": ["mixed_current_authority_envelope_payloads"],
                "records": records,
            }
        return {
            **selected,
            "status": "single_current_schema_immutable_envelope",
            "records": records,
            "valid_sources": [record["source"] for record in valid_records],
        }
    return {
        "valid": False,
        "status": (
            "legacy_or_hash_only_authority_diagnostic_only"
            if records
            else "authority_envelope_missing"
        ),
        "reasons": [
            f"{record['source']}:{reason}"
            for record in records
            for reason in record["reasons"]
        ]
        or ["package_new_entry_authority_envelope_missing"],
        "records": records,
    }


def signed_package_new_entry_authority_required(row: Mapping[str, Any]) -> tuple[bool, str]:
    action_intent = canonical_scheduler_action_intent(
        first_present_mapping_value(
            row,
            (
                "scheduler_materialization_action_intent",
                "selected_scheduler_action_class",
                "scheduler_action_class",
                "action_intent",
                "lifecycle_action",
            ),
        )
        or "new_position"
    )
    selector_action = canonical_selector_action(
        normalize_selector_action_for_reason(
            row.get("selector_action"),
            row.get("selector_reason"),
            action_intent,
        )
    )
    new_entry_intent = action_intent in REDUCED_RISK_SIGNED_NEW_ENTRY_ACTION_INTENTS
    required = (selector_action == "open-reduced-risk" and new_entry_intent) or (
        selector_action == "reduce-risk"
        and action_intent not in SELECTOR_REDUCE_RISK_ALLOWED_ACTION_INTENTS
        and new_entry_intent
    )
    return required, action_intent or "new_position"


def signed_package_new_entry_authority_reasons(
    row: Mapping[str, Any],
    *,
    action_intent: str,
    require_immutable_payload: bool = False,
) -> list[str]:
    envelope = package_new_entry_authority_envelope_selection(
        row,
        action_intent=action_intent,
    )
    if envelope.get("valid") is True:
        return []
    records = envelope.get("records") or []
    if len(records) == 1 and isinstance(records[0], Mapping):
        return list(records[0].get("reasons") or [])
    return list(envelope.get("reasons") or [str(envelope.get("status") or "unknown")])

    # Historical flat-field validation is intentionally unreachable. Current
    # execution authority is accepted only through the single-envelope path.
    reasons: list[str] = []
    if row.get("package_new_entry_authority_required") is not True:
        reasons.append("package_new_entry_authority_required_missing_or_false")
    if row.get("package_new_entry_authority_valid") is not True:
        status = str(row.get("package_new_entry_authority_status") or "missing")
        reasons.append(f"package_new_entry_authority_invalid:{status}")
    failures = row.get("package_new_entry_authority_failures")
    if isinstance(failures, str):
        failure_items = [failures] if failures.strip() else []
    elif isinstance(failures, Sequence) and not isinstance(
        failures,
        (bytes, bytearray),
    ):
        failure_items = [str(item) for item in failures if str(item or "").strip()]
    else:
        failure_items = []
    reasons.extend(
        f"package_new_entry_authority_failure:{failure}"
        for failure in failure_items
    )
    authority_hash = row.get("package_new_entry_authority_hash_sha256")
    expected_hash = row.get("expected_package_new_entry_authority_hash_sha256")
    if authority_hash in (None, "", [], {}):
        reasons.append("package_new_entry_authority_hash_missing")
    if expected_hash in (None, "", [], {}):
        reasons.append("expected_package_new_entry_authority_hash_missing")
    if authority_hash not in (None, "", [], {}) and expected_hash not in (
        None,
        "",
        [],
        {},
    ) and authority_hash != expected_hash:
        reasons.append("package_new_entry_authority_hash_mismatch")
    payload_schema = row.get("package_new_entry_authority_payload_schema")
    if payload_schema != PACKAGE_NEW_ENTRY_AUTHORITY_PAYLOAD_SCHEMA:
        reasons.append("package_new_entry_authority_payload_schema_invalid")
    scope = row.get("package_new_entry_authority_scope")
    expected_scope = PACKAGE_NEW_ENTRY_EXPECTED_SCOPE_BY_TARGET_INTENT.get(
        action_intent,
        PACKAGE_NEW_ENTRY_AUTHORITY_SCOPE,
    )
    if scope != expected_scope:
        reasons.append("package_new_entry_authority_scope_invalid")
    target_action = canonical_scheduler_action_intent(
        row.get("package_new_entry_authority_target_action_intent")
    )
    if target_action != action_intent:
        reasons.append("package_new_entry_authority_target_action_intent_mismatch")
    boundary_reason = predecision_boundary_bad_reason(
        row.get("package_new_entry_authority_source_boundary"),
        field="package_new_entry_authority_source_boundary",
    )
    if boundary_reason:
        reasons.append(boundary_reason)
    if row.get("package_new_entry_authority_uses_outcome_fields") is True:
        reasons.append("package_new_entry_authority_uses_outcome_fields")
    identity_pairs = (
        (
            "package_new_entry_authority_candidate_id",
            "candidate_id",
        ),
        (
            "package_new_entry_authority_decision_time_utc",
            "decision_time_utc",
        ),
        (
            "package_new_entry_authority_canonical_replay_candidate_instance_key",
            "canonical_replay_candidate_instance_key",
        ),
        (
            "package_new_entry_authority_source_bound_replay_candidate_instance_key",
            "source_bound_replay_candidate_instance_key",
        ),
    )
    for signed_field, current_field in identity_pairs:
        signed_value = row.get(signed_field)
        if quality_field_missing(signed_value):
            reasons.append(f"{signed_field}_missing")
            continue
        current_values = signed_authority_current_identity_values(row, current_field)
        if not current_values:
            reasons.append(
                f"package_new_entry_authority_current_{current_field}_missing"
            )
            continue
        if str(signed_value) not in current_values:
            reasons.append(f"{signed_field}_mismatch")
    identity_status = str(
        row.get("package_new_entry_authority_candidate_instance_identity_status")
        or ""
    ).strip()
    if not identity_status:
        reasons.append(
            "package_new_entry_authority_candidate_instance_identity_status_missing"
        )
    elif identity_status.startswith("missing") or identity_status == "unmaterialized":
        reasons.append(
            "package_new_entry_authority_candidate_instance_identity_status_invalid:"
            f"{identity_status}"
        )
    field_sources = row.get(
        "package_new_entry_authority_candidate_decision_quality_field_sources"
    )
    if isinstance(field_sources, str):
        try:
            field_sources = json.loads(field_sources)
        except json.JSONDecodeError:
            field_sources = {}
    if not isinstance(field_sources, Mapping):
        reasons.append(
            "package_new_entry_authority_candidate_decision_quality_field_sources_missing"
        )
        field_sources = {}
    for field in PACKAGE_NEW_ENTRY_AUTHORITY_QUALITY_FIELDS:
        if quality_field_missing(field_sources.get(field)):
            reasons.append(
                "package_new_entry_authority_candidate_decision_quality_field_sources."
                f"{field}_missing"
            )
    quality_boundary_reason = predecision_boundary_bad_reason(
        row.get("package_new_entry_authority_candidate_decision_quality_source_boundary"),
        field="package_new_entry_authority_candidate_decision_quality_source_boundary",
    )
    if quality_boundary_reason:
        reasons.append(quality_boundary_reason)
    alias_status = str(
        row.get("package_new_entry_authority_candidate_decision_quality_alias_status")
        or ""
    ).strip()
    if not alias_status:
        reasons.append(
            "package_new_entry_authority_candidate_decision_quality_alias_status_missing"
        )
    elif alias_status != "exact_materialized":
        reasons.append(
            "package_new_entry_authority_candidate_decision_quality_alias_status_invalid:"
            f"{alias_status}"
        )
    alias_mismatches = row.get(
        "package_new_entry_authority_candidate_decision_quality_alias_mismatches"
    )
    if isinstance(alias_mismatches, str):
        try:
            alias_mismatches = json.loads(alias_mismatches)
        except json.JSONDecodeError:
            alias_mismatches = [alias_mismatches] if alias_mismatches.strip() else []
    if isinstance(alias_mismatches, Sequence) and not isinstance(
        alias_mismatches,
        (bytes, bytearray),
    ):
        for mismatch in alias_mismatches:
            if str(mismatch or "").strip():
                reasons.append(
                    "package_new_entry_authority_candidate_decision_quality_alias_mismatch:"
                    f"{mismatch}"
                )
    elif alias_mismatches not in (None, "", [], {}):
        reasons.append(
            "package_new_entry_authority_candidate_decision_quality_alias_mismatch:"
            f"{alias_mismatches}"
        )
    provenance_failures = row.get(
        "package_new_entry_authority_candidate_decision_quality_provenance_failures"
    )
    if isinstance(provenance_failures, str):
        try:
            provenance_failures = json.loads(provenance_failures)
        except json.JSONDecodeError:
            provenance_failures = (
                [provenance_failures] if provenance_failures.strip() else []
            )
    if isinstance(provenance_failures, Sequence) and not isinstance(
        provenance_failures,
        (bytes, bytearray),
    ):
        for failure in provenance_failures:
            if str(failure or "").strip():
                reasons.append(
                    "package_new_entry_authority_candidate_decision_quality_provenance_failure:"
                    f"{failure}"
                )
    elif provenance_failures not in (None, "", [], {}):
        reasons.append(
            "package_new_entry_authority_candidate_decision_quality_provenance_failure:"
            f"{provenance_failures}"
        )
    reasons.extend(
        package_new_entry_authority_payload_contract_reasons(
            row,
            action_intent=action_intent,
            require_immutable_payload=require_immutable_payload,
        )
    )
    return list(dict.fromkeys(reasons))


SCHEDULER_SCORE_OVERRIDE_SOURCE_BOUNDARY = (
    "strict_predecision_signed_package_broker_cost_source_preflight_no_outcome_fields"
)
ZERO_TRADE_SOFT_VETO_SCORE_OVERRIDE_SOURCE = (
    "zero_trade_soft_veto_risk_admitted_scheduler_reallocation_score"
)


def sequence_values(value: Any) -> list[Any]:
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return []
        try:
            parsed = json.loads(text)
        except json.JSONDecodeError:
            return [text]
        return sequence_values(parsed)
    if isinstance(value, Sequence) and not isinstance(value, (bytes, bytearray)):
        return list(value)
    if value in (None, "", [], {}):
        return []
    return [value]


def scheduler_score_override_authority_leak_reasons(
    row: Mapping[str, Any],
) -> list[str]:
    """Fatal authority leaks for strict zero-trade scheduler-score handoffs."""

    override_applied = value_bool_true(
        first_present_mapping_value(
            row,
            (
                "risk_finalizer_scheduler_score_floor_override_applied",
                "finalizer_primary_probe_risk_finalizer_scheduler_score_floor_override_applied",
                "risk_finalizer_best_package_probe_risk_finalizer_scheduler_score_floor_override_applied",
            ),
        )
    )
    if not override_applied:
        return []

    score_source = str(
        first_present_mapping_value(
            row,
            (
                "risk_finalizer_scheduler_quality_score_source",
                "finalizer_primary_probe_risk_finalizer_scheduler_quality_score_source",
                "risk_finalizer_best_package_probe_risk_finalizer_scheduler_quality_score_source",
            ),
        )
        or ""
    ).strip()
    override_reason = str(
        first_present_mapping_value(
            row,
            (
                "risk_finalizer_scheduler_score_floor_override_reason",
                "finalizer_primary_probe_risk_finalizer_scheduler_score_floor_override_reason",
                "risk_finalizer_best_package_probe_risk_finalizer_scheduler_score_floor_override_reason",
            ),
        )
        or ""
    ).strip()
    zero_trade_candidate = value_bool_true(
        first_present_mapping_value(
            row,
            (
                "causal_finalizer_zero_trade_conversion_candidate",
                "risk_finalizer_causal_zero_trade_conversion_candidate",
                "finalizer_admission_zero_trade_conversion_candidate",
            ),
        )
    )
    zero_trade_override = bool(
        zero_trade_candidate
        or score_source == ZERO_TRADE_SOFT_VETO_SCORE_OVERRIDE_SOURCE
        or override_reason.startswith("strict_zero_trade_soft_veto")
    )
    if not zero_trade_override:
        return []

    reasons: list[str] = []
    if score_source != ZERO_TRADE_SOFT_VETO_SCORE_OVERRIDE_SOURCE:
        reasons.append("scheduler_score_override_source_not_zero_trade_soft_veto")
    if not value_bool_true(
        first_present_mapping_value(
            row,
            (
                "risk_finalizer_scheduler_score_floor_override_allowed",
                "finalizer_primary_probe_risk_finalizer_scheduler_score_floor_override_allowed",
                "risk_finalizer_best_package_probe_risk_finalizer_scheduler_score_floor_override_allowed",
            ),
        )
    ):
        reasons.append("scheduler_score_override_allowed_missing_or_false")
    override_failures = sequence_values(
        first_present_mapping_value(
            row,
            (
                "risk_finalizer_scheduler_score_floor_override_failures",
                "finalizer_primary_probe_risk_finalizer_scheduler_score_floor_override_failures",
                "risk_finalizer_best_package_probe_risk_finalizer_scheduler_score_floor_override_failures",
            ),
        )
    )
    if override_failures:
        reasons.append("scheduler_score_override_failures_present")
    boundary = str(
        first_present_mapping_value(
            row,
            (
                "risk_finalizer_scheduler_score_floor_override_source_boundary",
                "finalizer_primary_probe_risk_finalizer_scheduler_score_floor_override_source_boundary",
                "risk_finalizer_best_package_probe_risk_finalizer_scheduler_score_floor_override_source_boundary",
            ),
        )
        or ""
    ).strip()
    if boundary != SCHEDULER_SCORE_OVERRIDE_SOURCE_BOUNDARY:
        reasons.append("scheduler_score_override_source_boundary_missing_or_invalid")
    if value_bool_true(
        first_present_mapping_value(
            row,
            (
                "risk_finalizer_scheduler_score_floor_override_uses_outcome_fields",
                "finalizer_primary_probe_risk_finalizer_scheduler_score_floor_override_uses_outcome_fields",
                "risk_finalizer_best_package_probe_risk_finalizer_scheduler_score_floor_override_uses_outcome_fields",
            ),
        )
    ):
        reasons.append("scheduler_score_override_uses_outcome_fields")

    if not value_bool_true(
        first_present_mapping_value(
            row,
            (
                "package_replay_order_executable_candidate_use_allowed",
                "risk_finalizer_package_order_executable_candidate_use_allowed",
                "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed",
            ),
        )
    ):
        reasons.append("scheduler_score_override_order_executable_authority_missing")

    cost_status = str(
        first_present_mapping_value(
            row,
            (
                "pretrade_cost_packet_status",
                "risk_finalizer_pretrade_cost_packet_status",
                "finalizer_primary_probe_pretrade_cost_packet_status",
            ),
        )
        or ""
    ).upper()
    if cost_status != "PASSED":
        reasons.append("scheduler_score_override_pretrade_cost_not_passed")
    cost_source_gap_status = str(
        first_present_mapping_value(
            row,
            (
                "cost_source_gap_status",
                "risk_finalizer_cost_source_gap_status",
                "finalizer_primary_probe_cost_source_gap_status",
            ),
        )
        or ""
    )
    if cost_source_gap_status != "source_bound_cost_authority_present":
        reasons.append("scheduler_score_override_cost_source_gap_not_source_bound")
    cost_authority = str(
        first_present_mapping_value(
            row,
            (
                "cost_authority",
                "execution_cost_authority",
                "risk_finalizer_cost_authority",
                "finalizer_primary_probe_cost_authority",
            ),
        )
        or ""
    ).strip()
    if cost_authority != "broker_calibrated_replay_cost":
        reasons.append("scheduler_score_override_cost_authority_not_broker_calibrated")
    if value_bool_true(row.get("source_gap_cost_fallback_blocked")):
        reasons.append("scheduler_score_override_source_gap_cost_fallback_blocked")
    if value_bool_true(
        first_present_mapping_value(
            row,
            (
                "candidate_cost_r_fallback_is_authority",
                "risk_finalizer_candidate_cost_r_fallback_is_authority",
                "finalizer_primary_probe_candidate_cost_r_fallback_is_authority",
            ),
        )
    ):
        reasons.append("scheduler_score_override_candidate_cost_r_fallback_authority")

    signed_required, action_intent = signed_package_new_entry_authority_required(row)
    if not signed_required:
        reasons.append("scheduler_score_override_signed_authority_not_required")
    for signed_reason in signed_package_new_entry_authority_reasons(
        row,
        action_intent=action_intent or "new_position",
    ):
        reasons.append(f"scheduler_score_override_signed_authority:{signed_reason}")

    source_completeness = numeric_or_none(row.get("source_completeness"))
    if source_completeness is None or source_completeness < 0.95:
        reasons.append("scheduler_score_override_source_completeness_below_floor")
    source_status = str(row.get("source_completeness_status") or "").lower()
    if any(
        token in source_status
        for token in (
            "missing",
            "degraded",
            "gap",
            "source_required",
            "incomplete",
            "prospective_capture",
            "snapshot_incomplete",
        )
    ):
        reasons.append("scheduler_score_override_source_completeness_status_not_clean")
    preflight_allowed = first_present_mapping_value(
        row,
        (
            "pre_order_materialization_preflight_allowed",
            "risk_finalizer_pre_order_materialization_preflight_allowed",
            "finalizer_primary_probe_pre_order_materialization_preflight_allowed",
        ),
    )
    if preflight_allowed in (None, ""):
        reasons.append("scheduler_score_override_preflight_allowed_missing")
    elif value_bool_false(preflight_allowed):
        reasons.append("scheduler_score_override_preflight_blocked")
    final_risk_pct = numeric_or_none(
        first_present_mapping_value(
            row,
            (
                "final_approved_risk_pct",
                "risk_finalizer_final_approved_risk_pct",
                "finalizer_primary_probe_final_approved_risk_pct",
            ),
        )
    )
    if final_risk_pct is None or final_risk_pct <= 0.0:
        reasons.append("scheduler_score_override_final_risk_nonpositive")
    return list(dict.fromkeys(reasons))


def signed_authority_execution_projection_drift_reasons(
    row: Mapping[str, Any],
) -> list[str]:
    """Reject mutable projection drift after exact signed order admission."""

    signed_valid = value_bool_true(
        first_present_mapping_value(
            row,
            (
                "package_new_entry_authority_valid",
                "scorecard_reported_package_new_entry_authority_valid",
                "finalizer_primary_probe_package_new_entry_authority_valid",
                "risk_finalizer_package_new_entry_authority_valid",
                "risk_finalizer_best_package_probe_package_new_entry_authority_valid",
            ),
        )
    )
    signed_order_allowed = value_bool_true(
        first_present_mapping_value(
            row,
            (
                "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed",
                "package_replay_order_executable_candidate_use_allowed",
                "scorecard_reported_package_replay_order_executable_candidate_use_allowed",
                "finalizer_primary_probe_package_replay_order_executable_candidate_use_allowed",
                "risk_finalizer_package_replay_order_executable_candidate_use_allowed",
                "risk_finalizer_best_package_probe_package_replay_order_executable_candidate_use_allowed",
            ),
        )
    )
    if not (signed_valid and signed_order_allowed):
        return []
    reason = str(
        first_present_mapping_value(
            row,
            (
                "finalizer_primary_probe_package_replay_executable_candidate_use_allowed_reason",
                "risk_finalizer_package_replay_executable_candidate_use_allowed_reason",
                "risk_finalizer_best_package_probe_package_replay_executable_candidate_use_allowed_reason",
                "package_replay_executable_candidate_use_allowed_reason",
            ),
        )
        or ""
    ).strip()
    marker = "current_signed_authority_projection_mismatch:"
    if marker not in reason:
        return []
    atom = reason.split(marker, 1)[1].split(",", 1)[0].split("|", 1)[0]
    return [f"valid_signed_order_authority_mutable_projection_drift:{atom}"]


def signed_marketable_route_session_projection_drift_reasons(
    row: Mapping[str, Any],
) -> list[str]:
    """Reject signed immediate routes stranded by a stale session namespace."""

    surfaces: list[Mapping[str, Any]] = [row]
    finalizer = row.get("risk_admitted_scheduler_finalizer")
    if isinstance(finalizer, Mapping):
        surfaces.extend(
            probe
            for probe in (finalizer.get("probe_rows") or [])
            if isinstance(probe, Mapping)
        )
    reasons: list[str] = []
    for surface in surfaces:
        signed_valid = any(
            value_bool_true(surface.get(field))
            for field in (
                "package_new_entry_authority_valid",
                "finalizer_primary_probe_package_new_entry_authority_valid",
                "risk_finalizer_package_new_entry_authority_valid",
            )
        )
        route_allowed = any(
            value_bool_true(surface.get(field))
            for field in (
                "package_marketable_entry_guard_route_allowed",
                "package_marketable_entry_guard_immediate_marketable_limit_route_allowed",
                "finalizer_primary_probe_package_marketable_entry_guard_route_allowed",
                "finalizer_primary_probe_package_marketable_entry_guard_immediate_marketable_limit_route_allowed",
                "risk_finalizer_package_marketable_entry_guard_route_allowed",
                "risk_finalizer_package_marketable_entry_guard_immediate_marketable_limit_route_allowed",
            )
        )
        immediate_reason = str(
            first_present_mapping_value(
                surface,
                (
                    "pre_order_materialization_immediate_marketable_fill_reason",
                    "finalizer_primary_probe_pre_order_materialization_immediate_marketable_fill_reason",
                    "risk_finalizer_pre_order_materialization_immediate_marketable_fill_reason",
                ),
            )
            or ""
        ).strip()
        route = first_present_mapping_value(
            surface,
            (
                "package_marketable_entry_guard_replay_route",
                "finalizer_primary_probe_package_marketable_entry_guard_replay_route",
                "risk_finalizer_package_marketable_entry_guard_replay_route",
            ),
        )
        route = route if isinstance(route, Mapping) else {}
        route_has_concrete_session = bool(
            value_bool_true(
                route.get(
                    "concrete_execution_session_for_immediate_marketable_limit"
                )
            )
            or canonical_utc_hour_bucket_token(route.get("route_session"))
        )
        preflight_concrete_session = first_present_mapping_value(
            surface,
            (
                "pre_order_materialization_immediate_marketable_concrete_execution_session_authority",
                "finalizer_primary_probe_pre_order_materialization_immediate_marketable_concrete_execution_session_authority",
                "risk_finalizer_pre_order_materialization_immediate_marketable_concrete_execution_session_authority",
            ),
        )
        if (
            signed_valid
            and route_allowed
            and route_has_concrete_session
            and not value_bool_true(preflight_concrete_session)
            and immediate_reason
            == "off_configured_session_immediate_marketable_limit_disabled"
        ):
            reasons.append(
                "signed_immediate_marketable_route_concrete_session_projection_drift"
            )
    return list(dict.fromkeys(reasons))


def signed_marketable_route_authority_precedence_drift_reasons(
    row: Mapping[str, Any],
) -> list[str]:
    """Reject auxiliary router-refusal false overriding exact package route true."""

    surfaces: list[Mapping[str, Any]] = [row]
    finalizer = row.get("risk_admitted_scheduler_finalizer")
    if isinstance(finalizer, Mapping):
        surfaces.extend(
            probe
            for probe in (finalizer.get("probe_rows") or [])
            if isinstance(probe, Mapping)
        )
    reasons: list[str] = []
    for surface in surfaces:
        signed_valid = any(
            value_bool_true(surface.get(field))
            for field in (
                "package_new_entry_authority_valid",
                "finalizer_primary_probe_package_new_entry_authority_valid",
                "risk_finalizer_package_new_entry_authority_valid",
            )
        )
        flat_route_values = [
            surface.get(field)
            for field in (
                "package_marketable_entry_guard_route_allowed",
                "package_marketable_entry_guard_immediate_marketable_limit_route_allowed",
                "finalizer_primary_probe_package_marketable_entry_guard_route_allowed",
                "finalizer_primary_probe_package_marketable_entry_guard_immediate_marketable_limit_route_allowed",
                "risk_finalizer_package_marketable_entry_guard_route_allowed",
                "risk_finalizer_package_marketable_entry_guard_immediate_marketable_limit_route_allowed",
            )
            if surface.get(field) not in (None, "")
        ]
        exact_route_allowed = bool(
            flat_route_values
            and all(value_bool_true(value) for value in flat_route_values)
        )
        preflight_route_allowed = first_present_mapping_value(
            surface,
            (
                "pre_order_materialization_immediate_marketable_route_authority_allowed",
                "finalizer_primary_probe_pre_order_materialization_immediate_marketable_route_authority_allowed",
                "risk_finalizer_pre_order_materialization_immediate_marketable_route_authority_allowed",
            ),
        )
        signature_valid = first_present_mapping_value(
            surface,
            (
                "pre_order_materialization_immediate_marketable_signed_authority_valid",
                "finalizer_primary_probe_pre_order_materialization_immediate_marketable_signed_authority_valid",
                "risk_finalizer_pre_order_materialization_immediate_marketable_signed_authority_valid",
            ),
        )
        concrete_session = first_present_mapping_value(
            surface,
            (
                "pre_order_materialization_immediate_marketable_concrete_execution_session_authority",
                "finalizer_primary_probe_pre_order_materialization_immediate_marketable_concrete_execution_session_authority",
                "risk_finalizer_pre_order_materialization_immediate_marketable_concrete_execution_session_authority",
            ),
        )
        if (
            signed_valid
            and exact_route_allowed
            and value_bool_true(signature_valid)
            and value_bool_true(concrete_session)
            and value_bool_false(preflight_route_allowed)
        ):
            reasons.append(
                "signed_immediate_marketable_exact_route_overridden_by_auxiliary_false"
            )
    return list(dict.fromkeys(reasons))


def replay_executable_authority_leak_reasons(row: dict[str, Any]) -> list[str]:
    reasons: list[str] = []
    reasons.extend(unsigned_router_refusal_executable_authority_leak_reasons(row))
    reasons.extend(current_price_authority_leak_reasons(row))
    reasons.extend(scheduler_score_override_authority_leak_reasons(row))
    reasons.extend(signed_authority_execution_projection_drift_reasons(row))
    reasons.extend(signed_marketable_route_session_projection_drift_reasons(row))
    reasons.extend(signed_marketable_route_authority_precedence_drift_reasons(row))
    executable = any(
        row_bool_true(row, field)
        for field in (
            "package_replay_executable_candidate_use_allowed",
            "selected_scheduler_package_replay_executable_candidate_use_allowed",
            "scheduler_option_package_replay_executable_candidate_use_allowed",
            "ultimate_package_effective_executable_authority_allowed",
        )
    )
    order_executable = any(
        row_bool_true(row, field)
        for field in (
            "package_replay_order_executable_candidate_use_allowed",
            "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed",
            "selected_scheduler_package_replay_order_executable_candidate_use_allowed",
            "scheduler_option_package_replay_order_executable_candidate_use_allowed",
        )
    )
    off_session_applies = bool(
        row_bool_true(row, "selector_materialization_off_session_applies")
        or str(
            first_present_mapping_value(
                row,
                (
                    "raw_selector_reason",
                    "original_selector_reason",
                    "package_new_entry_authority_original_selector_reason",
                ),
            )
            or ""
        ).strip()
        == "admission_quality_off_configured_session_entry_blocked"
    )
    authority_family = str(
        first_present_mapping_value(
            row,
            (
                "package_new_entry_authority_authority_family",
                "package_open_reduced_authority_family",
                "scheduler_option_package_open_reduced_authority_family",
            ),
        )
        or ""
    ).strip()
    off_session_current_config_allowed = value_bool_true(
        first_present_mapping_value(
            row,
            (
                "selector_materialization_open_reduced_authority_current_config_allowed",
                "package_open_reduced_authority_current_config_allowed",
                "scheduler_option_package_open_reduced_authority_current_config_allowed",
            ),
        )
    )
    if order_executable and off_session_applies:
        if authority_family != "off_session_softening":
            reasons.append(
                "off_session_order_executable_without_off_session_authority_family"
            )
        elif not off_session_current_config_allowed:
            reasons.append(
                "off_session_order_executable_without_current_config_authority"
            )
    if not executable:
        positive_non_executable_r_fields = (
            "ultimate_package_effective_source_bound_signal_r",
            "ultimate_package_combined_source_bound_signal_r_sum",
            "ultimate_package_member_axis_source_bound_signal_r_sum",
            "package_source_bound_r",
            "source_bound_r",
            "combined_source_bound_signal_r",
            "source_bound_proxy_r",
        )
        for field in positive_non_executable_r_fields:
            value = numeric_or_none(row.get(field))
            if value is not None and value > 0.0:
                reasons.append(f"non_executable_positive_source_bound_r_leak:{field}")
        if row_bool_true(row, "ultimate_package_effective_executable_authority_allowed"):
            reasons.append(
                "non_executable_effective_executable_authority_allowed_leak"
            )
        source_bound = any(
            row_bool_true(row, field)
            for field in (
                "source_bound_package_candidate_use_allowed",
                "ultimate_package_source_bound_candidate_use_allowed",
                "package_replay_source_bound_candidate_use_allowed",
                "ultimate_package_effective_source_bound_candidate_use_allowed",
            )
        )
        if source_bound and row_bool_true(
            row, "ultimate_package_effective_source_bound_candidate_use_allowed"
        ):
            if not row_bool_true(
                row, "ultimate_package_effective_source_bound_non_executable"
            ):
                reasons.append(
                    "non_executable_source_bound_missing_non_executable_diagnostic"
                )
            if not str(
                row.get("ultimate_package_effective_source_bound_non_executable_reason")
                or row.get("ultimate_package_effective_executable_authority_reason")
                or row.get("package_replay_executable_candidate_use_allowed_reason")
                or ""
            ).strip():
                reasons.append(
                    "non_executable_source_bound_missing_non_executable_reason"
                )
        return reasons
    source_bound = any(
        row_bool_true(row, field)
        for field in (
            "source_bound_package_candidate_use_allowed",
            "ultimate_package_source_bound_candidate_use_allowed",
            "package_replay_source_bound_candidate_use_allowed",
        )
    )
    if not source_bound:
        reasons.append("executable_without_source_bound_membership")
    for field in ("candidate_decision_quality_source_boundary", "source_boundary"):
        boundary_reason = predecision_boundary_bad_reason(
            row.get(field),
            field=field,
        )
        if boundary_reason:
            reasons.append(boundary_reason)
    if (
        "package_replay_executable_candidate_use_allowed" in row
        and row.get("package_replay_candidate_use_allowed")
        != row.get("package_replay_executable_candidate_use_allowed")
    ):
        reasons.append("package_replay_candidate_use_allowed_mismatch")
    executable_reason = str(
        row.get("package_replay_executable_candidate_use_allowed_reason")
        or row.get("replay_candidate_use_allowed_now_reason")
        or ""
    ).strip()
    if canonical_executable_reason(executable_reason) != "broker_cost_selector_scheduler_executable":
        reasons.append("executable_reason_missing_or_not_authoritative")
    cost_status = str(row.get("pretrade_cost_packet_status") or "").upper()
    if cost_status != "PASSED":
        reasons.append("pretrade_cost_packet_status_not_passed")
    cost_authority = str(
        row.get("cost_authority") or row.get("pretrade_cost_packet_authority") or ""
    ).strip()
    if not cost_authority:
        reasons.append("cost_authority_missing")
    elif cost_authority != "broker_calibrated_replay_cost":
        reasons.append(f"cost_authority_unexpected:{cost_authority}")
    if str(row.get("cost_source_gap_status") or "") != "source_bound_cost_authority_present":
        reasons.append("cost_source_gap_status_not_source_bound_authority")
    if row.get("source_gap_cost_fallback_blocked") is True:
        reasons.append("source_gap_cost_fallback_blocked")
    if row.get("candidate_cost_r_fallback_is_authority") is True:
        reasons.append("candidate_cost_r_fallback_is_authority")
    scheduler_skip_reason = row.get("scheduler_materialization_skip_reason")
    if scheduler_skip_reason not in (None, "") and not scheduler_materialization_skip_is_soft_transfer(
        row,
        scheduler_skip_reason,
    ):
        reasons.append("scheduler_materialization_skip_reason_present")
    action_intent = canonical_scheduler_action_intent(
        first_present_mapping_value(
            row,
            (
                "scheduler_materialization_action_intent",
                "selected_scheduler_action_class",
                "scheduler_action_class",
                "action_intent",
                "lifecycle_action",
            ),
        )
        or ""
    )
    if not action_intent:
        reasons.append("scheduler_materialization_action_intent_missing")
    elif action_intent not in EXECUTABLE_SCHEDULER_ACTION_INTENTS:
        reasons.append("scheduler_materialization_action_intent_invalid")
    raw_selector_action = canonical_selector_action(
        first_present_mapping_value(
            row,
            (
                "selector_action_origin",
                "scheduler_materialization_original_selector_action",
                "original_position_selector_action",
                "selector_action",
            ),
        )
    )
    selector_action = canonical_selector_action(
        first_present_mapping_value(
            row,
            (
                "effective_selector_action",
                "materialized_package_new_entry_authority_selector_action",
                "scheduler_materialization_effective_selector_action",
                "selected_scheduler_effective_selector_action",
                "selector_action",
            ),
        )
    )
    override = any(
        row_bool_true(row, field)
        for field in (
            "scheduler_materialization_source_required_selector_hold_override_applied",
            "scheduler_materialization_source_required_fail_closed_override_applied",
        )
    )
    materialization_signature_present = any(
        first_present_mapping_value(row, (field,)) not in (None, "", [], {})
        for field in (
            "package_new_entry_authority_hash_sha256",
            "materialized_package_new_entry_authority_hash_sha256",
            "scheduler_materialization_package_new_entry_authority_hash_sha256",
            "scheduler_materialization_signed_authority_hash_sha256",
        )
    ) or any(
        value_bool_true(first_present_mapping_value(row, (field,)))
        for field in (
            "materialized_package_new_entry_authority_applied",
            "scheduler_materialization_signed_authority_valid",
            "signed_package_new_entry_authority_valid",
        )
    )
    if not selector_action:
        reasons.append("effective_selector_action_missing")
    if (
        raw_selector_action in {"reject", "hold", "source-required"}
        and selector_action in {"trade", "open-reduced-risk"}
        and not override
        and not materialization_signature_present
    ):
        reasons.append(
            "raw_blocking_selector_action_promoted_without_signed_materialization"
        )
    if (
        raw_selector_action == "reject"
        and selector_action in {"open-reduced-risk", "reduce-risk", "trade"}
        and action_intent in EXECUTABLE_SCHEDULER_ACTION_INTENTS
        and not override
    ):
        if not row_bool_true(
            row,
            "raw_selector_reject_open_reduced_order_executable_promotion_allowed",
        ):
            reasons.append(
                "raw_selector_reject_promoted_executable_without_promotion_contract"
            )
        promotion_failures = row.get(
            "raw_selector_reject_open_reduced_order_executable_promotion_failures"
        )
        if promotion_failures not in (None, "", [], {}):
            reasons.append(
                "raw_selector_reject_promotion_contract_failures_present"
            )
        min_limit_fillability = numeric_or_none(
            row.get("raw_selector_reject_open_reduced_promotion_min_limit_fillability")
        )
        limit_fillability_probability = numeric_or_none(
            first_present_mapping_value(
                row,
                (
                    "raw_selector_reject_open_reduced_promotion_limit_fillability_probability",
                    "predecision_limit_fillability_probability",
                    "limit_fillability_probability",
                    "pending_limit_fillability_probability",
                ),
            )
        )
        if min_limit_fillability is not None:
            if limit_fillability_probability is None:
                reasons.append(
                    "raw_selector_reject_promotion_limit_fillability_missing"
                )
            elif limit_fillability_probability < min_limit_fillability:
                reasons.append(
                    "raw_selector_reject_promotion_limit_fillability_below_floor"
                )
    source_required_action = (
        selector_action == "source-required"
        or (
            raw_selector_action == "source-required"
            and not materialization_signature_present
        )
        or action_intent == "source_required_fail_closed"
        or str(row.get("same_symbol_lifecycle_action") or "")
        == "source_required_fail_closed"
        or str(row.get("scheduler_materialization_original_action_intent") or "")
        == "invalid_action_intent:source_required_fail_closed"
        or source_required_replay_override_applied(row)
    )
    if source_required_action:
        source_required_reconcile_applied = any(
            row_bool_true(row, field)
            for field in (
                "execution_manager_source_required_package_risk_lifecycle_reconcile_applied",
                "source_required_package_risk_lifecycle_reconcile_applied",
                "scheduler_materialization_source_required_fail_closed_override_applied",
            )
        ) or source_required_replay_override_applied(row)
        if not source_required_reconcile_applied:
            reasons.append("source_required_replay_reconcile_not_applied")
        source_required_failures = row.get(
            "scheduler_materialization_source_required_fail_closed_override_failures"
        )
        if source_required_failures not in (None, "", [], {}):
            reasons.append("source_required_override_failures_present")
        source_required_reason = str(
            row.get("scheduler_materialization_override_reason") or ""
        )
        if source_required_reason not in SOURCE_REQUIRED_REPLAY_OVERRIDE_REASONS:
            reasons.append("source_required_override_reason_missing_or_invalid")
        for field, floor in (
            ("source_completeness", 0.95),
            ("candidate_expected_net_r", 0.0),
            ("candidate_probability", 0.0),
            ("candidate_fill_probability", 0.0),
        ):
            value = numeric_or_none(row.get(field))
            if value is None:
                reasons.append(f"source_required_quality_field_missing:{field}")
            elif value < floor:
                reasons.append(f"source_required_quality_field_below_floor:{field}")
    if not selector_action:
        reasons.append("selector_action_missing")
    elif selector_action == "reduce-risk":
        if action_intent not in SELECTOR_REDUCE_RISK_ALLOWED_ACTION_INTENTS:
            signed_row = {
                **row,
                "selector_action": selector_action,
                "scheduler_materialization_action_intent": action_intent,
            }
            signed_reasons = signed_package_new_entry_authority_reasons(
                signed_row,
                action_intent=action_intent,
            )
            if signed_reasons:
                reasons.append("selector_reduce_risk_not_new_order_authority")
                reasons.extend(
                    f"signed_package_new_entry_authority:{reason}"
                    for reason in signed_reasons
                )
    elif selector_action == "open-reduced-risk" and not open_reduced_authority_valid(row):
        reasons.append("selector_open_reduced_risk_authority_missing")
    elif (
        selector_action not in {"trade", "open-reduced-risk"}
        and not override
        and not source_required_action
    ):
        reasons.append("selector_action_not_risk_bearing")
    if row.get("package_authority_has_order_geometry") is False:
        reasons.append("package_authority_order_geometry_missing")
    if (
        str(row.get("package_authority_order_geometry_status") or "")
        == "package_authority_candidate_missing_entry_stop_target_geometry"
    ):
        reasons.append("package_authority_order_geometry_missing")
    return reasons


def reallocation_terminal_disposition_reconciliation_reasons(
    row: Mapping[str, Any],
) -> list[str]:
    finalizer = row.get("risk_admitted_scheduler_finalizer")
    if not isinstance(finalizer, Mapping):
        finalizer = row.get("risk_admitted_finalizer")
    if not isinstance(finalizer, Mapping):
        return []
    reasons: list[str] = []
    candidate_count = numeric_or_none(
        finalizer.get("reallocation_candidate_probe_count")
    )
    zero_trade_candidate_count = numeric_or_none(
        finalizer.get("zero_trade_conversion_candidate_probe_count")
    )
    causal_candidate_count = int(candidate_count or 0) + int(
        zero_trade_candidate_count or 0
    )
    causal_gate_enabled = finalizer.get("causal_quality_gate_enabled") is True
    causal_applied_count = numeric_or_none(
        finalizer.get("causal_quality_gate_applied_probe_count")
    )
    if (
        causal_gate_enabled
        and causal_candidate_count > 0
        and int(causal_applied_count or 0) <= 0
    ):
        reasons.append(
            "causal_quality_gate_zero_applied_with_candidate_probes:"
            f"candidates={causal_candidate_count}"
        )

    probe_rows = finalizer.get("probe_rows")
    if isinstance(probe_rows, list):
        for probe in probe_rows:
            if not isinstance(probe, Mapping):
                continue
            selected_policy_failures = value_list_texts(
                probe.get("selected_policy_executable_quality_gate_failures")
            )
            if (
                probe.get("scheduler_soft_veto_finalizer_probe_applied") is True
                and probe.get(
                    "scheduler_soft_veto_signed_order_stale_selector_alias_probe_allowed"
                )
                is True
                and probe.get(
                    "scheduler_soft_veto_signed_order_stale_selector_disposition_contract_valid"
                )
                is True
                and probe.get("selected_policy_executable_quality_gate_status")
                == "blocked"
                and selected_policy_failures
                and not str(
                    probe.get("policy_selection_block_reason") or ""
                ).startswith(
                    (
                        "selected_policy_executable_quality_gate_failed:",
                        "causal_reallocation_quality_gate_failed:",
                        "causal_zero_trade_conversion_quality_gate_failed:",
                    )
                )
            ):
                reasons.append(
                    "signed_order_stale_selector_alias_selected_policy_quality_block_masked"
                )

    scheduler_bound_count = numeric_or_none(
        finalizer.get("scheduler_bound_option_probe_count")
    )
    scheduler_bound_counts = finalizer.get(
        "scheduler_bound_terminal_disposition_counts"
    )
    if scheduler_bound_count is not None:
        scheduler_bound_expected_keys = {
            "selected",
            "quality_blocked",
            "policy_blocked",
            "authority_blocked",
            "scheduler_ineligible",
            "diagnostic_unadmitted",
        }
        if not isinstance(scheduler_bound_counts, Mapping):
            reasons.append("scheduler_bound_terminal_disposition_counts_missing")
        else:
            missing_scheduler_bound_keys = scheduler_bound_expected_keys.difference(
                str(key) for key in scheduler_bound_counts
            )
            reasons.extend(
                f"scheduler_bound_terminal_disposition_missing:{key}"
                for key in sorted(missing_scheduler_bound_keys)
            )
            scheduler_bound_total = sum(
                int(numeric_or_none(scheduler_bound_counts.get(key)) or 0)
                for key in scheduler_bound_expected_keys
            )
            if scheduler_bound_total != int(scheduler_bound_count):
                reasons.append(
                    "scheduler_bound_terminal_disposition_count_mismatch:"
                    f"expected={int(scheduler_bound_count)}:actual={scheduler_bound_total}"
                )
        if (
            finalizer.get("scheduler_bound_terminal_disposition_reconciled")
            is not True
        ):
            reasons.append(
                "scheduler_bound_terminal_disposition_reconciled_not_true"
            )
        scheduler_bound_input_count = numeric_or_none(
            finalizer.get("scheduler_bound_input_option_count")
        )
        if scheduler_bound_input_count is None:
            reasons.append("scheduler_bound_input_option_count_missing")
        elif int(scheduler_bound_input_count) != int(scheduler_bound_count):
            reasons.append(
                "scheduler_bound_option_probe_count_mismatch:"
                f"expected={int(scheduler_bound_input_count)}:"
                f"actual={int(scheduler_bound_count)}"
            )
            synthesized_diagnostic_count = numeric_or_none(
                finalizer.get("finalizer_synthesized_all_candidate_option_count")
            )
            if (
                synthesized_diagnostic_count is not None
                and int(scheduler_bound_input_count) > int(scheduler_bound_count)
                and int(scheduler_bound_input_count) - int(scheduler_bound_count)
                == int(synthesized_diagnostic_count)
            ):
                reasons.append(
                    "scheduler_bound_input_includes_synthesized_diagnostic_options:"
                    f"count={int(synthesized_diagnostic_count)}"
                )
        if (
            finalizer.get(
                "scheduler_bound_terminal_disposition_identity_schema_version"
            )
            != "risk_finalizer_scheduler_bound_terminal_identity_partition_v1"
        ):
            reasons.append("scheduler_bound_identity_partition_schema_invalid")
        scheduler_bound_input_keys = finalizer.get(
            "scheduler_bound_input_instance_keys"
        )
        scheduler_bound_partition_keys = finalizer.get(
            "scheduler_bound_partition_instance_keys"
        )
        if not isinstance(scheduler_bound_input_keys, list):
            reasons.append("scheduler_bound_input_instance_keys_missing")
            scheduler_bound_input_keys = []
        if not isinstance(scheduler_bound_partition_keys, list):
            reasons.append("scheduler_bound_partition_instance_keys_missing")
            scheduler_bound_partition_keys = []
        scheduler_bound_input_keys = [
            str(value).strip()
            for value in scheduler_bound_input_keys
            if str(value or "").strip()
        ]
        scheduler_bound_partition_keys = [
            str(value).strip()
            for value in scheduler_bound_partition_keys
            if str(value or "").strip()
        ]
        if any("@@" not in key for key in scheduler_bound_input_keys):
            reasons.append("scheduler_bound_input_instance_key_not_exact")
        if any("@@" not in key for key in scheduler_bound_partition_keys):
            reasons.append("scheduler_bound_partition_instance_key_not_exact")
        scheduler_bound_input_unique_count = numeric_or_none(
            finalizer.get("scheduler_bound_input_unique_instance_count")
        )
        if scheduler_bound_input_unique_count is None or int(
            scheduler_bound_input_unique_count
        ) != len(set(scheduler_bound_input_keys)):
            reasons.append("scheduler_bound_input_unique_instance_count_mismatch")
        if scheduler_bound_input_count is not None and int(
            scheduler_bound_input_count
        ) != len(scheduler_bound_input_keys):
            reasons.append("scheduler_bound_input_identity_count_mismatch")
        if int(scheduler_bound_count) != len(scheduler_bound_partition_keys):
            reasons.append("scheduler_bound_partition_identity_count_mismatch")
        if set(scheduler_bound_input_keys) != set(scheduler_bound_partition_keys):
            reasons.append("scheduler_bound_partition_identity_set_mismatch")
        for field in (
            "scheduler_bound_input_duplicate_instance_keys",
            "scheduler_bound_partition_duplicate_instance_keys",
            "scheduler_bound_missing_partition_instance_keys",
            "scheduler_bound_unexpected_partition_instance_keys",
        ):
            value = finalizer.get(field)
            if value not in ([], ()):
                reasons.append(f"{field}_not_empty")
        for field in (
            "scheduler_bound_input_missing_instance_key_count",
            "scheduler_bound_partition_missing_instance_key_count",
        ):
            if int(numeric_or_none(finalizer.get(field)) or 0) != 0:
                reasons.append(f"{field}_nonzero")
        if (
            finalizer.get(
                "scheduler_bound_terminal_disposition_identity_reconciled"
            )
            is not True
        ):
            reasons.append(
                "scheduler_bound_terminal_disposition_identity_reconciled_not_true"
            )

    stale_alias_candidate_count = numeric_or_none(
        finalizer.get("signed_order_stale_selector_alias_candidate_count")
    )
    stale_alias_probe_count = numeric_or_none(
        finalizer.get("signed_order_stale_selector_alias_probe_count")
    )
    stale_alias_probe_eligible_count = numeric_or_none(
        finalizer.get("signed_order_stale_selector_alias_probe_eligible_count")
    )
    stale_alias_probe_not_applied_count = numeric_or_none(
        finalizer.get("signed_order_stale_selector_alias_probe_not_applied_count")
    )
    stale_alias_terminal_count = numeric_or_none(
        finalizer.get("signed_order_stale_selector_alias_terminal_count")
    )
    stale_alias_quality_blocked_count = numeric_or_none(
        finalizer.get(
            "signed_order_stale_selector_alias_quality_blocked_probe_count"
        )
    )
    stale_alias_selected_count = numeric_or_none(
        finalizer.get("signed_order_stale_selector_alias_selected_probe_count")
    )
    stale_alias_other_terminal_count = numeric_or_none(
        finalizer.get(
            "signed_order_stale_selector_alias_other_terminal_probe_count"
        )
    )
    stale_alias_counts = (
        stale_alias_candidate_count,
        stale_alias_probe_eligible_count,
        stale_alias_probe_count,
        stale_alias_probe_not_applied_count,
        stale_alias_terminal_count,
        stale_alias_quality_blocked_count,
        stale_alias_selected_count,
        stale_alias_other_terminal_count,
    )
    if any(value is not None for value in stale_alias_counts):
        if any(value is None for value in stale_alias_counts):
            reasons.append("signed_order_stale_selector_alias_partition_incomplete")
        else:
            (
                stale_alias_candidate_total,
                stale_alias_probe_eligible_total,
                stale_alias_probe_total,
                stale_alias_probe_not_applied_total,
                stale_alias_terminal_total,
                stale_alias_quality_blocked_total,
                stale_alias_selected_total,
                stale_alias_other_terminal_total,
            ) = tuple(int(value or 0) for value in stale_alias_counts)
            if stale_alias_candidate_total != (
                stale_alias_probe_total + stale_alias_terminal_total
            ):
                reasons.append(
                    "signed_order_stale_selector_alias_candidate_partition_mismatch"
                )
            if stale_alias_probe_total != sum(
                (
                    stale_alias_quality_blocked_total,
                    stale_alias_selected_total,
                    stale_alias_other_terminal_total,
                )
            ):
                reasons.append(
                    "signed_order_stale_selector_alias_probe_partition_mismatch"
                )
            if stale_alias_probe_eligible_total != stale_alias_probe_total:
                reasons.append(
                    "signed_order_stale_selector_alias_eligible_probe_not_applied"
                )
            if stale_alias_probe_not_applied_total != 0:
                reasons.append(
                    "signed_order_stale_selector_alias_probe_not_applied_nonzero"
                )
            if (
                finalizer.get(
                    "signed_order_stale_selector_alias_partition_schema_version"
                )
                != "signed_order_stale_selector_alias_identity_partition_v1"
            ):
                reasons.append(
                    "signed_order_stale_selector_alias_partition_schema_invalid"
                )
            alias_identity_specs = (
                (
                    stale_alias_candidate_total,
                    "signed_order_stale_selector_alias_candidate_instance_keys",
                ),
                (
                    stale_alias_probe_eligible_total,
                    "signed_order_stale_selector_alias_probe_eligible_instance_keys",
                ),
                (
                    stale_alias_probe_total,
                    "signed_order_stale_selector_alias_probe_instance_keys",
                ),
                (
                    stale_alias_terminal_total,
                    "signed_order_stale_selector_alias_terminal_instance_keys",
                ),
                (
                    stale_alias_quality_blocked_total,
                    "signed_order_stale_selector_alias_quality_blocked_instance_keys",
                ),
                (
                    stale_alias_selected_total,
                    "signed_order_stale_selector_alias_selected_instance_keys",
                ),
                (
                    stale_alias_other_terminal_total,
                    "signed_order_stale_selector_alias_other_terminal_instance_keys",
                ),
            )
            alias_identity_sets: dict[str, set[str]] = {}
            for expected_count, field in alias_identity_specs:
                values = finalizer.get(field)
                if not isinstance(values, list):
                    reasons.append(f"{field}_missing")
                    values = []
                normalized_values = [
                    str(value).strip()
                    for value in values
                    if str(value or "").strip()
                ]
                alias_identity_sets[field] = set(normalized_values)
                if any("@@" not in key for key in normalized_values):
                    reasons.append(f"{field}_not_exact")
                if len(normalized_values) != len(set(normalized_values)):
                    reasons.append(f"{field}_duplicates_present")
                if len(normalized_values) != expected_count:
                    reasons.append(f"{field}_count_mismatch")
            candidate_keys = alias_identity_sets[
                "signed_order_stale_selector_alias_candidate_instance_keys"
            ]
            probe_eligible_keys = alias_identity_sets[
                "signed_order_stale_selector_alias_probe_eligible_instance_keys"
            ]
            probe_keys = alias_identity_sets[
                "signed_order_stale_selector_alias_probe_instance_keys"
            ]
            terminal_keys = alias_identity_sets[
                "signed_order_stale_selector_alias_terminal_instance_keys"
            ]
            quality_keys = alias_identity_sets[
                "signed_order_stale_selector_alias_quality_blocked_instance_keys"
            ]
            selected_keys = alias_identity_sets[
                "signed_order_stale_selector_alias_selected_instance_keys"
            ]
            other_keys = alias_identity_sets[
                "signed_order_stale_selector_alias_other_terminal_instance_keys"
            ]
            if candidate_keys != probe_keys | terminal_keys or probe_keys & terminal_keys:
                reasons.append(
                    "signed_order_stale_selector_alias_candidate_identity_partition_mismatch"
                )
            if probe_eligible_keys != probe_keys:
                reasons.append(
                    "signed_order_stale_selector_alias_probe_eligible_identity_mismatch"
                )
            if (
                probe_keys != quality_keys | selected_keys | other_keys
                or quality_keys & selected_keys
                or quality_keys & other_keys
                or selected_keys & other_keys
            ):
                reasons.append(
                    "signed_order_stale_selector_alias_probe_identity_partition_mismatch"
                )
            if int(
                numeric_or_none(
                    finalizer.get(
                        "signed_order_stale_selector_alias_missing_instance_key_count"
                    )
                )
                or 0
            ) != 0:
                reasons.append(
                    "signed_order_stale_selector_alias_missing_instance_key_count_nonzero"
                )
            if finalizer.get(
                "signed_order_stale_selector_alias_duplicate_instance_keys"
            ) not in ([], ()):
                reasons.append(
                    "signed_order_stale_selector_alias_duplicate_instance_keys_not_empty"
                )
        if (
            finalizer.get(
                "signed_order_stale_selector_alias_partition_reconciled"
            )
            is not True
        ):
            reasons.append(
                "signed_order_stale_selector_alias_partition_reconciled_not_true"
            )

    if candidate_count is None or candidate_count <= 0:
        return reasons
    counts = finalizer.get("reallocation_terminal_disposition_counts")
    if not isinstance(counts, Mapping):
        reasons.append("reallocation_terminal_disposition_counts_missing")
        return reasons
    expected_keys = {
        "selected",
        "quality_blocked",
        "guard_blocked",
        "cost_blocked",
        "lifecycle_blocked",
        "policy_blocked",
        "unadmitted",
    }
    missing_keys = expected_keys.difference(str(key) for key in counts)
    if missing_keys:
        reasons.extend(
            f"reallocation_terminal_disposition_missing:{key}"
            for key in sorted(missing_keys)
        )
    disposition_total = sum(
        int(numeric_or_none(counts.get(key)) or 0) for key in expected_keys
    )
    if disposition_total != int(candidate_count):
        reasons.append(
            "reallocation_terminal_disposition_count_mismatch:"
            f"expected={int(candidate_count)}:actual={disposition_total}"
        )
    if finalizer.get("reallocation_terminal_disposition_reconciled") is not True:
        reasons.append("reallocation_terminal_disposition_reconciled_not_true")
    for key, field in (
        ("selected", "reallocation_selected_probe_count"),
        ("quality_blocked", "reallocation_quality_blocked_probe_count"),
        ("policy_blocked", "reallocation_policy_blocked_probe_count"),
        ("unadmitted", "reallocation_unadmitted_probe_count"),
    ):
        projected = numeric_or_none(finalizer.get(field))
        if projected is None or int(projected) != int(
            numeric_or_none(counts.get(key)) or 0
        ):
            reasons.append(f"reallocation_terminal_disposition_projection_mismatch:{key}")
    exact_rows = finalizer.get("reallocation_terminal_probe_rows")
    if not isinstance(exact_rows, list):
        reasons.append("reallocation_terminal_probe_rows_missing")
        return reasons
    declared_exact_row_count = numeric_or_none(
        finalizer.get("reallocation_terminal_probe_row_count")
    )
    if declared_exact_row_count is None or int(declared_exact_row_count) != len(
        exact_rows
    ):
        reasons.append("reallocation_terminal_probe_row_count_mismatch")
    if len(exact_rows) != int(candidate_count):
        reasons.append(
            "reallocation_terminal_probe_candidate_count_mismatch:"
            f"expected={int(candidate_count)}:actual={len(exact_rows)}"
        )
    exact_instance_keys: list[str] = []
    exact_dispositions: Counter[str] = Counter()
    for exact_row in exact_rows:
        if not isinstance(exact_row, Mapping):
            reasons.append("reallocation_terminal_probe_row_not_mapping")
            continue
        instance_key = str(
            exact_row.get("canonical_replay_candidate_instance_key")
            or exact_row.get("source_bound_replay_candidate_instance_key")
            or exact_row.get("risk_finalizer_probe_instance_key")
            or ""
        ).strip()
        if "@@" not in instance_key or not all(
            part.strip() for part in instance_key.rsplit("@@", 1)
        ):
            reasons.append("reallocation_terminal_probe_instance_key_not_exact")
        else:
            exact_instance_keys.append(instance_key)
        disposition = str(
            exact_row.get("reallocation_terminal_disposition") or ""
        ).strip()
        if disposition not in expected_keys:
            reasons.append(
                "reallocation_terminal_probe_disposition_invalid:"
                f"{disposition or 'missing'}"
            )
        else:
            exact_dispositions[disposition] += 1
        if exact_row.get("reallocation_terminal_disposition_source_boundary") != (
            "risk_finalizer_terminal_selection_no_outcome_fields"
        ):
            reasons.append(
                "reallocation_terminal_probe_source_boundary_invalid"
            )
    if len(exact_instance_keys) != len(set(exact_instance_keys)):
        reasons.append("reallocation_terminal_probe_instance_keys_duplicate")
    for disposition in expected_keys:
        if exact_dispositions[disposition] != int(
            numeric_or_none(counts.get(disposition)) or 0
        ):
            reasons.append(
                "reallocation_terminal_probe_disposition_count_mismatch:"
                f"{disposition}"
            )
    return reasons


def selected_package_quality_row(row: dict[str, Any]) -> bool:
    package_status = str(row.get("selected_package_candidate_use_allowed_status") or "")
    package_status_indicates_selected_row = bool(
        package_status
        and package_status
        not in {
            "no_package_axis_or_candidate_use_alias",
            "no_current_bridge_member_axis_match",
            "source_bound_package_signal_not_executable",
            "no_package_signal",
        }
    )
    return bool(
        row.get("selected_package_replay_row")
        or row.get("selected_package_denominator_use_allowed")
        or row.get("source_bound_package_candidate_use_allowed") is True
        or row.get("ultimate_package_source_bound_candidate_use_allowed") is True
        or row.get("package_replay_source_bound_candidate_use_allowed") is True
        or package_status_indicates_selected_row
    )


def package_replay_authority_scope_present(row: Mapping[str, Any]) -> bool:
    """Return whether package replay authority applies to this verifier row."""

    if not isinstance(row, Mapping):
        return False
    if any(
        row_bool_true(dict(row), field)
        for field in (
            "selected_package_replay_row",
            "selected_package_denominator_use_allowed",
            "source_bound_package_candidate_use_allowed",
            "ultimate_package_source_bound_candidate_use_allowed",
            "package_replay_source_bound_candidate_use_allowed",
            "ultimate_package_effective_source_bound_candidate_use_allowed",
            "package_new_entry_authority_required",
            "package_new_entry_authority_valid",
            "package_replay_executable_candidate_use_allowed",
            "package_replay_order_executable_candidate_use_allowed",
            "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed",
            "selected_scheduler_package_replay_order_executable_candidate_use_allowed",
            "scheduler_option_package_replay_order_executable_candidate_use_allowed",
        )
    ):
        return True
    for count_field in (
        "ultimate_package_admission_sleeve_match_count",
        "ultimate_package_effective_admission_count",
        "admission_sleeve_match_count",
    ):
        value = numeric_or_none(row.get(count_field))
        if value is not None and value > 0.0:
            return True
    return False


def scan_replay_bridge_quality_parity(
    compact_candidate_groups: dict[str, list[dict[str, Any]]],
    scorecard_groups: dict[str, list[dict[str, Any]]],
    denominator_bridge_groups: dict[str, list[dict[str, Any]]] | None = None,
    candidate_groups: dict[str, list[dict[str, Any]]] | None = None,
) -> dict[str, Any]:
    compact_required = (
        "expected_net_r",
        "candidate_expected_net_r",
        "probability",
        "candidate_probability",
        "fill_probability",
        "candidate_fill_probability",
        "source_completeness",
        "source_completeness_status",
        "candidate_decision_quality_source_boundary",
        "source_boundary",
        "source_bound_package_candidate_use_allowed",
        "ultimate_package_source_bound_candidate_use_allowed",
        "package_replay_source_bound_candidate_use_allowed",
        "package_replay_candidate_use_allowed",
        "package_replay_executable_candidate_use_allowed",
        "package_replay_executable_candidate_use_allowed_reason",
        "selected_package_candidate_use_allowed_status",
        *PACKAGE_PACKET_CONTRACT_FIELDS,
        "ultimate_package_effective_matched_count",
        "ultimate_package_effective_admission_count",
        "ultimate_package_effective_source_bound_signal_r",
        "ultimate_package_effective_source_bound_candidate_use_allowed",
        "diagnostic_ultimate_package_effective_source_bound_signal_r",
        "diagnostic_ultimate_package_effective_source_bound_candidate_use_allowed",
        "ultimate_package_effective_source_bound_non_executable",
        "ultimate_package_effective_source_bound_non_executable_reason",
        "ultimate_package_effective_executable_authority_allowed",
        "ultimate_package_effective_executable_authority_reason",
        "ultimate_package_executable_admission_status",
        "ultimate_package_scheduler_consumed_status",
        "broker_pretrade_cost_r",
        "broker_calibrated_expected_cost_r",
        "selector_action",
        "effective_selector_action",
        "selector_reason",
        "entry_price",
        "stop_loss",
        "take_profit_1",
        "target_reference",
        "risk_reward_ratio",
        "trade_parameters",
        "canonical_geometry_status",
    )
    stop_hazard_required = (
        "predecision_stop_hazard_guard_status",
        "predecision_stop_hazard_guard_reason",
        "predecision_stop_hazard_guard_action",
        "predecision_stop_hazard_guard_source_boundary",
        "predecision_stop_hazard_guard_outcome_fields_used",
    )
    stop_hazard_cap_required = (
        "predecision_stop_hazard_guard_risk_cap_applied",
        "predecision_stop_hazard_guard_risk_cap_pct",
        "predecision_stop_hazard_guard_unit_risk_atr",
        "predecision_stop_hazard_guard_distance_to_limit_risk",
        "predecision_stop_hazard_guard_limit_fill_probability",
    )
    option_required = (
        "expected_net_r",
        "candidate_expected_net_r",
        "probability",
        "confidence",
        "fill_probability",
        "source_completeness",
        "broker_pretrade_cost_r",
        "broker_calibrated_expected_cost_r",
        "selector_action",
        "selector_reason",
    )

    def truthy(value: Any) -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return value != 0
        if isinstance(value, str):
            return value.strip().lower() in {"1", "true", "yes", "y", "allowed", "pass"}
        return bool(value)

    def first_present_value(*values: Any) -> Any:
        for value in values:
            if value not in (None, "", [], {}):
                return value
        return None

    def effective_selector_action_value(row: Mapping[str, Any]) -> str:
        return canonical_selector_action(
            first_present_value(
                row.get("effective_selector_action"),
                row.get("materialized_effective_selector_action"),
                row.get("materialized_package_new_entry_authority_selector_action"),
                row.get("scheduler_materialization_effective_selector_action"),
                row.get("selected_scheduler_effective_selector_action"),
                row.get("scheduler_materialization_selector_action"),
                row.get("package_new_entry_authority_selector_action"),
                row.get("selector_action"),
            )
        )

    def quality_contract_value(row: Mapping[str, Any], field: str) -> Any:
        if field == "effective_selector_action":
            return effective_selector_action_value(row)
        return row.get(field)

    def confidence_required_for_quality_row(row: Mapping[str, Any]) -> bool:
        field_sources = row.get("candidate_decision_quality_field_sources")
        field_sources = field_sources if isinstance(field_sources, Mapping) else {}
        scheduler_inputs = row.get("scheduler_candidate_decision_inputs")
        scheduler_inputs = scheduler_inputs if isinstance(scheduler_inputs, Mapping) else {}
        return any(
            value not in (None, "", [], {})
            for value in (
                row.get("confidence"),
                row.get("candidate_confidence"),
                field_sources.get("confidence"),
                scheduler_inputs.get("confidence"),
                scheduler_inputs.get("candidate_confidence"),
                scheduler_inputs.get("scheduler_confidence"),
            )
        )

    def missing_confidence_aliases(row: Mapping[str, Any]) -> list[str]:
        if not confidence_required_for_quality_row(row):
            return []
        missing_fields = [
            field
            for field in ("confidence", "candidate_confidence")
            if quality_field_missing(row.get(field))
        ]
        field_sources = row.get("candidate_decision_quality_field_sources")
        field_sources = field_sources if isinstance(field_sources, Mapping) else {}
        if quality_field_missing(field_sources.get("confidence")):
            missing_fields.append("candidate_decision_quality_field_sources.confidence")
        scheduler_inputs = row.get("scheduler_candidate_decision_inputs")
        scheduler_inputs = scheduler_inputs if isinstance(scheduler_inputs, Mapping) else {}
        scheduler_confidence_input_present = any(
            scheduler_inputs.get(field) not in (None, "", [], {})
            for field in (
                "confidence",
                "candidate_confidence",
                "scheduler_confidence",
            )
        )
        if scheduler_confidence_input_present and quality_field_missing(
            row.get("scheduler_confidence")
        ):
            missing_fields.append("scheduler_confidence")
        return missing_fields

    def stop_hazard_projection_missing_fields(row: Mapping[str, Any]) -> list[str]:
        projection_present = any(
            row.get(field) not in (None, "", [], {})
            for field in (
                "predecision_stop_hazard_guard_status",
                "predecision_stop_hazard_guard_reason",
                "predecision_stop_hazard_guard_action",
                "predecision_stop_hazard_guard_risk_cap_applied",
                "predecision_stop_hazard_guard_risk_cap_pct",
            )
        )
        if not projection_present:
            return []
        counts["selected_stop_hazard_projection_rows"] += 1
        missing_fields = [
            f"predecision_stop_hazard_guard_missing:{field}"
            for field in stop_hazard_required
            if quality_field_missing(row.get(field))
        ]
        action = str(row.get("predecision_stop_hazard_guard_action") or "").strip()
        if action not in {"clear", "cap", "block", "penalize"}:
            missing_fields.append("predecision_stop_hazard_guard_action_invalid")
        if row.get("predecision_stop_hazard_guard_outcome_fields_used") is not False:
            missing_fields.append(
                "predecision_stop_hazard_guard_outcome_fields_used_not_false"
            )
        status = str(row.get("predecision_stop_hazard_guard_status") or "").strip()
        if status == "capped":
            missing_fields.extend(
                f"predecision_stop_hazard_guard_missing:{field}"
                for field in stop_hazard_cap_required
                if quality_field_missing(row.get(field))
            )
            if row.get("predecision_stop_hazard_guard_risk_cap_applied") is not True:
                missing_fields.append(
                    "predecision_stop_hazard_guard_capped_without_risk_cap"
                )
        return list(dict.fromkeys(missing_fields))

    def scheduler_option_quality_contract(option: Mapping[str, Any]) -> str:
        """Classify scheduler options before applying candidate-admission fields.

        Pending-order lifecycle options keep a linked candidate id for traceability,
        but they are not fresh selector/admission candidates unless package replay
        authority explicitly marks them as candidate-use rows.
        """

        if any(
            truthy(option.get(field))
            for field in (
                "package_replay_candidate_use_allowed",
                "package_replay_executable_candidate_use_allowed",
                "source_bound_package_candidate_use_allowed",
                "ultimate_package_source_bound_candidate_use_allowed",
                "ultimate_package_effective_source_bound_candidate_use_allowed",
            )
        ):
            return "candidate_scheduler_options"
        source_type = str(
            option.get("source_type")
            or option.get("scheduler_option_source_type")
            or option.get("option_source_type")
            or ""
        ).strip().lower()
        if source_type in {"pending_order", "pending_lifecycle", "existing_order"}:
            return "pending_lifecycle_scheduler_options"
        if source_type and source_type not in {
            "candidate",
            "generated_candidate",
            "new_candidate",
            "scheduler_candidate",
        }:
            return "non_candidate_scheduler_options"
        return "candidate_scheduler_options"

    compact_missing: Counter[str] = Counter()
    candidate_missing: Counter[str] = Counter()
    denominator_missing: Counter[str] = Counter()
    option_missing: Counter[str] = Counter()
    executable_leaks: Counter[str] = Counter()
    bridge_join_bad: Counter[str] = Counter()
    bridge_join_status_counts: Counter[str] = Counter()
    scorecard_provenance_bad: Counter[str] = Counter()
    compact_scorecard_projection_bad: Counter[str] = Counter()
    package_displacement_quality_bad: Counter[str] = Counter()
    reallocation_terminal_disposition_bad: Counter[str] = Counter()
    dynamic_fillability_bad: Counter[str] = Counter()
    counts: Counter[str] = Counter()
    samples: list[dict[str, Any]] = []
    executable_leak_samples: list[dict[str, Any]] = []
    bridge_join_samples: list[dict[str, Any]] = []
    scorecard_provenance_samples: list[dict[str, Any]] = []
    compact_scorecard_projection_samples: list[dict[str, Any]] = []
    package_displacement_quality_samples: list[dict[str, Any]] = []
    reallocation_terminal_disposition_samples: list[dict[str, Any]] = []
    dynamic_fillability_samples: list[dict[str, Any]] = []

    def record_package_displacement_threshold_truth(
        row: Mapping[str, Any],
        *,
        namespace: str,
        row_number: int,
        source: str,
    ) -> None:
        row_reasons = package_displacement_threshold_truth_reasons(row)
        for reason in row_reasons:
            package_displacement_quality_bad[
                f"{namespace}.{source}:{reason}"
            ] += 1
        if row_reasons and len(package_displacement_quality_samples) < 8:
            package_displacement_quality_samples.append(
                {
                    "namespace": namespace,
                    "row_number": row_number,
                    "candidate_id": row.get("candidate_id")
                    or row.get("selected_candidate_id"),
                    "source": source,
                    "reasons": row_reasons,
                }
            )

    def scorecard_selected_ids(row: Mapping[str, Any]) -> list[str]:
        raw_ids = row.get("selected_candidate_ids")
        if isinstance(raw_ids, str):
            raw_ids = [raw_ids]
        ids = [
            str(item)
            for item in (raw_ids or [])
            if str(item or "").strip()
        ]
        selected_id = str(row.get("selected_candidate_id") or "").strip()
        if selected_id:
            ids.append(selected_id)
        raw_instance_keys = row.get("selected_candidate_instance_keys")
        if isinstance(raw_instance_keys, str):
            raw_instance_keys = [raw_instance_keys]
        for instance_key in raw_instance_keys or []:
            candidate_token = str(instance_key or "").split("@@", 1)[0].strip()
            if candidate_token:
                ids.append(candidate_token)
        selected_instance_key = str(row.get("selected_candidate_instance_key") or "").strip()
        if selected_instance_key:
            candidate_token = selected_instance_key.split("@@", 1)[0].strip()
            if candidate_token:
                ids.append(candidate_token)
        return sorted(set(ids))

    def finalizer_probe_rows(row: Mapping[str, Any]) -> list[Mapping[str, Any]]:
        containers = []
        for key in ("risk_admitted_scheduler_finalizer", "risk_admitted_finalizer"):
            value = row.get(key)
            if isinstance(value, Mapping):
                containers.append(value)
        rows: list[Mapping[str, Any]] = []
        for container in containers:
            for probe_field in ("probe_rows", "selected_probe_rows"):
                probe_rows = container.get(probe_field)
                if isinstance(probe_rows, list):
                    rows.extend(
                        item for item in probe_rows if isinstance(item, Mapping)
                    )
        direct_probe_rows = row.get("probe_rows")
        if isinstance(direct_probe_rows, list):
            rows.extend(
                item for item in direct_probe_rows if isinstance(item, Mapping)
            )
        return rows

    def record_scorecard_provenance(row: Mapping[str, Any], *, namespace: str, row_number: int) -> None:
        selected_ids = scorecard_selected_ids(row)
        no_selected = not selected_ids
        row_reasons: list[str] = []
        for field in ("source_boundary", "candidate_decision_quality_source_boundary"):
            boundary_reason = predecision_boundary_bad_reason(
                row.get(field),
                field=field,
            )
            if boundary_reason:
                row_reasons.append(boundary_reason)
        if no_selected:
            for outcome_field in (
                "final_r",
                "actual_r",
                "cash_pnl",
                "gross_r",
                "net_r",
                "broker_real_pnl",
            ):
                if row.get(outcome_field) not in (None, "", [], {}):
                    row_reasons.append(
                        f"no_selected_scorecard_outcome_field_present:{outcome_field}"
                    )
            for executable_field in (
                "package_replay_candidate_use_allowed",
                "package_replay_executable_candidate_use_allowed",
                "replay_candidate_use_allowed_now",
            ):
                if row.get(executable_field) is True:
                    row_reasons.append(
                        "no_selected_scorecard_executable_authority_present:"
                        f"{executable_field}"
                    )
            for identity_field in (
                "canonical_replay_candidate_instance_key",
                "selected_candidate_instance_key",
                "risk_finalizer_probe_instance_key",
                "source_bound_replay_candidate_instance_key",
            ):
                if row.get(identity_field) not in (None, "", [], {}):
                    row_reasons.append(
                        f"no_selected_scorecard_top_level_{identity_field}_present"
                    )
            if row.get("candidate_instance_identity_status") == "materialized":
                row_reasons.append(
                    "no_selected_scorecard_top_level_candidate_identity_materialized"
                )
        else:
            if row.get("candidate_instance_identity_status") not in (
                None,
                "",
                "materialized",
            ):
                row_reasons.append(
                    "selected_scorecard_candidate_identity_status_not_materialized"
                )
        row_reasons.extend(
            f"candidate_decision_quality:{issue}"
            for issue in default_confidence_provenance_issues(row)
        )
        row_reasons.extend(
            f"candidate_decision_quality:{issue}"
            for issue in confidence_source_omission_issues(row)
        )
        row_reasons.extend(
            f"signed_soft_transfer:{reason}"
            for reason in signed_soft_transfer_displacement_reliance_reasons(row)
        )
        row_reasons.extend(
            f"hard_clean_capped_transfer:{reason}"
            for reason in v220_hard_clean_capped_reduced_risk_contract_reasons(row)
        )
        for reason in row_reasons:
            scorecard_provenance_bad[f"{namespace}.scorecard:{reason}"] += 1
        if row_reasons and len(scorecard_provenance_samples) < 8:
            scorecard_provenance_samples.append(
                {
                    "namespace": namespace,
                    "row_number": row_number,
                    "candidate_id": row.get("candidate_id")
                    or row.get("selected_candidate_id"),
                    "selected_candidate_ids": selected_ids,
                    "source": "scorecard",
                    "reasons": row_reasons,
                }
            )
        for probe_index, probe in enumerate(
            finalizer_probe_rows(row),
            start=1,
        ):
            status = str(probe.get("status") or "").strip()
            probe_reasons: list[str] = []
            for outcome_field in (
                "final_r",
                "actual_r",
                "cash_pnl",
                "gross_r",
                "net_r",
                "broker_real_pnl",
            ):
                if probe.get(outcome_field) not in (None, "", [], {}):
                    probe_reasons.append(f"probe_outcome_field_present:{outcome_field}")
            skip_boundary_checks = status in {
                "candidate_instance_identity_missing",
                "candidate_or_packet_missing",
                "non_candidate_scheduler_option_not_risk_probe",
            }
            if not skip_boundary_checks:
                for field in (
                    "source_boundary",
                    "candidate_decision_quality_source_boundary",
                ):
                    boundary_reason = predecision_boundary_bad_reason(
                        probe.get(field),
                        field=f"probe_{field}",
                    )
                    if boundary_reason:
                        probe_reasons.append(boundary_reason)
            for override_reason in scheduler_score_override_authority_leak_reasons(
                probe
            ):
                probe_reasons.append(
                    f"scheduler_score_override_authority:{override_reason}"
                )
            probe_reasons.extend(
                f"signed_soft_transfer:{reason}"
                for reason in signed_soft_transfer_displacement_reliance_reasons(probe)
            )
            probe_reasons.extend(
                f"hard_clean_capped_transfer:{reason}"
                for reason in v220_hard_clean_capped_reduced_risk_contract_reasons(
                    probe
                )
            )
            for reason in probe_reasons:
                scorecard_provenance_bad[
                    f"{namespace}.scorecard_probe:{reason}"
                ] += 1
            if probe_reasons and len(scorecard_provenance_samples) < 8:
                scorecard_provenance_samples.append(
                    {
                        "namespace": namespace,
                        "row_number": row_number,
                        "probe_number": probe_index,
                        "candidate_id": probe.get("candidate_id"),
                        "source": "risk_finalizer_probe",
                        "reasons": probe_reasons,
                    }
                )

    def record_selected_bridge_join_status(
        row: Mapping[str, Any],
        *,
        namespace: str,
        row_number: int,
        source: str,
    ) -> None:
        bridge_join_status = str(
            row.get("selected_package_bridge_join_status") or ""
        ).strip()
        if bridge_join_status:
            bridge_join_status_counts[bridge_join_status] += 1
        if row.get("selected_package_denominator_use_allowed") is not True:
            return
        row_bridge_join_bad = False
        if bridge_join_status != "exact_candidate_window_join":
            bridge_join_bad[
                f"{namespace}.selected_package_bridge_join_status:"
                f"{bridge_join_status or 'missing'}"
            ] += 1
            row_bridge_join_bad = True
        bridge_join_key = row.get("selected_package_bridge_join_key")
        canonical_instance_key = (
            row.get("canonical_replay_candidate_instance_key")
            or row.get("selected_package_bridge_canonical_replay_candidate_instance_key")
            or row.get("source_bound_replay_candidate_instance_key")
        )
        if bridge_join_key in (None, "", [], {}):
            bridge_join_bad[f"{namespace}.selected_package_bridge_join_key_missing"] += 1
            row_bridge_join_bad = True
        if canonical_instance_key in (None, "", [], {}):
            bridge_join_bad[
                f"{namespace}.canonical_replay_candidate_instance_key_missing"
            ] += 1
            row_bridge_join_bad = True
        elif bridge_join_key not in (None, "", [], {}) and bridge_join_key != canonical_instance_key:
            bridge_join_bad[
                f"{namespace}.selected_package_bridge_join_key_not_canonical_instance_key"
            ] += 1
            row_bridge_join_bad = True
        if row_bridge_join_bad and len(bridge_join_samples) < 8:
            bridge_join_samples.append(
                {
                    "namespace": namespace,
                    "row_number": row_number,
                    "candidate_id": row.get("replay_candidate_id")
                    or row.get("candidate_id"),
                    "source": source,
                    "selected_package_bridge_join_status": bridge_join_status or None,
                    "selected_package_bridge_join_key": row.get(
                        "selected_package_bridge_join_key"
                    ),
                    "canonical_replay_candidate_instance_key": (
                        canonical_instance_key
                    ),
                }
            )

    def selected_package_contract_missing_fields(row: Mapping[str, Any]) -> list[str]:
        missing_fields = [
            field
            for field in PACKAGE_PACKET_CONTRACT_FIELDS
            if quality_field_missing(row.get(field))
        ]
        missing_fields.extend(candidate_decision_quality_missing_fields(row))
        signed_required, action_intent = signed_package_new_entry_authority_required(row)
        if signed_required:
            missing_fields.extend(
                field
                for field in PACKAGE_NEW_ENTRY_AUTHORITY_CONTRACT_FIELDS
                if package_new_entry_authority_contract_field_missing(
                    field,
                    row.get(field),
                )
            )
            missing_fields.extend(
                f"signed_package_new_entry_authority:{reason}"
                for reason in signed_package_new_entry_authority_reasons(
                    row,
                    action_intent=action_intent,
                )
            )
        return list(dict.fromkeys(missing_fields))

    denominator_required = tuple(
        field
        for field in compact_required
        if field not in {"broker_pretrade_cost_r", "broker_calibrated_expected_cost_r"}
    )

    for namespace, rows in (candidate_groups or {}).items():
        for index, row in enumerate(rows, start=1):
            selected_package_row = selected_package_quality_row(row)
            if not selected_package_row:
                continue
            counts["selected_package_candidate_rows"] += 1
            record_package_displacement_threshold_truth(
                row,
                namespace=namespace,
                row_number=index,
                source="candidate",
            )
            leak_reasons = replay_executable_authority_leak_reasons(row)
            for reason in leak_reasons:
                executable_leaks[f"{namespace}.{reason}"] += 1
            if leak_reasons and len(executable_leak_samples) < 8:
                executable_leak_samples.append(
                    {
                        "namespace": namespace,
                        "row_number": index,
                        "candidate_id": row.get("candidate_id"),
                        "source": "candidate",
                        "leak_reasons": leak_reasons,
                    }
                )
            missing_fields = selected_package_contract_missing_fields(row)
            for field in missing_fields:
                candidate_missing[f"{namespace}.{field}"] += 1
            if missing_fields and len(samples) < 8:
                samples.append(
                    {
                        "namespace": namespace,
                        "row_number": index,
                        "candidate_id": row.get("candidate_id"),
                        "source": "candidate",
                        "missing_fields": missing_fields,
                    }
                )
            record_selected_bridge_join_status(
                row,
                namespace=namespace,
                row_number=index,
                source="candidate",
            )

    for namespace, rows in compact_candidate_groups.items():
        for index, row in enumerate(rows, start=1):
            selected_package_row = selected_package_quality_row(row)
            if not selected_package_row:
                continue
            counts["selected_package_compact_rows"] += 1
            record_package_displacement_threshold_truth(
                row,
                namespace=namespace,
                row_number=index,
                source="compact_candidate",
            )
            missing_fields = [
                field
                for field in compact_required
                if quality_field_missing(quality_contract_value(row, field))
            ]
            missing_fields.extend(missing_confidence_aliases(row))
            missing_fields.extend(stop_hazard_projection_missing_fields(row))
            missing_fields.extend(selected_package_contract_missing_fields(row))
            missing_fields = list(dict.fromkeys(missing_fields))
            for field in missing_fields:
                compact_missing[f"{namespace}.{field}"] += 1
            if missing_fields and len(samples) < 8:
                samples.append(
                    {
                        "namespace": namespace,
                        "row_number": index,
                        "candidate_id": row.get("candidate_id"),
                        "source": "compact_candidate",
                        "missing_fields": missing_fields,
                    }
                )
            leak_reasons = replay_executable_authority_leak_reasons(row)
            for reason in leak_reasons:
                executable_leaks[f"{namespace}.{reason}"] += 1
            if leak_reasons and len(executable_leak_samples) < 8:
                executable_leak_samples.append(
                    {
                        "namespace": namespace,
                        "row_number": index,
                        "candidate_id": row.get("candidate_id"),
                        "source": "compact_candidate",
                        "leak_reasons": leak_reasons,
                    }
                )
            record_selected_bridge_join_status(
                row,
                namespace=namespace,
                row_number=index,
                source="compact_candidate",
            )

    for namespace, rows in (denominator_bridge_groups or {}).items():
        for index, row in enumerate(rows, start=1):
            selected_package_row = selected_package_quality_row(row)
            if not selected_package_row:
                continue
            counts["selected_package_denominator_rows"] += 1
            record_package_displacement_threshold_truth(
                row,
                namespace=namespace,
                row_number=index,
                source="denominator_bridge",
            )
            missing_fields = [
                field
                for field in denominator_required
                if quality_field_missing(quality_contract_value(row, field))
            ]
            missing_fields.extend(stop_hazard_projection_missing_fields(row))
            missing_fields.extend(missing_confidence_aliases(row))
            missing_fields.extend(selected_package_contract_missing_fields(row))
            missing_fields = list(dict.fromkeys(missing_fields))
            for field in missing_fields:
                denominator_missing[f"{namespace}.{field}"] += 1
            if missing_fields and len(samples) < 8:
                samples.append(
                    {
                        "namespace": namespace,
                        "row_number": index,
                        "candidate_id": row.get("replay_candidate_id")
                        or row.get("candidate_id"),
                        "source": "denominator_bridge",
                        "missing_fields": missing_fields,
                    }
                )
            leak_reasons = replay_executable_authority_leak_reasons(row)
            for reason in leak_reasons:
                executable_leaks[f"{namespace}.{reason}"] += 1
            if leak_reasons and len(executable_leak_samples) < 8:
                executable_leak_samples.append(
                    {
                        "namespace": namespace,
                        "row_number": index,
                        "candidate_id": row.get("replay_candidate_id")
                        or row.get("candidate_id"),
                        "source": "denominator_bridge",
                        "leak_reasons": leak_reasons,
                    }
                )
            record_selected_bridge_join_status(
                row,
                namespace=namespace,
                row_number=index,
                source="denominator_bridge",
            )

    for namespace, rows in scorecard_groups.items():
        for row_index, row in enumerate(rows, start=1):
            counts["scorecard_rows"] += 1
            compact_projection_reasons = compact_scorecard_projection_reasons(
                row
            )
            for reason in compact_projection_reasons:
                compact_scorecard_projection_bad[
                    f"{namespace}.scorecard:{reason}"
                ] += 1
            if (
                compact_projection_reasons
                and len(compact_scorecard_projection_samples) < 8
            ):
                compact_scorecard_projection_samples.append(
                    {
                        "namespace": namespace,
                        "row_number": row_index,
                        "candidate_id": row.get("candidate_id")
                        or row.get("selected_candidate_id"),
                        "reasons": compact_projection_reasons,
                    }
                )
            record_package_displacement_threshold_truth(
                row,
                namespace=namespace,
                row_number=row_index,
                source="scorecard",
            )
            record_scorecard_provenance(
                row,
                namespace=namespace,
                row_number=row_index,
            )
            reallocation_reasons = (
                reallocation_terminal_disposition_reconciliation_reasons(row)
            )
            for reason in reallocation_reasons:
                reallocation_terminal_disposition_bad[
                    f"{namespace}.scorecard:{reason}"
                ] += 1
            if (
                reallocation_reasons
                and len(reallocation_terminal_disposition_samples) < 8
            ):
                reallocation_terminal_disposition_samples.append(
                    {
                        "namespace": namespace,
                        "row_number": row_index,
                        "candidate_id": row.get("candidate_id")
                        or row.get("selected_candidate_id"),
                        "reasons": reallocation_reasons,
                    }
                )
            displacement_reasons = package_displacement_quality_failure_reasons(row)
            for reason in displacement_reasons:
                package_displacement_quality_bad[f"{namespace}.scorecard:{reason}"] += 1
            if (
                displacement_reasons
                and len(package_displacement_quality_samples) < 8
            ):
                package_displacement_quality_samples.append(
                    {
                        "namespace": namespace,
                        "row_number": row_index,
                        "candidate_id": row.get("candidate_id")
                        or row.get("selected_candidate_id"),
                        "source": "scorecard_selected_scheduler_option",
                        "reasons": displacement_reasons,
                    }
                )
            for option_index, option in enumerate(
                scorecard_scheduler_options(row), start=1
            ):
                if quality_field_missing(option.get("candidate_id")):
                    continue
                record_package_displacement_threshold_truth(
                    option,
                    namespace=namespace,
                    row_number=option_index,
                    source="scorecard_option",
                )
                contract = scheduler_option_quality_contract(option)
                counts[contract] += 1
                if contract != "candidate_scheduler_options":
                    continue
                inputs = option.get("scheduler_candidate_decision_inputs")
                if not isinstance(inputs, dict):
                    inputs = option.get("candidate_decision_inputs")
                inputs = inputs if isinstance(inputs, dict) else {}
                missing_fields = []
                for field in option_required:
                    if field == "confidence":
                        value = first_present_value(
                            option.get("confidence"),
                            option.get("candidate_confidence"),
                            option.get("scheduler_confidence"),
                        )
                    else:
                        value = option.get(field)
                    if quality_field_missing(value):
                        if field == "confidence":
                            value = first_present_value(
                                inputs.get("confidence"),
                                inputs.get("candidate_confidence"),
                                inputs.get("scheduler_confidence"),
                            )
                        else:
                            value = inputs.get(field)
                    if quality_field_missing(value):
                        missing_fields.append(field)
                missing_fields.extend(
                    candidate_decision_quality_missing_fields({**inputs, **dict(option)})
                )
                missing_fields.extend(
                    f"candidate_decision_quality.{issue}"
                    for issue in default_confidence_provenance_issues(
                        {**inputs, **dict(option)}
                    )
                )
                dynamic_fillability_reasons = (
                    dynamic_execution_fillability_floor_issues(
                        {**inputs, **dict(option)}
                    )
                )
                for reason in dynamic_fillability_reasons:
                    dynamic_fillability_bad[f"{namespace}.{reason}"] += 1
                if (
                    dynamic_fillability_reasons
                    and len(dynamic_fillability_samples) < 8
                ):
                    dynamic_fillability_samples.append(
                        {
                            "namespace": namespace,
                            "row_number": row_index,
                            "option_number": option_index,
                            "candidate_id": option.get("candidate_id"),
                            "reasons": dynamic_fillability_reasons,
                        }
                    )
                missing_fields = list(dict.fromkeys(missing_fields))
                for field in missing_fields:
                    option_missing[f"{namespace}.{field}"] += 1
                if missing_fields and len(samples) < 8:
                    samples.append(
                        {
                            "namespace": namespace,
                            "row_number": row_index,
                            "option_number": option_index,
                            "candidate_id": option.get("candidate_id"),
                            "source": "scorecard_scheduler_option",
                            "missing_fields": missing_fields,
                        }
                    )

    return {
        "selected_package_candidate_rows": counts["selected_package_candidate_rows"],
        "selected_package_compact_rows": counts["selected_package_compact_rows"],
        "selected_package_denominator_rows": counts[
            "selected_package_denominator_rows"
        ],
        "selected_stop_hazard_projection_rows": counts[
            "selected_stop_hazard_projection_rows"
        ],
        "scorecard_rows": counts["scorecard_rows"],
        "candidate_scheduler_options": counts["candidate_scheduler_options"],
        "pending_lifecycle_scheduler_options": counts[
            "pending_lifecycle_scheduler_options"
        ],
        "non_candidate_scheduler_options": counts["non_candidate_scheduler_options"],
        "candidate_missing_counts": json_safe_counter(candidate_missing),
        "compact_missing_counts": json_safe_counter(compact_missing),
        "denominator_missing_counts": json_safe_counter(denominator_missing),
        "scorecard_option_missing_counts": json_safe_counter(option_missing),
        "scorecard_provenance_bad_counts": json_safe_counter(
            scorecard_provenance_bad
        ),
        "compact_scorecard_projection_bad_counts": json_safe_counter(
            compact_scorecard_projection_bad
        ),
        "package_displacement_quality_bad_counts": json_safe_counter(
            package_displacement_quality_bad
        ),
        "reallocation_terminal_disposition_bad_counts": json_safe_counter(
            reallocation_terminal_disposition_bad
        ),
        "dynamic_fillability_bad_counts": json_safe_counter(
            dynamic_fillability_bad
        ),
        "executable_authority_leak_counts": json_safe_counter(executable_leaks),
        "selected_package_bridge_join_status_counts": json_safe_counter(
            bridge_join_status_counts
        ),
        "selected_package_bridge_join_bad_counts": json_safe_counter(
            bridge_join_bad
        ),
        "sample_missing": samples,
        "sample_scorecard_provenance_bad": scorecard_provenance_samples,
        "sample_compact_scorecard_projection_bad": (
            compact_scorecard_projection_samples
        ),
        "sample_package_displacement_quality_bad": (
            package_displacement_quality_samples
        ),
        "sample_reallocation_terminal_disposition_bad": (
            reallocation_terminal_disposition_samples
        ),
        "sample_dynamic_fillability_bad": dynamic_fillability_samples,
        "sample_executable_authority_leaks": executable_leak_samples,
        "sample_selected_package_bridge_join_bad": bridge_join_samples,
    }


def scan_broad_order_trade_cost_authority(paths: dict[str, Path]) -> dict[str, Any]:
    counts: Counter[str] = Counter()
    bad_counts: Counter[str] = Counter()
    sample_bad: list[dict[str, Any]] = []

    def optional_float(value: Any) -> float | None:
        try:
            return float(value)
        except (TypeError, ValueError):
            return None

    for ledger_name, path in paths.items():
        if not path.exists():
            bad_counts[f"{ledger_name}:missing"] += 1
            continue
        for line in iter_text_lines_with_retries(path):
            if not line.strip():
                continue
            row = json.loads(line)
            counts[f"{ledger_name}_rows"] += 1
            status = str(row.get("pretrade_cost_packet_status") or "").upper()
            authority_value = None
            for key in (
                "cost_authority",
                "pretrade_cost_model_authority",
                "execution_cost_authority",
            ):
                value = row.get(key)
                if value not in (None, ""):
                    authority_value = value
                    break
            authority = str(authority_value or "")
            source_gap_status = str(row.get("cost_source_gap_status") or "")
            fallback_is_authority = bool(
                row.get("candidate_cost_r_fallback_is_authority", False)
            )
            order_status = str(row.get("order_status") or "")
            materialized_execution_row = bool(
                ledger_name == "trade"
                or order_status
                in {
                    "filled",
                    "pending_accepted",
                    "accepted_not_filled_pending_until_expiry",
                    "expired_unfilled",
                }
                or row.get("simulated_order_id") not in (None, "")
                or row.get("simulated_trade_id") not in (None, "")
            )
            cost_refused_or_source_gap = bool(
                status == "REFUSED"
                or source_gap_status
                not in {"", "source_bound_cost_authority_present"}
                or fallback_is_authority
                or row.get("broker_cost_packet_refused") is True
                or row.get("source_gap_cost_fallback_blocked") is True
                or row.get("missed_source_gap_cost_fallback_blocked") is True
                or row.get("cost_authority_order_materialization_blocked") is True
                or (
                    row.get("broker_pretrade_cost_executable") is False
                    and bool(row.get("broker_pretrade_cost_executable_block_reason"))
                )
            )
            if materialized_execution_row and cost_refused_or_source_gap:
                bad_counts[f"{ledger_name}:cost_refused_or_source_gap_materialized"] += 1
                if status == "REFUSED":
                    bad_counts[f"{ledger_name}:materialized_pretrade_cost_refused"] += 1
                if fallback_is_authority:
                    bad_counts[
                        f"{ledger_name}:materialized_candidate_cost_fallback_authority"
                    ] += 1
                if source_gap_status not in {"", "source_bound_cost_authority_present"}:
                    bad_counts[
                        f"{ledger_name}:materialized_cost_source_gap:{source_gap_status}"
                    ] += 1
                if len(sample_bad) < 10:
                    sample_bad.append(
                        {
                            "ledger": ledger_name,
                            "candidate_id": row.get("candidate_id"),
                            "simulated_order_id": row.get("simulated_order_id"),
                            "simulated_trade_id": row.get("simulated_trade_id"),
                            "symbol": row.get("symbol"),
                            "order_status": row.get("order_status"),
                            "pretrade_cost_packet_status": status or None,
                            "cost_source_gap_status": source_gap_status or None,
                            "candidate_cost_r_fallback_is_authority": fallback_is_authority,
                            "reasons": ["cost_refused_or_source_gap_materialized"],
                        }
                    )
            if ledger_name == "order" and order_status in {
                "risk_rejected",
                "execution_manager_blocked",
            }:
                continue
            if not row_cost_authority_executable_claim(row, ledger_name=ledger_name):
                counts[f"{ledger_name}_diagnostic_or_non_executable_rows"] += 1
                continue
            pending_order_intent_awaiting_terminal_fill = bool(
                ledger_name == "order"
                and order_status == "pending_accepted"
                and row.get("is_terminal_order_event") is not True
                and row.get("entry_fill_executable") is not True
                and row.get("fill_status") in (None, "")
            )
            unresolved_fill_realism_reasons = fill_realism_authority_reasons(row)
            fill_realism_reasons = (
                [
                    reason
                    for reason in unresolved_fill_realism_reasons
                    if reason != "executable_fill_realism_class_missing"
                ]
                if pending_order_intent_awaiting_terminal_fill
                else unresolved_fill_realism_reasons
            )
            if (
                pending_order_intent_awaiting_terminal_fill
                and "executable_fill_realism_class_missing"
                in unresolved_fill_realism_reasons
            ):
                counts["order_pending_intent_awaiting_terminal_fill_realism_rows"] += 1
            if fill_realism_reasons:
                bad_counts[f"{ledger_name}:fill_realism_authority_leak"] += 1
                for reason in fill_realism_reasons:
                    bad_counts[f"{ledger_name}:{reason}"] += 1
                if len(sample_bad) < 10:
                    sample_bad.append(
                        {
                            "ledger": ledger_name,
                            "candidate_id": row.get("candidate_id"),
                            "simulated_order_id": row.get("simulated_order_id"),
                            "simulated_trade_id": row.get("simulated_trade_id"),
                            "symbol": row.get("symbol"),
                            "order_status": row.get("order_status"),
                            "fill_realism_class": row.get("fill_realism_class"),
                            "reasons": fill_realism_reasons,
                        }
                    )
            current_price_leak_reasons = current_price_authority_leak_reasons(row)
            if current_price_leak_reasons:
                bad_counts[f"{ledger_name}:current_price_authority_leak"] += 1
                for reason in current_price_leak_reasons:
                    bad_counts[f"{ledger_name}:{reason}"] += 1
                if len(sample_bad) < 10:
                    sample_bad.append(
                        {
                            "ledger": ledger_name,
                            "candidate_id": row.get("candidate_id"),
                            "simulated_order_id": row.get("simulated_order_id"),
                            "simulated_trade_id": row.get("simulated_trade_id"),
                            "symbol": row.get("symbol"),
                            "order_status": row.get("order_status"),
                            "reasons": current_price_leak_reasons,
                        }
                    )
            if ledger_name == "oracle":
                continue
            reasons = []
            reasons.extend(
                f"candidate_decision_quality:{issue}"
                for issue in default_confidence_provenance_issues(row)
            )
            if status != "PASSED":
                reasons.append(f"pretrade_cost_packet_status:{status or 'missing'}")
            if authority != "broker_calibrated_replay_cost":
                reasons.append(f"cost_authority:{authority or 'missing'}")
            if source_gap_status != "source_bound_cost_authority_present":
                reasons.append(
                    f"cost_source_gap_status:{source_gap_status or 'missing'}"
                )
            if fallback_is_authority:
                reasons.append("candidate_cost_r_fallback_is_authority")
            if ledger_name == "trade":
                net_cost_scope = str(row.get("net_cost_scope") or "")
                rebased_marketable_limit_scope = (
                    net_cost_scope
                    == "broker_calibrated_pretrade_cost_rebased_to_effective_fill_r_not_close_side_all_in"
                    and (
                        row.get(
                            "marketable_limit_cost_authority_rebased_to_effective_fill_geometry"
                        )
                        is True
                        or row.get(
                            "marketable_limit_cost_r_rebased_to_effective_fill_geometry"
                        )
                        is True
                    )
                )
                if net_cost_scope not in {
                    "broker_pretrade_plus_optional_fallback_surcharge_not_close_side_all_in",
                } and not rebased_marketable_limit_scope:
                    reasons.append(f"net_cost_scope:{net_cost_scope or 'missing'}")
                close_side_status = str(row.get("close_side_all_in_cost_status") or "")
                if close_side_status not in {
                    "not_joined_in_replay_net_proxy_r",
                    "close_side_all_in_cost_joined",
                }:
                    reasons.append(
                        f"close_side_all_in_cost_status:{close_side_status or 'missing'}"
                    )
                if (
                    close_side_status == "close_side_all_in_cost_joined"
                    and row.get("close_side_all_in_cost_joined") is not True
                ):
                    reasons.append("close_side_all_in_cost_join_overclaimed")
                final_r = optional_float(row.get("final_r"))
                expected_cost_r = optional_float(row.get("expected_cost_r"))
                net_proxy_r = optional_float(row.get("net_proxy_r"))
                entry_fill_terminal_r_unscoreable = bool(
                    row.get("entry_fill_executable") is True
                    and row.get("terminal_r_scoreable") is False
                )
                if (
                    entry_fill_terminal_r_unscoreable
                    and final_r is None
                    and expected_cost_r is not None
                    and net_proxy_r is None
                ):
                    counts[
                        "trade_entry_fill_terminal_r_unscoreable_arithmetic_not_applicable_rows"
                    ] += 1
                elif final_r is None or expected_cost_r is None or net_proxy_r is None:
                    reasons.append("net_proxy_arithmetic_missing_fields")
                elif abs(net_proxy_r - (final_r - expected_cost_r)) > 1e-7:
                    reasons.append("net_proxy_r_not_final_r_minus_expected_cost_r")
            if reasons:
                bad_counts[f"{ledger_name}:weak_cost_authority"] += 1
                for reason in reasons:
                    bad_counts[f"{ledger_name}:{reason}"] += 1
                if len(sample_bad) < 10:
                    sample_bad.append(
                        {
                            "ledger": ledger_name,
                            "candidate_id": row.get("candidate_id"),
                            "simulated_order_id": row.get("simulated_order_id"),
                            "simulated_trade_id": row.get("simulated_trade_id"),
                            "symbol": row.get("symbol"),
                            "order_status": row.get("order_status"),
                            "reasons": reasons,
                        }
                    )
    return {
        "paths": {name: str(path) for name, path in paths.items()},
        "row_counts": json_safe_counter(counts),
        "bad_counts": json_safe_counter(bad_counts),
        "sample_bad": sample_bad,
    }


def scan_broad_missed_opportunity_semantics(path: Path) -> dict[str, Any]:
    counts: Counter[str] = Counter()
    bad_counts: Counter[str] = Counter()
    sample_bad: list[dict[str, Any]] = []
    def _present(value: Any) -> bool:
        return value not in (None, "", [], {})

    def _truthy(value: Any) -> bool:
        if isinstance(value, bool):
            return value
        return str(value or "").strip().lower() in {"1", "true", "yes", "y"}

    if not path.exists():
        return {
            "path": str(path),
            "row_counts": {},
            "bad_counts": {"missed:missing": 1},
            "sample_bad": [],
            "scan_truncated": False,
        }
    for row_index, line in enumerate(iter_text_lines_with_retries(path), start=1):
        if not line.strip():
            continue
        row = json.loads(line)
        counts["missed_rows"] += 1
        reasons: list[str] = []
        reasons.extend(
            f"candidate_decision_quality:{issue}"
            for issue in default_confidence_provenance_issues(row)
        )
        reasons.extend(
            f"candidate_decision_quality:{issue}"
            for issue in confidence_source_omission_issues(row)
        )
        ordered_status = str(row.get("ordered_path_status") or "")
        is_counterfactual = "counterfactual" in ordered_status or str(
            row.get("miss_reason") or ""
        ).endswith("_counterfactual")
        unexecuted_missed_row = bool(
            row.get("order_status") == "not_sent_missed_opportunity"
            or not _truthy(row.get("executable_finalized"))
            or not _truthy(row.get("missed_row_executable_finalized"))
        )
        if unexecuted_missed_row:
            counts["unexecuted_missed_rows"] += 1
            for field in ("gross_r", "net_proxy_r", "net_r", "final_r", "cash_pnl"):
                if _present(row.get(field)):
                    reasons.append(
                        f"unexecuted_missed_generic_pnl_present:{field}"
                    )
            if row.get("missed_opportunity_headline_r_scoreable") is True:
                reasons.append("unexecuted_missed_headline_r_scoreable_true")
            if (
                str(row.get("missed_opportunity_r_scoreability_status") or "")
                == "headline_r_scoreable"
            ):
                reasons.append(
                    "unexecuted_missed_scoreability_status_headline_r_scoreable"
                )
        if is_counterfactual:
            for field in ("gross_r", "net_proxy_r", "net_r", "final_r", "cash_pnl"):
                if _present(row.get(field)):
                    reasons.append(
                        f"counterfactual_missed_generic_pnl_present:{field}"
                    )
            if row.get("profit_harvest_mfe_capture_replay_exit") not in (
                None,
                "",
                [],
                {},
            ):
                reasons.append(
                    "counterfactual_missed_generic_profit_harvest_exit_present"
                )
            if row.get("profit_harvest_mfe_capture_replay_bound") is True:
                reasons.append(
                    "counterfactual_missed_generic_profit_harvest_bound_true"
                )
            if (
                row.get("counterfactual_gross_r") in (None, "", [], {})
                and row.get("opportunity_gross_r") in (None, "", [], {})
                and row.get("policy_gross_r") not in (None, "", [], {})
            ):
                reasons.append("counterfactual_missed_prefixed_gross_r_missing")
        if row.get("missed_cost_executable_opportunity_scoreable") is True:
            order_executable_flag = row_package_replay_order_executable_flag(row)
            if not value_bool_true(order_executable_flag):
                reasons.append(
                    "missed_cost_executable_scoreable_without_order_executable_authority"
                )
            if not row_package_replay_order_executable_source(row):
                reasons.append(
                    "missed_cost_executable_scoreable_order_authority_source_missing"
                )
        for reason in reasons:
            bad_counts[f"missed:{reason}"] += 1
        if reasons and len(sample_bad) < 8:
            sample_bad.append(
                {
                    "row_number": row_index,
                    "candidate_id": row.get("candidate_id"),
                    "miss_reason": row.get("miss_reason"),
                    "ordered_path_status": ordered_status,
                    "reasons": reasons,
                }
            )
    return {
        "path": str(path),
        "row_counts": json_safe_counter(counts),
        "bad_counts": json_safe_counter(bad_counts),
        "sample_bad": sample_bad,
        "scan_truncated": False,
        "scan_sample_max_rows": None,
    }


FULL_RISK_LADDER_TRUE_FIELDS = (
    "signed_authority_valid",
    "broker_cost_passed",
    "source_complete",
    "fill_floor_resolved_or_empty",
    "full_risk_allowed",
    "full_risk_applied",
)

FULL_RISK_NAMESPACE_ACTION_FIELDS = (
    "risk_expression_effective_action",
    "effective_selector_action",
    "effective_risk_decision",
    "admission_risk_class",
    "effective_admission_risk_class",
)

FULL_RISK_NAMESPACE_BLOCKING_ACTIONS = {
    "open-reduced-risk",
    "reduce-risk",
    "reject",
    "source-required",
}


def scan_broad_risk_expression_ladder_authority(
    paths: Mapping[str, Path],
) -> dict[str, Any]:
    """Fail risk-expression rows that hide predecision signing or sizing truth."""

    counts: Counter[str] = Counter()
    tier_counts: Counter[str] = Counter()
    bad_counts: Counter[str] = Counter()
    sample_bad: list[dict[str, Any]] = []

    def ladder_value(row: Mapping[str, Any], ladder: Mapping[str, Any], key: str) -> Any:
        return first_present_mapping_value(row, (f"risk_expression_ladder_{key}", key)) or ladder.get(key)

    def ladder_list(value: Any) -> list[Any]:
        if value is None:
            return []
        if isinstance(value, list):
            return value
        if isinstance(value, tuple):
            return list(value)
        return [value]

    def _risk_expression_reduced_row_reasons(
        row: Mapping[str, Any],
        ladder: Mapping[str, Any],
        tier_causes: Sequence[str],
    ) -> list[str]:
        reasons: list[str] = []
        full_risk_failures = [
            str(item).strip()
            for item in ladder_list(
                first_present_mapping_value(
                    row,
                    (
                        "package_risk_expression_full_risk_failures",
                        "full_risk_failures",
                    ),
                )
                or ladder.get("full_risk_failures")
            )
            if str(item).strip()
        ]
        all_causes = set(tier_causes) | set(full_risk_failures)
        signed_or_package_row = bool(
            value_bool_true(
                first_present_mapping_value(
                    row,
                    (
                        "package_risk_expression_signed_authority_valid",
                        "package_new_entry_authority_valid",
                    ),
                )
            )
            or value_bool_true(ladder.get("signed_authority_valid"))
            or value_bool_true(ladder.get("signed_package_authority_valid"))
        )
        if not signed_or_package_row:
            return reasons
        risk_pct_basis = numeric_or_none(
            first_present_mapping_value(
                row,
                (
                    "risk_pct_basis",
                    "risk_reduction_basis_pct",
                    "full_risk_counterfactual_risk_pct",
                ),
            )
        )
        final_risk_pct = numeric_or_none(
            first_present_mapping_value(
                row,
                (
                    "runtime_final_risk_pct",
                    "final_approved_risk_pct",
                    "approved_risk_pct",
                    "risk_pct",
                ),
            )
        )
        risk_pct_provenance = first_present_mapping_value(
            row,
            ("risk_pct_provenance", "risk_pct_basis_source", "risk_pct_final_source"),
        )
        if ledger_name in {"order", "trade"}:
            if risk_pct_basis is None or risk_pct_basis <= 0:
                reasons.append("reduced_ladder_risk_pct_basis_missing")
            if final_risk_pct is None or final_risk_pct <= 0:
                reasons.append("reduced_ladder_final_risk_pct_missing")
            if risk_pct_provenance in (None, "", [], {}):
                reasons.append("reduced_ladder_risk_pct_provenance_missing")
        if "execution_fillability_below_full_risk_floor" in all_causes:
            fill_probability = numeric_or_none(
                first_present_mapping_value(
                    row,
                    (
                        "package_risk_expression_execution_fill_probability",
                        "execution_fill_probability",
                        "predecision_limit_fillability_probability",
                    ),
                )
            )
            fill_floor = numeric_or_none(
                first_present_mapping_value(
                    row,
                    (
                        "package_risk_expression_execution_fill_probability_full_risk_floor",
                        "risk_expression_ladder_execution_fill_probability_full_risk_floor",
                    ),
                )
            )
            if fill_probability is None:
                reasons.append("reduced_ladder_fillability_value_missing")
            if fill_floor is None or fill_floor <= 0:
                reasons.append("reduced_ladder_fillability_floor_missing")
        return reasons

    for ledger_name, path in paths.items():
        if not path.exists():
            bad_counts[f"{ledger_name}:missing"] += 1
            continue
        for row_index, line in enumerate(iter_text_lines_with_retries(path), start=1):
            if not line.strip():
                continue
            row = json.loads(line)
            counts[f"{ledger_name}_rows"] += 1
            if not row_cost_authority_executable_claim(row, ledger_name=ledger_name):
                counts[f"{ledger_name}_diagnostic_or_non_executable_rows"] += 1
                continue
            ladder = parse_mapping(row.get("risk_expression_ladder"))
            tier = str(
                row.get("risk_expression_ladder_tier")
                or ladder.get("ladder_tier")
                or ladder.get("tier")
                or ""
            ).strip().lower().replace("_", "-")
            if not tier:
                counts[f"{ledger_name}_missing_ladder_tier_rows"] += 1
                continue
            tier_counts[f"{ledger_name}:{tier}"] += 1
            tier_causes = [
                str(cause).strip()
                for cause in ladder_list(
                    row.get("risk_expression_ladder_tier_causes")
                    or ladder.get("tier_causes")
                )
                if str(cause).strip()
            ]
            scheduler_priority_tier_value = ladder_value(
                row, ladder, "scheduler_priority_tier"
            )
            try:
                scheduler_priority_tier = int(float(scheduler_priority_tier_value))
            except (TypeError, ValueError):
                scheduler_priority_tier = None
            if (
                tier == "reduced"
                and scheduler_priority_tier == 0
                and "scheduler_priority_reduced_tier" in tier_causes
            ):
                bad_counts[
                    f"{ledger_name}:reduced_ladder_stale_scheduler_priority_cause"
                ] += 1
                if len(sample_bad) < 10:
                    sample_bad.append(
                        {
                            "ledger": ledger_name,
                            "row_number": row_index,
                            "candidate_id": row.get("candidate_id"),
                            "simulated_order_id": row.get("simulated_order_id"),
                            "simulated_trade_id": row.get("simulated_trade_id"),
                            "symbol": row.get("symbol"),
                            "decision_time_utc": row.get("decision_time_utc"),
                            "risk_expression_ladder_tier": tier,
                            "reasons": [
                                "reduced_ladder_stale_scheduler_priority_cause"
                            ],
                        }
                    )
            if tier == "reduced":
                reduced_reasons = _risk_expression_reduced_row_reasons(
                    row,
                    ladder,
                    tier_causes,
                )
                if reduced_reasons:
                    bad_counts[f"{ledger_name}:reduced_ladder_authority_bad"] += 1
                    for reason in reduced_reasons:
                        bad_counts[f"{ledger_name}:{reason}"] += 1
                    if len(sample_bad) < 10:
                        sample_bad.append(
                            {
                                "ledger": ledger_name,
                                "row_number": row_index,
                                "candidate_id": row.get("candidate_id"),
                                "simulated_order_id": row.get("simulated_order_id"),
                                "simulated_trade_id": row.get("simulated_trade_id"),
                                "symbol": row.get("symbol"),
                                "decision_time_utc": row.get("decision_time_utc"),
                                "risk_expression_ladder_tier": tier,
                                "reasons": reduced_reasons,
                            }
                        )
            if tier != "full":
                continue
            counts[f"{ledger_name}_full_risk_ladder_rows"] += 1
            reasons: list[str] = []
            for field in FULL_RISK_LADDER_TRUE_FIELDS:
                value = ladder_value(row, ladder, field)
                if value_bool_true(value):
                    continue
                if value in (None, "", [], {}):
                    reasons.append(f"full_risk_ladder_signing_condition_missing:{field}")
                else:
                    reasons.append(f"full_risk_ladder_signing_condition_false:{field}")
            top_rank_status = str(
                ladder_value(row, ladder, "scheduler_top_rank_status") or ""
            ).strip().lower()
            if top_rank_status and top_rank_status not in {
                "final_selected_top_rank",
                "runtime_finalizer_selected_top_rank",
                "scheduler_selected_top_rank",
                "deferred_to_finalizer_rank",
            }:
                reasons.append(
                    f"full_risk_ladder_scheduler_top_rank_status_invalid:{top_rank_status}"
                )
            namespace_actions: dict[str, str] = {}
            for field in FULL_RISK_NAMESPACE_ACTION_FIELDS:
                value = ladder_value(row, ladder, field)
                action = canonical_selector_action(value)
                if not action:
                    continue
                namespace_actions[field] = action
                if action in FULL_RISK_NAMESPACE_BLOCKING_ACTIONS:
                    reasons.append(
                        f"full_risk_namespace_action_not_trade:{field}:{action}"
                    )
            if reasons:
                bad_counts[f"{ledger_name}:full_risk_ladder_signing_condition_bad"] += 1
                for reason in reasons:
                    bad_counts[f"{ledger_name}:{reason}"] += 1
                if len(sample_bad) < 10:
                    sample_bad.append(
                        {
                            "ledger": ledger_name,
                            "row_number": row_index,
                            "candidate_id": row.get("candidate_id"),
                            "simulated_order_id": row.get("simulated_order_id"),
                            "simulated_trade_id": row.get("simulated_trade_id"),
                            "symbol": row.get("symbol"),
                            "decision_time_utc": row.get("decision_time_utc"),
                            "risk_expression_ladder_tier": tier,
                            "namespace_actions": namespace_actions,
                            "reasons": reasons,
                        }
                    )
    return {
        "paths": {name: str(path) for name, path in paths.items()},
        "row_counts": json_safe_counter(counts),
        "tier_counts": json_safe_counter(tier_counts),
        "bad_counts": json_safe_counter(bad_counts),
        "sample_bad": sample_bad,
    }


def scan_source_bound_parity_ledger(path: Path) -> dict[str, Any]:
    """Validate the source-bound parity ledger with a bounded-memory full scan."""

    counts: Counter[str] = Counter()
    row_type_counts: Counter[str] = Counter()
    profile_label_counts: dict[str, Counter[str]] = defaultdict(Counter)
    profile_metrics: dict[str, Counter[str]] = defaultdict(Counter)
    exact_window_profile_metrics: dict[str, dict[str, float]] = defaultdict(
        lambda: defaultdict(float)
    )
    bad_counts: Counter[str] = Counter()
    sample_bad: list[dict[str, Any]] = []

    def _float(value: Any) -> float:
        try:
            return float(value or 0.0)
        except (TypeError, ValueError):
            return 0.0

    def _record_bad(reason: str, row_index: int, row: Mapping[str, Any]) -> None:
        bad_counts[reason] += 1
        if len(sample_bad) >= 10:
            return
        sample_bad.append(
            {
                "row_number": row_index,
                "row_type": row.get("row_type"),
                "broad_replay_profile": row.get("broad_replay_profile"),
                "execution_leakage_label": row.get("execution_leakage_label"),
                "source_member_id": row.get("source_member_id"),
                "candidate_id": row.get("candidate_id"),
                "reason": reason,
            }
        )

    if not path.exists() or path.stat().st_size <= 0:
        return {
            "path": str(path),
            "exists": False,
            "row_count": 0,
            "row_type_counts": {},
            "profile_label_counts": {},
            "profile_metrics": {},
            "bad_counts": {"source_bound_parity_ledger_missing": 1},
            "sample_bad": [],
        }

    try:
        for row_index, line in enumerate(iter_text_lines_with_retries(path), start=1):
            if not line.strip():
                continue
            row = json.loads(line)
            counts["row_count"] += 1
            row_type = str(row.get("row_type") or "unknown")
            row_type_counts[row_type] += 1
            if row_type != "source_member_axis_to_executable_replay":
                continue

            profile = str(row.get("broad_replay_profile") or "unknown")
            label = str(row.get("execution_leakage_label") or "unknown")
            profile_label_counts[profile][label] += 1
            exact_metrics = exact_window_profile_metrics[profile]

            metrics = profile_metrics[profile]
            metrics["source_member_axis_rows"] += 1
            broad_generated = (
                row.get("broad_replay_candidate_generated") is True
                or row.get("candidate_generation_label") == "candidate_generated"
            )
            bridge_generated = (
                row.get("selected_package_bridge_candidate_generated") is True
            )
            if broad_generated:
                metrics["broad_replay_candidate_generated_axis_rows"] += 1
            if bridge_generated:
                metrics["selected_package_bridge_candidate_generated_axis_rows"] += 1
            metrics["candidate_generated_axis_rows"] += int(
                broad_generated or bridge_generated
            )
            source_bound_r = _float(row.get("source_bound_r"))
            package_source_bound_r = _float(row.get("package_source_bound_r"))
            effective_source_bound_r = _float(row.get("effective_source_bound_r"))
            effective_package_source_bound_r = _float(
                row.get("effective_package_source_bound_r")
            )
            diagnostic_source_bound_r = _float(row.get("diagnostic_source_bound_r"))
            diagnostic_package_source_bound_r = _float(
                row.get("diagnostic_package_source_bound_r")
            )
            if (
                row.get("source_bound_r_additive_allowed") is not False
                or row.get("source_bound_r_evidence_class")
                != B7_5_SOURCE_BOUND_SIGNAL_EVIDENCE_CLASS
            ):
                _record_bad(
                    "source_bound_signal_additive_semantics_invalid",
                    row_index,
                    row,
                )
            scorecard_option_count = int(
                row.get("scheduler_option_present_count") or 0
            )
            scorecard_count = int(row.get("scorecard_selected_count") or 0)
            order_count = int(row.get("order_present_count") or 0)
            trade_count = int(row.get("trade_count") or 0)
            scorecard_axis = scorecard_option_count > 0
            order_axis = order_count > 0
            trade_axis = trade_count > 0
            exact_metrics["package_axis_rows_in_parity_scope"] += 1
            exact_metrics["package_axes_available_inside_replay_window"] += 1
            source_bound_values = (
                source_bound_r,
                package_source_bound_r,
                effective_source_bound_r,
                effective_package_source_bound_r,
            )
            if any(abs(value) > 1e-12 for value in source_bound_values):
                exact_metrics[
                    "source_bound_r_nonzero_package_axes_inside_replay_window"
                ] += 1
            if any(
                value > 1e-12
                for value in source_bound_values
            ):
                exact_metrics[
                    "source_bound_r_positive_package_axes_inside_replay_window"
                ] += 1
            if any(
                abs(value) > 1e-12
                for value in (
                    diagnostic_source_bound_r,
                    diagnostic_package_source_bound_r,
                )
            ):
                exact_metrics["package_axes_in_global_diagnostic_surface"] += 1
            if broad_generated or bridge_generated:
                exact_metrics["candidate_generated_axes_inside_replay_window"] += 1
            if scorecard_axis:
                exact_metrics["scorecard_present_axes_inside_replay_window"] += 1
                metrics["scorecard_present_axis_rows"] += 1
            if scorecard_count > 0:
                exact_metrics["scheduler_selected_axes_inside_replay_window"] += 1
                metrics["scheduler_selected_axis_rows"] += 1
            if order_axis:
                exact_metrics["order_present_axes_inside_replay_window"] += 1
                metrics["order_present_axis_rows"] += 1
            if scorecard_axis or order_axis:
                exact_metrics[
                    "scorecard_or_order_present_axes_inside_replay_window"
                ] += 1
            if trade_axis:
                exact_metrics["filled_trade_axes_inside_replay_window"] += 1
                metrics["filled_trade_axis_rows"] += 1
            exact_metrics["source_bound_r_available_inside_replay_window"] += (
                source_bound_r
            )
            exact_metrics[
                "non_additive_executable_gated_source_bound_signal_r_inside_replay_window"
            ] += source_bound_r
            exact_metrics[
                "package_source_bound_r_available_inside_replay_window"
            ] += package_source_bound_r
            exact_metrics[
                "non_additive_executable_gated_package_source_bound_signal_r_inside_replay_window"
            ] += package_source_bound_r
            exact_metrics[
                "diagnostic_global_source_bound_r_sum_not_denominator"
            ] += diagnostic_source_bound_r
            exact_metrics[
                "diagnostic_global_package_source_bound_r_sum_not_denominator"
            ] += diagnostic_package_source_bound_r
            exact_metrics[
                "axis_attributed_actual_executable_r_inside_replay_window"
            ] += _float(row.get("actual_r_sum"))
            exact_metrics["scorecard_selected_count_inside_replay_window"] += (
                scorecard_count
            )
            exact_metrics["order_present_count_inside_replay_window"] += order_count
            exact_metrics["trade_count_inside_replay_window"] += trade_count

            if label == "candidate_generated_selector_reject":
                for field in (
                    "scheduler_option_present_count",
                    "scorecard_selected_count",
                    "order_present_count",
                    "trade_count",
                    "missed_count",
                ):
                    if int(row.get(field) or 0) != 0:
                        _record_bad(
                            f"selector_reject_execution_field_nonzero:{field}",
                            row_index,
                            row,
                        )
                for field in (
                    "actual_r_sum",
                    "gross_r_sum",
                    "final_r_sum",
                    "cash_pnl_sum",
                    "risk_cash_sum",
                    "risk_pct_sum",
                    "missed_net_proxy_r_sum",
                ):
                    if abs(_float(row.get(field))) > 0.0000001:
                        _record_bad(
                            f"selector_reject_execution_r_nonzero:{field}",
                            row_index,
                            row,
                        )
                if int(row.get("blocked_counterfactual_missed_count") or 0) < 0:
                    _record_bad(
                        "selector_reject_blocked_counterfactual_count_invalid",
                        row_index,
                        row,
                    )

            if "not_scheduler_selected" in label:
                for field in (
                    "scorecard_selected_count",
                    "order_present_count",
                    "trade_count",
                ):
                    if int(row.get(field) or 0) != 0:
                        _record_bad(
                            f"not_scheduler_selected_execution_field_nonzero:{field}",
                            row_index,
                            row,
                        )
                for field in (
                    "actual_r_sum",
                    "gross_r_sum",
                    "final_r_sum",
                    "cash_pnl_sum",
                ):
                    if abs(_float(row.get(field))) > 0.0000001:
                        _record_bad(
                            f"not_scheduler_selected_execution_r_nonzero:{field}",
                            row_index,
                            row,
                        )
    except (json.JSONDecodeError, OSError, TimeoutError):
        bad_counts["source_bound_parity_ledger_unreadable"] += 1

    return {
        "path": str(path),
        "exists": True,
        "row_count": int(counts["row_count"]),
        "row_type_counts": json_safe_counter(row_type_counts),
        "profile_label_counts": {
            profile: json_safe_counter(label_counts)
            for profile, label_counts in sorted(profile_label_counts.items())
        },
        "profile_metrics": {
            profile: json_safe_counter(
                {
                    **metrics,
                    "candidate_not_generated_axis_rows": (
                        int(metrics["source_member_axis_rows"])
                        - int(metrics["candidate_generated_axis_rows"])
                    ),
                }
            )
            for profile, metrics in sorted(profile_metrics.items())
        },
        "exact_window_profile_metrics": {
            profile: {
                key: round(value, 12) if isinstance(value, float) else value
                for key, value in sorted(metrics.items())
            }
            for profile, metrics in sorted(exact_window_profile_metrics.items())
        },
        "bad_counts": json_safe_counter(bad_counts),
        "sample_bad": sample_bad,
    }


def scan_candidate_instance_parity_projection(path: Path) -> dict[str, Any]:
    """Full-scan the exact candidate-instance funnel with bounded row memory."""

    row_count = 0
    keys: set[str] = set()
    duplicate_key_count = 0
    stage_counts: Counter[str] = Counter()
    profile_stage_counts: dict[str, Counter[str]] = defaultdict(Counter)
    package_candidate_identity_match_status_counts: Counter[str] = Counter()
    bad_counts: Counter[str] = Counter()
    sample_bad: list[dict[str, Any]] = []

    def record(reason: str, row_number: int, row: Mapping[str, Any]) -> None:
        bad_counts[reason] += 1
        if len(sample_bad) < 10:
            sample_bad.append(
                {
                    "row_number": row_number,
                    "candidate_id": row.get("candidate_id"),
                    "candidate_instance_parity_key": row.get(
                        "candidate_instance_parity_key"
                    ),
                    "reason": reason,
                }
            )

    if not path.exists() or path.stat().st_size <= 0:
        return {
            "path": str(path),
            "exists": False,
            "row_count": 0,
            "unique_candidate_instance_parity_key_count": 0,
            "duplicate_candidate_instance_parity_key_count": 0,
            "stage_presence_counts": {},
            "profile_stage_presence_counts": {},
            "package_candidate_identity_match_status_counts": {},
            "bad_counts": {"candidate_instance_projection_missing": 1},
            "sample_bad": [],
        }

    try:
        for row_number, line in enumerate(
            iter_text_lines_with_retries(path),
            start=1,
        ):
            if not line.strip():
                continue
            row = json.loads(line)
            if not isinstance(row, Mapping):
                record("candidate_instance_projection_row_not_object", row_number, {})
                continue
            row_count += 1
            if row.get("schema") != (
                "gtos.final_moonshot.denominator_to_deployment."
                "candidate_instance_parity_projection.v1"
            ):
                record("candidate_instance_projection_schema_mismatch", row_number, row)
            if row.get("row_type") != "candidate_instance_parity_projection":
                record("candidate_instance_projection_row_type_mismatch", row_number, row)
            key = str(row.get("candidate_instance_parity_key") or "").strip()
            if not key or "@@" not in key:
                record("candidate_instance_projection_key_missing", row_number, row)
            elif key in keys:
                duplicate_key_count += 1
                record("candidate_instance_projection_key_duplicate", row_number, row)
            else:
                keys.add(key)
            profile = str(row.get("broad_replay_profile") or "unknown")
            package_candidate_identity_match_status_counts[
                str(row.get("package_candidate_identity_match_status") or "missing")
            ] += 1
            for stage, field in (
                ("candidate", "candidate_present"),
                ("scorecard", "scorecard_present"),
                ("scheduler_selected", "scheduler_selected"),
                ("order", "order_present"),
                ("trade", "trade_present"),
                ("missed", "missed_present"),
            ):
                present = int(row.get(field) is True)
                stage_counts[stage] += present
                profile_stage_counts[profile][stage] += present
            if row.get("candidate_present") is not True:
                record("candidate_instance_projection_candidate_absent", row_number, row)
            if row.get("trade_present") is True and row.get("order_present") is not True:
                record("candidate_instance_projection_trade_without_order", row_number, row)
            if row.get("order_present") is True and row.get("scheduler_selected") is not True:
                record("candidate_instance_projection_order_without_selection", row_number, row)
    except (json.JSONDecodeError, OSError, TimeoutError):
        bad_counts["candidate_instance_projection_unreadable"] += 1

    return {
        "path": str(path),
        "exists": True,
        "row_count": row_count,
        "unique_candidate_instance_parity_key_count": len(keys),
        "duplicate_candidate_instance_parity_key_count": duplicate_key_count,
        "stage_presence_counts": json_safe_counter(stage_counts),
        "profile_stage_presence_counts": {
            profile: json_safe_counter(counts)
            for profile, counts in sorted(profile_stage_counts.items())
        },
        "package_candidate_identity_match_status_counts": json_safe_counter(
            package_candidate_identity_match_status_counts
        ),
        "bad_counts": json_safe_counter(bad_counts),
        "sample_bad": sample_bad,
    }


PACKAGE_NEW_ENTRY_EXPECTED_SCOPE_BY_TARGET_INTENT = {
    "new_position": "selector_reduced_risk_to_scheduler_new_position",
    "same_direction_scale_in": (
        "selector_reduced_risk_to_scheduler_same_direction_scale_in"
    ),
    "replace_pending": "selector_reduced_risk_to_scheduler_replace_pending",
    "close_and_reverse": "selector_reduced_risk_to_scheduler_close_and_reverse",
}


def scan_package_new_entry_scope_target_parity(
    paths: Mapping[str, Path],
) -> dict[str, Any]:
    counts: Counter[str] = Counter()
    scope_target_counts: Counter[str] = Counter()
    bad_counts: Counter[str] = Counter()
    sample_bad: list[dict[str, Any]] = []

    def normalize_action(value: Any) -> str:
        return str(value or "").strip().lower().replace("-", "_").replace(" ", "_")

    for namespace, path in paths.items():
        if not path.exists() or path.stat().st_size <= 0:
            continue
        try:
            for row_index, line in enumerate(iter_text_lines_with_retries(path), start=1):
                if not line.strip():
                    continue
                row = json.loads(line)
                counts[f"{namespace}_rows"] += 1
                scope = str(row.get("package_new_entry_authority_scope") or "").strip()
                if not scope:
                    continue
                target = normalize_action(
                    row.get("package_new_entry_authority_target_action_intent")
                    or row.get("effective_action_intent")
                    or row.get("scheduler_materialization_action_intent")
                    or row.get("action_intent")
                )
                if not target:
                    continue
                counts[f"{namespace}_scoped_rows"] += 1
                scope_target_counts[f"{namespace}|{scope}|{target}"] += 1
                expected_scope = PACKAGE_NEW_ENTRY_EXPECTED_SCOPE_BY_TARGET_INTENT.get(
                    target
                )
                if not expected_scope or scope == expected_scope:
                    continue
                bad_counts[f"{namespace}:scope_target_mismatch:{target}"] += 1
                if len(sample_bad) < 12:
                    sample_bad.append(
                        {
                            "namespace": namespace,
                            "row_number": row_index,
                            "candidate_id": row.get("candidate_id")
                            or row.get("selected_candidate_id"),
                            "selected_candidate_id": row.get("selected_candidate_id"),
                            "scope": scope,
                            "target_action_intent": target,
                            "expected_scope": expected_scope,
                            "selector_action": row.get("selector_action"),
                            "selector_reason": row.get("selector_reason"),
                        }
                    )
        except (json.JSONDecodeError, OSError, TimeoutError):
            bad_counts[f"{namespace}:scope_target_scan_unreadable"] += 1

    return {
        "counts": json_safe_counter(counts),
        "scope_target_counts": json_safe_counter(scope_target_counts),
        "bad_counts": json_safe_counter(bad_counts),
        "sample_bad": sample_bad,
    }


