def order_executable_status_is_blocked(value: Any) -> bool:
    status = str(value or "").strip().lower()
    return bool(
        status in ORDER_EXECUTABLE_TRANSFER_BLOCKED_STATUSES
        or any(token in status for token in ORDER_EXECUTABLE_BLOCKED_STATUS_TOKENS)
    )


def order_executable_alias_values(
    row: Mapping[str, Any],
) -> Iterable[tuple[str, str, Any]]:
    surfaces: list[tuple[str, Mapping[str, Any]]] = [("root", row)]
    seen: set[int] = {id(row)}
    for surface_field in ORDER_EXECUTABLE_ALIAS_SURFACE_FIELDS:
        surface = parse_mapping(row.get(surface_field))
        if not surface or id(surface) in seen:
            continue
        seen.add(id(surface))
        surfaces.append((surface_field, surface))
    for path, surface in surfaces:
        for field in EFFECTIVE_ORDER_EXECUTABLE_DEMOTION_FIELDS:
            if field in surface:
                yield path, field, surface.get(field)


def explicit_preserved_order_executable_proposal_present(
    row: Mapping[str, Any],
) -> bool:
    return any(
        value_bool_true(row.get(field))
        for field in PRESERVED_ORDER_EXECUTABLE_PROPOSAL_FIELDS
    )


def preserved_order_executable_proposal_contract_reasons(
    row: Mapping[str, Any],
) -> list[str]:
    if not explicit_preserved_order_executable_proposal_present(row):
        return []
    reasons: list[str] = []
    status = str(
        row.get("package_replay_order_executable_transfer_status") or ""
    ).strip()
    blocker_class = str(
        row.get("package_replay_order_executable_final_blocker_class") or ""
    ).strip()
    blocker_reason = str(
        row.get("package_replay_order_executable_final_blocker_reason") or ""
    ).strip()
    if status not in {"final_blocked", "not_order_executable"}:
        reasons.append("preserved_proposal_exact_final_status_missing")
    if blocker_class not in ORDER_EXECUTABLE_TRANSFER_ALLOWED_BLOCKERS:
        reasons.append("preserved_proposal_exact_final_blocker_class_missing")
    if not blocker_reason:
        reasons.append("preserved_proposal_exact_final_blocker_reason_missing")
    elif blocker_reason == "risk_authority_bound_and_headroom_available":
        reasons.append("preserved_proposal_final_blocker_reason_is_success")
    if any(
        row.get(field) not in (None, "")
        for field in (
            "package_replay_order_executable_bound_order_id",
            "package_replay_order_executable_bound_trade_id",
        )
    ):
        reasons.append("preserved_proposal_has_bound_order_or_trade_id")

    action_intent = canonical_scheduler_action_intent(
        first_present_mapping_value(
            row,
            (
                "scheduler_materialization_action_intent",
                "selected_scheduler_action_class",
                "scheduler_action_class",
                "action_intent",
                "lifecycle_action",
            ),
        )
        or "new_position"
    )
    envelope = package_new_entry_authority_envelope_selection(
        row,
        action_intent=action_intent,
    )
    prefinal_runtime_trade_admission = (
        runtime_reduced_risk_trade_admission_contract_valid(
            row,
            executable_authority_stage="pre_finalization",
        )
    )
    if not prefinal_runtime_trade_admission and envelope.get("valid") is not True:
        reasons.append("preserved_proposal_selected_signed_payload_invalid")
    elif not prefinal_runtime_trade_admission:
        payload = envelope.get("payload")
        if not isinstance(payload, Mapping) or not value_bool_true(
            payload.get("package_replay_order_executable_candidate_use_allowed")
        ):
            reasons.append("preserved_proposal_signed_payload_order_claim_not_true")
    reasons.extend(
        f"preserved_proposal_member_axis_identity:{reason}"
        for reason in finalized_executable_member_axis_identity_reasons(
            row,
            executable_authority_stage="pre_finalization",
        )
    )
    reasons.extend(
        package_fill_floor_final_blocker_correspondence_reasons(
            row,
            package_fill_floor_unresolved_failure_reasons(row),
        )
    )
    return list(dict.fromkeys(reasons))


def effective_order_executable_demotion_reasons(
    row: Mapping[str, Any],
) -> list[str]:
    reasons: list[str] = []
    for path, field, value in order_executable_alias_values(row):
        if not value_bool_true(value):
            continue
        alias = field if path == "root" else f"{path}.{field}"
        reasons.append(f"effective_demotion_executable_alias_still_true:{alias}")
    return list(dict.fromkeys(reasons))


def blocked_status_executable_claim_reasons(
    row: Mapping[str, Any],
) -> list[str]:
    reasons: list[str] = []
    blocked_statuses = [
        (status_field, row.get(status_field))
        for status_field in ORDER_EXECUTABLE_BLOCKED_STATUS_FIELDS
        if order_executable_status_is_blocked(row.get(status_field))
    ]
    positive_approved_risk: tuple[str, Any] | None = None
    for field in (
        "final_approved_risk_pct",
        "scheduler_approved_risk_pct",
        "approved_risk_pct",
        "risk_decision_approved_risk_pct",
    ):
        value = row.get(field)
        numeric = numeric_or_none(value)
        if numeric is not None and math.isfinite(numeric) and numeric > 0.0:
            positive_approved_risk = (field, value)
            break
    if blocked_statuses and positive_approved_risk is not None:
        risk_field, risk_value = positive_approved_risk
        for blocker_field in (
            "package_replay_order_executable_final_blocker_reason",
            "order_executable_final_blocker_reason",
            "final_blocker_reason",
        ):
            blocker_reason = str(row.get(blocker_field) or "").strip()
            if blocker_reason != "approved_risk_pct_below_selected_cell_risk_pct":
                continue
            reasons.append(
                "positive_reduced_risk_misclassified_as_terminal_blocker:"
                f"{blocker_field}:{risk_field}:{risk_value}"
            )
    # A simulated order id identifies an attempted replay order, including an
    # attempt that was terminally blocked. Only an explicit executable binding
    # or a materialized trade is an executable claim.
    bound_claim = any(
        row.get(field) not in (None, "")
        for field in (
            "package_replay_order_executable_bound_order_id",
            "package_replay_order_executable_bound_trade_id",
            "simulated_trade_id",
        )
    )
    aliases = [
        (path, field, value)
        for path, field, value in order_executable_alias_values(row)
        if value_bool_true(value)
    ]
    if not aliases and not bound_claim:
        return list(dict.fromkeys(reasons))
    for status_field, status_value in blocked_statuses:
        reasons.append(
            f"blocked_status_executable_claim:{status_field}:{status_value}"
        )
        for path, field, value in aliases:
            alias = field if path == "root" else f"{path}.{field}"
            reasons.append(
                "blocked_status_executable_alias_claim:"
                f"{status_field}:{status_value}:{alias}:{value}"
            )
    return list(dict.fromkeys(reasons))


def terminal_r_final_live_claim_reasons(row: Mapping[str, Any]) -> list[str]:
    """Keep replay terminal R scoreable without promoting it to final/live truth."""

    statuses = {
        field: str(row.get(field) or "").strip().lower()
        for field in (
            "terminal_r_authority_status",
            "terminal_r_path_authority",
            "headline_result_authority_status",
        )
        if row.get(field) not in (None, "")
    }
    non_final_statuses = {
        field: status
        for field, status in statuses.items()
        if any(token in status for token in TERMINAL_R_NON_FINAL_STATUS_TOKENS)
    }
    if not non_final_statuses:
        return []
    reasons: list[str] = []
    for claim_field in TERMINAL_R_FINAL_LIVE_CLAIM_FIELDS:
        if not value_bool_true(row.get(claim_field)):
            continue
        status_detail = ",".join(
            f"{field}={status}" for field, status in sorted(non_final_statuses.items())
        )
        reasons.append(
            "terminal_r_non_final_evidence_claims_final_live_authority:"
            f"{claim_field}:{status_detail}"
        )
    return list(dict.fromkeys(reasons))


def row_order_executable_transfer_allowed(row: Mapping[str, Any]) -> bool | None:
    transfer_status = str(
        row.get("package_replay_order_executable_transfer_status") or ""
    ).strip()
    if order_executable_status_is_blocked(transfer_status):
        return False
    flag = row_package_replay_order_executable_flag(row)
    if flag is not None:
        if value_bool_true(flag):
            return True
        if value_bool_false(flag):
            return False
    return None


