def phase2_instance_completion_authority_issues(
    *,
    summary: Mapping[str, Any],
    completion_phase2_counts: Mapping[str, Any],
    phase2_proxy_target_label_rows: Sequence[Mapping[str, Any]],
) -> list[str]:
    issues: list[str] = []
    unique_instance_proxy_final_r: dict[str, float] = {}
    replay_instances_by_candidate_id: defaultdict[str, set[str]] = defaultdict(set)
    for row in phase2_proxy_target_label_rows:
        instance_key = str(row.get("replay_instance_join_key") or "").strip()
        if not instance_key:
            continue
        replay_candidate_id = str(row.get("replay_candidate_id") or "").strip()
        if replay_candidate_id:
            replay_instances_by_candidate_id[replay_candidate_id].add(instance_key)
        target_value = row.get("target_value") or {}
        if isinstance(target_value, Mapping):
            try:
                unique_instance_proxy_final_r[instance_key] = float(
                    target_value.get("counterfactual_final_r") or 0.0
                )
            except (TypeError, ValueError):
                unique_instance_proxy_final_r[instance_key] = 0.0

    unique_instance_final_r_sum = sum(unique_instance_proxy_final_r.values())
    unique_instance_count = len(unique_instance_proxy_final_r)
    repeated_candidate_count = sum(
        1 for keys in replay_instances_by_candidate_id.values() if len(keys) > 1
    )
    proxy_expected = {
        "phase2_proxy_target_unique_instance_final_r_sum": (
            unique_instance_final_r_sum,
            "completion_phase2_proxy_target_unique_instance_final_r_sum_mismatch",
            "phase2_proxy_target_summary_unique_instance_final_r_sum_mismatch",
        ),
        "phase2_proxy_target_instance_rows": (
            unique_instance_count,
            "completion_phase2_proxy_target_instance_rows_mismatch",
            "phase2_proxy_target_summary_instance_rows_mismatch",
        ),
        "phase2_proxy_target_repeated_candidate_id_count": (
            repeated_candidate_count,
            "completion_phase2_proxy_target_repeated_candidate_id_count_mismatch",
            "phase2_proxy_target_summary_repeated_candidate_id_count_mismatch",
        ),
    }
    for field, (expected, completion_issue, summary_issue) in proxy_expected.items():
        if isinstance(expected, float):
            if not nearly_equal(summary.get(field), expected):
                issues.append(summary_issue)
            if not nearly_equal(completion_phase2_counts.get(field), expected):
                issues.append(completion_issue)
        else:
            if summary.get(field) != expected:
                issues.append(summary_issue)
            if completion_phase2_counts.get(field) != expected:
                issues.append(completion_issue)
    authority_field = "phase2_proxy_target_unique_instance_final_r_sum_authority"
    if summary.get(authority_field) != "replay_instance_join_key_authority":
        issues.append("phase2_proxy_target_summary_unique_instance_final_r_sum_authority_missing")
    if completion_phase2_counts.get(authority_field) != "replay_instance_join_key_authority":
        issues.append("completion_phase2_proxy_target_unique_instance_final_r_sum_authority_missing")

    collapsed_fields = {
        "phase2_collapsed_unique_instance_proxy_final_r_sum": (
            "completion_phase2_collapsed_unique_instance_proxy_final_r_sum_mismatch",
            True,
        ),
        "phase2_collapsed_unique_replay_instance_count": (
            "completion_phase2_collapsed_unique_replay_instance_count_mismatch",
            False,
        ),
        "phase2_collapsed_repeated_candidate_id_count": (
            "completion_phase2_collapsed_repeated_candidate_id_count_mismatch",
            False,
        ),
    }
    for field, (issue, is_float) in collapsed_fields.items():
        if is_float:
            if not nearly_equal(completion_phase2_counts.get(field), float(summary.get(field) or 0.0)):
                issues.append(issue)
        elif completion_phase2_counts.get(field) != summary.get(field):
            issues.append(issue)
    collapsed_authority_field = "phase2_collapsed_unique_instance_proxy_final_r_sum_authority"
    if summary.get(collapsed_authority_field) != "replay_instance_join_key_authority":
        issues.append("phase2_collapsed_summary_unique_instance_proxy_final_r_sum_authority_missing")
    if completion_phase2_counts.get(collapsed_authority_field) != "replay_instance_join_key_authority":
        issues.append("completion_phase2_collapsed_unique_instance_proxy_final_r_sum_authority_missing")
    return issues


def stable_verified_utc(result: dict[str, Any]) -> str:
    path = ROUTE / "VERIFICATION_RESULT.json"
    if not path.exists():
        return utc_now()
    try:
        existing = read_json(path)
    except json.JSONDecodeError:
        return utc_now()
    old = {key: value for key, value in existing.items() if key != "verified_utc"}
    new = {key: value for key, value in result.items() if key != "verified_utc"}
    return existing.get("verified_utc") or utc_now() if old == new else utc_now()


