def phase2_m15_grid_all_symbol_existing_files() -> set[str]:
    summary = read_json_if_readable(
        ROUTE / "PHASE2_M15_GRID_ALL_SYMBOL_REPLAY_BRIDGE_SUMMARY.json"
    )
    zero_row_empty_ledger_summary_fields = {
        "_FILTERED_NON_EXECUTABLE_ORDER_LEDGER.jsonl": "filtered_non_executable_order_rows",
        "_FILTERED_NON_EXECUTABLE_TRADE_LEDGER.jsonl": "filtered_non_executable_trade_rows",
        "_ORDERED_PATH_ORACLE_LEDGER.jsonl": "oracle_rows",
        "_ORDER_LEDGER.jsonl": "order_rows",
        "_PROFIT_HARVEST_AUTHORITY_BLOCKER_LEDGER.jsonl": "profit_harvest_authority_blocker_rows",
        "_TRADE_LEDGER.jsonl": "trade_rows",
    }

    def empty_ledger_allowed(filename: str) -> bool:
        for suffix, field in zero_row_empty_ledger_summary_fields.items():
            if filename.endswith(suffix):
                return int(summary.get(field) or 0) == 0
        return False

    return {
        filename
        for filename in PHASE2_M15_GRID_ALL_SYMBOL_REQUIRED_FILES
        if (ROUTE / filename).exists()
        and (
            (ROUTE / filename).stat().st_size > 0
            or empty_ledger_allowed(filename)
        )
    }


def phase2_m15_grid_all_symbol_manifest_required_files(
    manifest: Mapping[str, Any],
) -> set[str]:
    valid_omitted = manifest_omitted_large_artifact_files(manifest)
    required = set(PHASE2_M15_GRID_ALL_SYMBOL_REQUIRED_FILES)
    required.update(
        filename
        for filename in PHASE2_M15_GRID_ALL_SYMBOL_OMITTABLE_LARGE_FILES
        if filename not in valid_omitted
    )
    return required


def manifest_omitted_large_artifact_files(manifest: Mapping[str, Any]) -> set[str]:
    omitted = manifest.get("omitted_large_artifacts")
    filenames: set[str] = set()
    if isinstance(omitted, Mapping):
        iterable: Iterable[Any] = omitted.values()
    elif isinstance(omitted, Sequence) and not isinstance(omitted, (str, bytes)):
        iterable = omitted
    else:
        iterable = ()
    for entry in iterable:
        if isinstance(entry, Mapping):
            filename = entry.get("file") or entry.get("filename") or entry.get("path")
            has_row_authority = bool(
                entry.get("row_count_authority")
                or entry.get("summary_row_count_authority")
            )
            has_reason = bool(entry.get("reason") or entry.get("omitted_reason"))
            if filename and has_row_authority and has_reason:
                    filenames.add(Path(str(filename)).name)
    return filenames


def manifest_listed_file_presence_issues(
    manifest: Mapping[str, Any],
    *,
    filename_prefix: str,
) -> list[str]:
    manifest_files = {
        Path(str(filename)).name
        for filename in (manifest.get("files") or [])
        if str(filename or "").strip()
    }
    omitted = manifest_omitted_large_artifact_files(manifest)
    issues: list[str] = []

    def allow_empty_jsonl_artifact(filename: str) -> bool:
        empty_ledger_summary_fields = {
            "_FILTERED_NON_EXECUTABLE_ORDER_LEDGER.jsonl": "filtered_non_executable_order_rows",
            "_FILTERED_NON_EXECUTABLE_TRADE_LEDGER.jsonl": "filtered_non_executable_trade_rows",
            "_ORDERED_PATH_ORACLE_LEDGER.jsonl": "oracle_rows",
            "_ORDER_LEDGER.jsonl": "order_rows",
            "_PROFIT_HARVEST_AUTHORITY_BLOCKER_LEDGER.jsonl": "profit_harvest_authority_blocker_rows",
            "_TRADE_LEDGER.jsonl": "trade_rows",
        }
        summary_field = None
        summary_name = None
        for suffix, field in empty_ledger_summary_fields.items():
            if filename.endswith(suffix):
                summary_field = field
                summary_name = filename.replace(suffix, "_SUMMARY.json")
                break
        if summary_field is None or summary_name is None:
            return False
        summary = read_json_if_readable(ROUTE / summary_name)
        if not summary:
            return False
        expected_rows = int(summary.get(summary_field) or 0)
        return expected_rows == 0

    for filename in sorted(
        name
        for name in manifest_files
        if name.startswith(filename_prefix) and name not in omitted
    ):
        path = ROUTE / filename
        if not path.exists():
            issues.append(f"manifest_listed_file_missing:{filename}")
        elif filename.endswith("_SUMMARY.json") and path.stat().st_size <= 0:
            issues.append(f"manifest_listed_summary_empty:{filename}")
        elif filename.endswith((".json", ".jsonl")) and path.stat().st_size <= 0:
            if allow_empty_jsonl_artifact(filename):
                continue
            issues.append(f"manifest_listed_json_artifact_empty:{filename}")
    return issues


def write_early_failed_verification_result(
    issues: Sequence[str],
    *,
    summary: Mapping[str, Any],
    completion: dict[str, Any],
    focused: dict[str, Any],
) -> int:
    result = {
        "schema": "gtos.final_moonshot.denominator_to_deployment.verification_result.v1",
        "verified_utc": utc_now(),
        "ok": False,
        "issue_count": len(issues),
        "issues": list(issues),
        "early_failure": True,
        "final_package_selected": summary.get("final_package_selected", False),
        "selected_package_replay_materialized": summary.get(
            "selected_package_replay_materialized",
            False,
        ),
        "selected_package_replay_denominator_selectable": summary.get(
            "selected_package_replay_denominator_selectable",
            False,
        ),
        "selected_package_replay_final_selectable": summary.get(
            "selected_package_replay_final_selectable",
            False,
        ),
        "live_trading_enabled": summary.get("live_trading_enabled", False),
        "model_training_allowed": summary.get("model_training_allowed", False),
        "phase2_final_package_selection_allowed": summary.get(
            "phase2_final_package_selection_allowed",
            False,
        ),
    }
    result["verified_utc"] = stable_verified_utc(result)
    write_json(ROUTE / "VERIFICATION_RESULT.json", result)
    verification = completion.setdefault("verification", {})
    verification["denominator_to_deployment_execution"] = "failed"
    write_json(ROUTE / "COMPLETION_AUDIT.json", completion)
    focused["status"] = "failed"
    focused["verification_result"] = {
        "ok": False,
        "issue_count": len(issues),
        "verified_utc": result["verified_utc"],
    }
    write_json(ROUTE / "FOCUSED_TEST_RESULT.json", focused)
    return 1


def main() -> int:
    issues: list[str] = []
    summary = read_json(ROUTE / "DENOMINATOR_TO_DEPLOYMENT_EXECUTION_SUMMARY.json")
    manifest = read_json(ROUTE / "OUTPUT_MANIFEST.json")
    completion = read_json(ROUTE / "COMPLETION_AUDIT.json")
    focused = read_json(ROUTE / "FOCUSED_TEST_RESULT.json")
    b7_5_source_window_contract = read_json_if_readable(
        ROUTE / "B7_5_EXTENDED_HISTORY_SOURCE_WINDOW_CONTRACT.json"
    )
    b7_5_extended_history_behavior = read_json_if_readable(
        ROUTE / "B7_5_EXTENDED_HISTORY_BEHAVIOR_SUMMARY.json"
    )
