    def replay_floor_parse_decision_time(value: Any) -> datetime | None:
        if not value:
            return None
        try:
            return datetime.fromisoformat(str(value).replace("Z", "+00:00"))
        except ValueError:
            return None

    def replay_floor_utc_session(value: Any) -> str | None:
        parsed = replay_floor_parse_decision_time(value)
        if parsed is None:
            return None
        if parsed.hour < 7:
            return "asia_utc"
        if parsed.hour < 13:
            return "london_utc"
        if parsed.hour < 21:
            return "ny_utc"
        return "rollover_utc"

    def replay_floor_unique(rows: list[dict[str, Any]], field: str) -> set[str]:
        return {str(row.get(field)) for row in rows if row.get(field)}

