    def _numeric_values(rows: Sequence[Mapping[str, Any]], field: str) -> list[float]:
        values: list[float] = []
        for row in rows:
            value = row.get(field)
            if isinstance(value, (int, float)):
                values.append(float(value))
        return values

    def _sum_field(rows: Sequence[Mapping[str, Any]], field: str) -> float:
        return round(sum(_numeric_values(rows, field)), 9)

    def _min_field(rows: Sequence[Mapping[str, Any]], field: str) -> float | None:
        values = _numeric_values(rows, field)
        return min(values) if values else None

    def _max_field(rows: Sequence[Mapping[str, Any]], field: str) -> float | None:
        values = _numeric_values(rows, field)
        return max(values) if values else None

    def _outcome_counts(rows: Sequence[Mapping[str, Any]], field: str) -> dict[str, int]:
        counts = {"win_rows": 0, "loss_rows": 0, "flat_rows": 0, "missing_rows": 0}
        for row in rows:
            value = row.get(field)
            if not isinstance(value, (int, float)):
                counts["missing_rows"] += 1
            elif value > 0:
                counts["win_rows"] += 1
            elif value < 0:
                counts["loss_rows"] += 1
            else:
                counts["flat_rows"] += 1
        return counts

